INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('regles/01-ne-jamais-decider-sous-pression','{"id":1,"number":"01","slug":"01-ne-jamais-decider-sous-pression","title":"Ne prenez jamais une décision importante sous pression.","summary":"L''urgence est l''un des outils les plus efficaces pour faire baisser votre vigilance.","detail":"Lorsqu''une personne, un message ou un site vous pousse à décider immédiatement, ralentissez volontairement. Vérifiez l''information par un autre canal et accordez-vous quelques minutes avant toute action irréversible.","categoryId":"cybersecurite","order":0,"subcategory":"","homeRank":0}','{"id":1,"number":"01","slug":"01-ne-jamais-decider-sous-pression","title":"Ne prenez jamais une décision importante sous pression.","summary":"L''urgence est l''un des outils les plus efficaces pour faire baisser votre vigilance.","detail":"Lorsqu''une personne, un message ou un site vous pousse à décider immédiatement, ralentissez volontairement. Vérifiez l''information par un autre canal et accordez-vous quelques minutes avant toute action irréversible.","categoryId":"cybersecurite","order":0,"subcategory":"","homeRank":0}',1,'2026-10-01T06:41:56.605Z','migration');
