INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('regles/02-verifiez-l-identite-avant-de-faire-confiance','{"id":2,"number":"02","slug":"02-verifiez-l-identite-avant-de-faire-confiance","title":"Vérifiez l''identité avant de faire confiance.","summary":"Un nom, un logo ou une photo ne prouvent jamais l''identité de votre interlocuteur.","detail":"Avant de transmettre une information sensible, de payer ou de modifier un accès, utilisez un moyen indépendant pour confirmer que vous parlez bien à la bonne personne ou à la bonne organisation.","categoryId":"cybersecurite","order":1,"subcategory":"","homeRank":0}','{"id":2,"number":"02","slug":"02-verifiez-l-identite-avant-de-faire-confiance","title":"Vérifiez l''identité avant de faire confiance.","summary":"Un nom, un logo ou une photo ne prouvent jamais l''identité de votre interlocuteur.","detail":"Avant de transmettre une information sensible, de payer ou de modifier un accès, utilisez un moyen indépendant pour confirmer que vous parlez bien à la bonne personne ou à la bonne organisation.","categoryId":"cybersecurite","order":1,"subcategory":"","homeRank":0}',1,'2026-10-01T06:41:56.605Z','migration');
