INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('regles/03-utilisez-un-mot-de-passe-unique-pour-chaque-service','{"id":3,"number":"03","slug":"03-utilisez-un-mot-de-passe-unique-pour-chaque-service","title":"Utilisez un mot de passe unique pour chaque service.","summary":"Un mot de passe réutilisé transforme une fuite isolée en risque généralisé.","detail":"Utilisez un gestionnaire de mots de passe pour générer et conserver des identifiants uniques. Si un service est compromis, les autres comptes restent ainsi protégés.","categoryId":"cybersecurite","order":2,"subcategory":"","homeRank":0}','{"id":3,"number":"03","slug":"03-utilisez-un-mot-de-passe-unique-pour-chaque-service","title":"Utilisez un mot de passe unique pour chaque service.","summary":"Un mot de passe réutilisé transforme une fuite isolée en risque généralisé.","detail":"Utilisez un gestionnaire de mots de passe pour générer et conserver des identifiants uniques. Si un service est compromis, les autres comptes restent ainsi protégés.","categoryId":"cybersecurite","order":2,"subcategory":"","homeRank":0}',1,'2026-10-01T06:41:56.605Z','migration');
