INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('regles/04-activez-la-double-authentification','{"id":4,"number":"04","slug":"04-activez-la-double-authentification","title":"Activez la double authentification.","summary":"Un mot de passe seul ne constitue plus une protection suffisante.","detail":"Activez la double authentification dès qu''elle est disponible, en privilégiant une application d''authentification ou une clé physique lorsque le service le permet.","categoryId":"cybersecurite","order":3,"subcategory":"","homeRank":0}','{"id":4,"number":"04","slug":"04-activez-la-double-authentification","title":"Activez la double authentification.","summary":"Un mot de passe seul ne constitue plus une protection suffisante.","detail":"Activez la double authentification dès qu''elle est disponible, en privilégiant une application d''authentification ou une clé physique lorsque le service le permet.","categoryId":"cybersecurite","order":3,"subcategory":"","homeRank":0}',1,'2026-10-01T06:41:56.605Z','migration');
