INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/questionnaire-etude-marche','{"kind":"guides","slug":"questionnaire-etude-marche","title":"Étude de marché : poser des questions qui éclairent","description":"Construire un questionnaire court sans orienter les réponses.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : décidez ce que vous cherchez à apprendre avant de rédiger vos questions.","sections":[{"title":"Partir d’une décision","paragraphs":["Voulez-vous choisir un lieu, comprendre un usage ou tester un prix ? Notez cet objectif. Écartez les questions dont la réponse ne changera aucune décision : un questionnaire long décourage les participants."]},{"title":"Interroger les bonnes personnes","paragraphs":["Recherchez des personnes correspondant à votre clientèle visée, au-delà de votre entourage. Variez les profils et les lieux de diffusion. Un grand nombre de réponses ne corrige pas un échantillon mal choisi."]},{"title":"Tester avant de diffuser","paragraphs":["Utilisez des phrases simples, une seule idée par question et des formulations neutres. Faites essayer le questionnaire à quelques personnes. À l’analyse, distinguez les résultats observés des conclusions que vous extrapolez."]}],"checklist":["Objectif écrit.","Public cible défini.","Questions testées et résultats contextualisés."],"sources":[{"kind":"reference","label":"Bpifrance Création — Réaliser un questionnaire","url":"https://bpifrance-creation.fr/encyclopedie/letude-marche/etapes/realiser-questionnaire-cadre-votre-etude-marche"}],"order":75,"subcategory":"","homeRank":0,"tagSlugs":["decisions","entreprendre"]}','{"kind":"guides","slug":"questionnaire-etude-marche","title":"Étude de marché : poser des questions qui éclairent","description":"Construire un questionnaire court sans orienter les réponses.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : décidez ce que vous cherchez à apprendre avant de rédiger vos questions.","sections":[{"title":"Partir d’une décision","paragraphs":["Voulez-vous choisir un lieu, comprendre un usage ou tester un prix ? Notez cet objectif. Écartez les questions dont la réponse ne changera aucune décision : un questionnaire long décourage les participants."]},{"title":"Interroger les bonnes personnes","paragraphs":["Recherchez des personnes correspondant à votre clientèle visée, au-delà de votre entourage. Variez les profils et les lieux de diffusion. Un grand nombre de réponses ne corrige pas un échantillon mal choisi."]},{"title":"Tester avant de diffuser","paragraphs":["Utilisez des phrases simples, une seule idée par question et des formulations neutres. Faites essayer le questionnaire à quelques personnes. À l’analyse, distinguez les résultats observés des conclusions que vous extrapolez."]}],"checklist":["Objectif écrit.","Public cible défini.","Questions testées et résultats contextualisés."],"sources":[{"kind":"reference","label":"Bpifrance Création — Réaliser un questionnaire","url":"https://bpifrance-creation.fr/encyclopedie/letude-marche/etapes/realiser-questionnaire-cadre-votre-etude-marche"}],"order":75,"subcategory":"","homeRank":0,"tagSlugs":["decisions","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
