INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/entretiens-clients','{"kind":"guides","slug":"entretiens-clients","title":"Entretiens clients : écouter avant de présenter son idée","description":"Comprendre les usages réels grâce à des échanges ouverts.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : cherchez à comprendre un problème avant de convaincre que votre solution est bonne.","sections":[{"title":"Faire raconter une situation","paragraphs":["Demandez comment la personne a résolu le problème la dernière fois : contexte, recherche, achat, difficulté. Un récit concret apporte davantage qu’un simple avis favorable sur une idée encore abstraite."]},{"title":"Laisser une place au désaccord","paragraphs":["Préparez des questions ouvertes et relancez sans suggérer la réponse. Notez les obstacles, les alternatives et les raisons de ne pas acheter. Évitez de transformer chaque entretien en démonstration commerciale."]},{"title":"Comparer les observations","paragraphs":["Regroupez les besoins qui reviennent et les différences entre profils. Ces entretiens qualitatifs éclairent les motivations ; ils ne mesurent pas à eux seuls la taille du marché. Testez ensuite vos hypothèses sur un public plus large."]}],"checklist":["Profils variés rencontrés.","Situations concrètes notées.","Hypothèses distinguées des faits."],"sources":[{"kind":"reference","label":"Bpifrance Création — Mener des entretiens","url":"https://bpifrance-creation.fr/encyclopedie/letude-marche/etapes/mener-entretiens-cadre-son-etude-marche"}],"order":76,"subcategory":"","homeRank":0,"tagSlugs":["decisions","entreprendre"]}','{"kind":"guides","slug":"entretiens-clients","title":"Entretiens clients : écouter avant de présenter son idée","description":"Comprendre les usages réels grâce à des échanges ouverts.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : cherchez à comprendre un problème avant de convaincre que votre solution est bonne.","sections":[{"title":"Faire raconter une situation","paragraphs":["Demandez comment la personne a résolu le problème la dernière fois : contexte, recherche, achat, difficulté. Un récit concret apporte davantage qu’un simple avis favorable sur une idée encore abstraite."]},{"title":"Laisser une place au désaccord","paragraphs":["Préparez des questions ouvertes et relancez sans suggérer la réponse. Notez les obstacles, les alternatives et les raisons de ne pas acheter. Évitez de transformer chaque entretien en démonstration commerciale."]},{"title":"Comparer les observations","paragraphs":["Regroupez les besoins qui reviennent et les différences entre profils. Ces entretiens qualitatifs éclairent les motivations ; ils ne mesurent pas à eux seuls la taille du marché. Testez ensuite vos hypothèses sur un public plus large."]}],"checklist":["Profils variés rencontrés.","Situations concrètes notées.","Hypothèses distinguées des faits."],"sources":[{"kind":"reference","label":"Bpifrance Création — Mener des entretiens","url":"https://bpifrance-creation.fr/encyclopedie/letude-marche/etapes/mener-entretiens-cadre-son-etude-marche"}],"order":76,"subcategory":"","homeRank":0,"tagSlugs":["decisions","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
