INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/swot-actions-prioritaires','{"kind":"guides","slug":"swot-actions-prioritaires","title":"SWOT : transformer un diagnostic en actions","description":"Relier forces, faiblesses, opportunités et menaces à des décisions.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : un tableau stratégique doit déboucher sur des choix concrets.","sections":[{"title":"Séparer intérieur et extérieur","paragraphs":["Les compétences ou les moyens de votre entreprise relèvent des forces et faiblesses. Les évolutions du marché et de la concurrence alimentent les opportunités et menaces. Ne mélangez pas ce que vous contrôlez et ce que vous observez."]},{"title":"Appuyer chaque idée sur un fait","paragraphs":["Remplacez « excellente qualité » par un élément vérifiable : retours clients, délais tenus ou défauts constatés. Une impression peut rester une hypothèse, à condition de la désigner ainsi."]},{"title":"Choisir une priorité","paragraphs":["Croisez une force avec une opportunité, puis une faiblesse avec une menace. Retenez quelques actions réalisables, avec une personne responsable et une échéance. Réexaminez le diagnostic quand le contexte change."]}],"checklist":["Constats documentés.","Facteurs internes et externes séparés.","Actions datées."],"sources":[{"kind":"reference","label":"Bpifrance Création — Analyse SWOT","url":"https://bpifrance-creation.fr/encyclopedie/letude-marche/outils-danalyse/swot-outil-danalyse-strategique"}],"order":77,"subcategory":"","homeRank":0,"tagSlugs":["decisions","entreprendre"]}','{"kind":"guides","slug":"swot-actions-prioritaires","title":"SWOT : transformer un diagnostic en actions","description":"Relier forces, faiblesses, opportunités et menaces à des décisions.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : un tableau stratégique doit déboucher sur des choix concrets.","sections":[{"title":"Séparer intérieur et extérieur","paragraphs":["Les compétences ou les moyens de votre entreprise relèvent des forces et faiblesses. Les évolutions du marché et de la concurrence alimentent les opportunités et menaces. Ne mélangez pas ce que vous contrôlez et ce que vous observez."]},{"title":"Appuyer chaque idée sur un fait","paragraphs":["Remplacez « excellente qualité » par un élément vérifiable : retours clients, délais tenus ou défauts constatés. Une impression peut rester une hypothèse, à condition de la désigner ainsi."]},{"title":"Choisir une priorité","paragraphs":["Croisez une force avec une opportunité, puis une faiblesse avec une menace. Retenez quelques actions réalisables, avec une personne responsable et une échéance. Réexaminez le diagnostic quand le contexte change."]}],"checklist":["Constats documentés.","Facteurs internes et externes séparés.","Actions datées."],"sources":[{"kind":"reference","label":"Bpifrance Création — Analyse SWOT","url":"https://bpifrance-creation.fr/encyclopedie/letude-marche/outils-danalyse/swot-outil-danalyse-strategique"}],"order":77,"subcategory":"","homeRank":0,"tagSlugs":["decisions","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
