INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/tableau-bord-entreprise','{"kind":"guides","slug":"tableau-bord-entreprise","title":"Tableau de bord : suivre les chiffres qui font agir","description":"Choisir quelques indicateurs utiles et comprendre les écarts.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : suivez des mesures qui vous aident à prendre une décision.","sections":[{"title":"Choisir selon votre activité","paragraphs":["Commandes, marge, retards de paiement ou délais de production ne répondent pas à la même question. Sélectionnez les indicateurs liés aux risques et aux objectifs de votre activité plutôt que les chiffres les plus flatteurs."]},{"title":"Comparer sur une même base","paragraphs":["Mettez les résultats face aux prévisions sur une période identique. Précisez la définition de chaque indicateur pour ne pas confondre chiffre d’affaires facturé et argent réellement encaissé."]},{"title":"Décider après la lecture","paragraphs":["Un écart appelle une explication : saisonnalité, prix, volume ou retard. Notez l’action retenue et sa date de réexamen. Un tableau rarement consulté ou trop détaillé devient vite un simple stockage de chiffres."]}],"checklist":["Indicateurs limités et définis.","Prévisions comparables.","Décisions consignées."],"sources":[{"kind":"reference","label":"Bpifrance Création — Le tableau de bord","url":"https://bpifrance-creation.fr/encyclopedie/letude-marche/determiner-sa-strategie/tableau-bord-outil-suivre-levolution-votre"}],"order":78,"subcategory":"","homeRank":0,"tagSlugs":["budget","entreprendre"]}','{"kind":"guides","slug":"tableau-bord-entreprise","title":"Tableau de bord : suivre les chiffres qui font agir","description":"Choisir quelques indicateurs utiles et comprendre les écarts.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : suivez des mesures qui vous aident à prendre une décision.","sections":[{"title":"Choisir selon votre activité","paragraphs":["Commandes, marge, retards de paiement ou délais de production ne répondent pas à la même question. Sélectionnez les indicateurs liés aux risques et aux objectifs de votre activité plutôt que les chiffres les plus flatteurs."]},{"title":"Comparer sur une même base","paragraphs":["Mettez les résultats face aux prévisions sur une période identique. Précisez la définition de chaque indicateur pour ne pas confondre chiffre d’affaires facturé et argent réellement encaissé."]},{"title":"Décider après la lecture","paragraphs":["Un écart appelle une explication : saisonnalité, prix, volume ou retard. Notez l’action retenue et sa date de réexamen. Un tableau rarement consulté ou trop détaillé devient vite un simple stockage de chiffres."]}],"checklist":["Indicateurs limités et définis.","Prévisions comparables.","Décisions consignées."],"sources":[{"kind":"reference","label":"Bpifrance Création — Le tableau de bord","url":"https://bpifrance-creation.fr/encyclopedie/letude-marche/determiner-sa-strategie/tableau-bord-outil-suivre-levolution-votre"}],"order":78,"subcategory":"","homeRank":0,"tagSlugs":["budget","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
