INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/fixer-prix-vente','{"kind":"guides","slug":"fixer-prix-vente","title":"Prix de vente : croiser coûts, clients et concurrence","description":"Définir un prix cohérent avec votre offre et votre rentabilité.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : le tarif d’un concurrent ne suffit pas à déterminer votre prix.","sections":[{"title":"Chiffrer ce que vous fournissez","paragraphs":["Identifiez les dépenses nécessaires à la prestation ou au produit, y compris le temps de travail. Un prix qui couvre les achats mais oublie le reste peut masquer une activité déficitaire."]},{"title":"Comprendre la comparaison du client","paragraphs":["Examinez les offres réellement comparables : qualité, délai, service et conditions. Demandez ce qui compte pour votre clientèle. Un prix plus bas ne compense pas forcément une offre mal adaptée."]},{"title":"Tester votre cohérence","paragraphs":["Croisez coûts, demande, concurrence et positionnement. Simulez l’effet d’une remise avant de l’accorder. Réévaluez le tarif si vos coûts, vos prestations ou votre marché évoluent."]}],"checklist":["Coûts identifiés.","Offres comparables étudiées.","Marge après remise calculée."],"sources":[{"kind":"reference","label":"Bpifrance Création — Fixer ses prix","url":"https://bpifrance-creation.fr/encyclopedie/letude-marche/determiner-sa-strategie/comment-fixer-ses-prix-projet-creation"}],"order":79,"subcategory":"","homeRank":0,"tagSlugs":["budget","entreprendre"]}','{"kind":"guides","slug":"fixer-prix-vente","title":"Prix de vente : croiser coûts, clients et concurrence","description":"Définir un prix cohérent avec votre offre et votre rentabilité.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : le tarif d’un concurrent ne suffit pas à déterminer votre prix.","sections":[{"title":"Chiffrer ce que vous fournissez","paragraphs":["Identifiez les dépenses nécessaires à la prestation ou au produit, y compris le temps de travail. Un prix qui couvre les achats mais oublie le reste peut masquer une activité déficitaire."]},{"title":"Comprendre la comparaison du client","paragraphs":["Examinez les offres réellement comparables : qualité, délai, service et conditions. Demandez ce qui compte pour votre clientèle. Un prix plus bas ne compense pas forcément une offre mal adaptée."]},{"title":"Tester votre cohérence","paragraphs":["Croisez coûts, demande, concurrence et positionnement. Simulez l’effet d’une remise avant de l’accorder. Réévaluez le tarif si vos coûts, vos prestations ou votre marché évoluent."]}],"checklist":["Coûts identifiés.","Offres comparables étudiées.","Marge après remise calculée."],"sources":[{"kind":"reference","label":"Bpifrance Création — Fixer ses prix","url":"https://bpifrance-creation.fr/encyclopedie/letude-marche/determiner-sa-strategie/comment-fixer-ses-prix-projet-creation"}],"order":79,"subcategory":"","homeRank":0,"tagSlugs":["budget","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
