INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/seuil-rentabilite','{"kind":"guides","slug":"seuil-rentabilite","title":"Seuil de rentabilité : savoir combien il faut vendre","description":"Traduire vos charges en objectif de ventes réaliste.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : vérifiez le volume nécessaire avant de vous fier au chiffre d’affaires.","sections":[{"title":"Distinguer les charges","paragraphs":["Séparez les charges fixes de celles qui évoluent avec les ventes. La marge sur coûts variables correspond à ce qui reste du chiffre d’affaires après ces coûts variables ; elle sert notamment à couvrir les charges fixes."]},{"title":"Faire un calcul explicite","paragraphs":["Le seuil de rentabilité se calcule en divisant les charges fixes par le taux de marge sur coûts variables. Exemple fictif : 1 000 € de charges fixes avec un taux de 50 % demandent 2 000 € de ventes sur la même période."]},{"title":"Vérifier la faisabilité","paragraphs":["Convertissez ce montant en commandes ou en heures facturables. Comparez-le à votre capacité réelle. Réactualisez le calcul lors d’un changement de prix ou de coûts ; atteindre ce seuil ne garantit pas une trésorerie disponible."]}],"checklist":["Même période de calcul.","Hypothèses explicites.","Volume compatible avec la capacité."],"sources":[{"kind":"reference","label":"Bpifrance Création — Seuil de rentabilité","url":"https://bpifrance-creation.fr/encyclopedie/previsions-financieres-business-plan/previsions-financieres/seuil-rentabilite"}],"order":80,"subcategory":"","homeRank":0,"tagSlugs":["budget","entreprendre"]}','{"kind":"guides","slug":"seuil-rentabilite","title":"Seuil de rentabilité : savoir combien il faut vendre","description":"Traduire vos charges en objectif de ventes réaliste.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : vérifiez le volume nécessaire avant de vous fier au chiffre d’affaires.","sections":[{"title":"Distinguer les charges","paragraphs":["Séparez les charges fixes de celles qui évoluent avec les ventes. La marge sur coûts variables correspond à ce qui reste du chiffre d’affaires après ces coûts variables ; elle sert notamment à couvrir les charges fixes."]},{"title":"Faire un calcul explicite","paragraphs":["Le seuil de rentabilité se calcule en divisant les charges fixes par le taux de marge sur coûts variables. Exemple fictif : 1 000 € de charges fixes avec un taux de 50 % demandent 2 000 € de ventes sur la même période."]},{"title":"Vérifier la faisabilité","paragraphs":["Convertissez ce montant en commandes ou en heures facturables. Comparez-le à votre capacité réelle. Réactualisez le calcul lors d’un changement de prix ou de coûts ; atteindre ce seuil ne garantit pas une trésorerie disponible."]}],"checklist":["Même période de calcul.","Hypothèses explicites.","Volume compatible avec la capacité."],"sources":[{"kind":"reference","label":"Bpifrance Création — Seuil de rentabilité","url":"https://bpifrance-creation.fr/encyclopedie/previsions-financieres-business-plan/previsions-financieres/seuil-rentabilite"}],"order":80,"subcategory":"","homeRank":0,"tagSlugs":["budget","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
