INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/besoin-fonds-roulement','{"kind":"guides","slug":"besoin-fonds-roulement","title":"BFR : financer le temps entre dépenses et encaissements","description":"Anticiper le décalage provoqué par les stocks et les délais de paiement.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : une vente rentable peut demander de l’argent avant d’en rapporter.","sections":[{"title":"Dessiner le cycle","paragraphs":["Placez sur une ligne les achats, le stockage, la livraison, la facture et l’encaissement. Repérez les dépenses à payer avant de recevoir l’argent du client. Ce décalage contribue au besoin en fonds de roulement."]},{"title":"Tester une situation moins favorable","paragraphs":["Que se passe-t-il si les stocks tournent moins vite ou si un client paie plus tard ? Chiffrez ces hypothèses. La croissance peut augmenter le besoin de financement au lieu de le résoudre immédiatement."]},{"title":"Prévoir les ressources","paragraphs":["Intégrez le besoin au financement du projet. Examinez les stocks et les conditions de paiement négociables sans supposer que tous vos partenaires accepteront vos délais. Faites vérifier les hypothèses par votre accompagnateur ou votre comptable."]}],"checklist":["Cycle d’exploitation décrit.","Scénario de retard chiffré.","Financement du décalage prévu."],"sources":[{"kind":"reference","label":"Bpifrance Création — Besoin en fonds de roulement","url":"https://bpifrance-creation.fr/encyclopedie/previsions-financieres-business-plan/previsions-financieres/besoin-fonds-roulement-bfr"}],"order":81,"subcategory":"","homeRank":0,"tagSlugs":["budget","entreprendre"]}','{"kind":"guides","slug":"besoin-fonds-roulement","title":"BFR : financer le temps entre dépenses et encaissements","description":"Anticiper le décalage provoqué par les stocks et les délais de paiement.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : une vente rentable peut demander de l’argent avant d’en rapporter.","sections":[{"title":"Dessiner le cycle","paragraphs":["Placez sur une ligne les achats, le stockage, la livraison, la facture et l’encaissement. Repérez les dépenses à payer avant de recevoir l’argent du client. Ce décalage contribue au besoin en fonds de roulement."]},{"title":"Tester une situation moins favorable","paragraphs":["Que se passe-t-il si les stocks tournent moins vite ou si un client paie plus tard ? Chiffrez ces hypothèses. La croissance peut augmenter le besoin de financement au lieu de le résoudre immédiatement."]},{"title":"Prévoir les ressources","paragraphs":["Intégrez le besoin au financement du projet. Examinez les stocks et les conditions de paiement négociables sans supposer que tous vos partenaires accepteront vos délais. Faites vérifier les hypothèses par votre accompagnateur ou votre comptable."]}],"checklist":["Cycle d’exploitation décrit.","Scénario de retard chiffré.","Financement du décalage prévu."],"sources":[{"kind":"reference","label":"Bpifrance Création — Besoin en fonds de roulement","url":"https://bpifrance-creation.fr/encyclopedie/previsions-financieres-business-plan/previsions-financieres/besoin-fonds-roulement-bfr"}],"order":81,"subcategory":"","homeRank":0,"tagSlugs":["budget","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
