INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/plan-financement-demarrage','{"kind":"guides","slug":"plan-financement-demarrage","title":"Démarrage : financer plus que le matériel","description":"Équilibrer les besoins initiaux et les ressources réellement disponibles.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : prévoyez aussi l’argent nécessaire pour faire fonctionner l’activité.","sections":[{"title":"Lister tous les besoins","paragraphs":["Recensez le matériel, les dépenses immatérielles, le stock de départ et le besoin en fonds de roulement. Ajoutez une marge de trésorerie adaptée aux incertitudes plutôt que de financer uniquement les achats visibles."]},{"title":"Qualifier les ressources","paragraphs":["Distinguez vos apports, les financements accordés et les aides encore hypothétiques. Une demande déposée ne constitue pas une somme disponible. Notez les dates de versement attendues."]},{"title":"Rechercher un équilibre solide","paragraphs":["Comparez le total des besoins aux ressources durables. Si l’équilibre manque, ajustez le projet ou son financement avant d’engager les dépenses. Révisez le plan à mesure que les devis et les accords deviennent définitifs."]}],"checklist":["Besoins complets.","Accords séparés des demandes.","Réserve et calendrier prévus."],"sources":[{"kind":"reference","label":"Bpifrance Création — Plan de financement initial","url":"https://bpifrance-creation.fr/encyclopedie/previsions-financieres-business-plan/previsions-financieres/plan-financement-initial"}],"order":82,"subcategory":"","homeRank":0,"tagSlugs":["budget","entreprendre"]}','{"kind":"guides","slug":"plan-financement-demarrage","title":"Démarrage : financer plus que le matériel","description":"Équilibrer les besoins initiaux et les ressources réellement disponibles.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : prévoyez aussi l’argent nécessaire pour faire fonctionner l’activité.","sections":[{"title":"Lister tous les besoins","paragraphs":["Recensez le matériel, les dépenses immatérielles, le stock de départ et le besoin en fonds de roulement. Ajoutez une marge de trésorerie adaptée aux incertitudes plutôt que de financer uniquement les achats visibles."]},{"title":"Qualifier les ressources","paragraphs":["Distinguez vos apports, les financements accordés et les aides encore hypothétiques. Une demande déposée ne constitue pas une somme disponible. Notez les dates de versement attendues."]},{"title":"Rechercher un équilibre solide","paragraphs":["Comparez le total des besoins aux ressources durables. Si l’équilibre manque, ajustez le projet ou son financement avant d’engager les dépenses. Révisez le plan à mesure que les devis et les accords deviennent définitifs."]}],"checklist":["Besoins complets.","Accords séparés des demandes.","Réserve et calendrier prévus."],"sources":[{"kind":"reference","label":"Bpifrance Création — Plan de financement initial","url":"https://bpifrance-creation.fr/encyclopedie/previsions-financieres-business-plan/previsions-financieres/plan-financement-initial"}],"order":82,"subcategory":"","homeRank":0,"tagSlugs":["budget","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
