INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/choisir-marque-distinctive','{"kind":"guides","slug":"choisir-marque-distinctive","title":"Marque : vérifier le nom avant de communiquer","description":"Préparer le choix d’un signe distinctif pour votre activité.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : ne confondez pas un nom séduisant avec un nom juridiquement disponible.","sections":[{"title":"Choisir un signe distinctif","paragraphs":["Une marque doit permettre d’identifier votre offre. Un terme qui décrit seulement le produit peut ne pas remplir cette fonction. Écartez aussi les formulations trompeuses sur ses caractéristiques."]},{"title":"Vérifier avant d’investir","paragraphs":["Avant de commander enseigne, emballages ou publicité, examinez les droits antérieurs et la pertinence d’un dépôt. La disponibilité d’une adresse internet ne suffit pas à régler la question de la marque."]},{"title":"Cadrer votre projet","paragraphs":["Listez les produits et services concernés ainsi que vos perspectives de développement. En cas de doute sur le nom ou la protection recherchée, faites-vous accompagner par un professionnel de la propriété industrielle. Gardez la trace des recherches effectuées."]}],"checklist":["Nom distinctif envisagé.","Recherches avant communication.","Périmètre de protection étudié."],"sources":[{"kind":"reference","label":"Bpifrance Création — Déposer une marque","url":"https://bpifrance-creation.fr/encyclopedie/trouver-proteger-tester-son-idee/proteger-son-idee/comment-deposer-marque"}],"order":83,"subcategory":"","homeRank":0,"tagSlugs":["decisions","entreprendre"]}','{"kind":"guides","slug":"choisir-marque-distinctive","title":"Marque : vérifier le nom avant de communiquer","description":"Préparer le choix d’un signe distinctif pour votre activité.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : ne confondez pas un nom séduisant avec un nom juridiquement disponible.","sections":[{"title":"Choisir un signe distinctif","paragraphs":["Une marque doit permettre d’identifier votre offre. Un terme qui décrit seulement le produit peut ne pas remplir cette fonction. Écartez aussi les formulations trompeuses sur ses caractéristiques."]},{"title":"Vérifier avant d’investir","paragraphs":["Avant de commander enseigne, emballages ou publicité, examinez les droits antérieurs et la pertinence d’un dépôt. La disponibilité d’une adresse internet ne suffit pas à régler la question de la marque."]},{"title":"Cadrer votre projet","paragraphs":["Listez les produits et services concernés ainsi que vos perspectives de développement. En cas de doute sur le nom ou la protection recherchée, faites-vous accompagner par un professionnel de la propriété industrielle. Gardez la trace des recherches effectuées."]}],"checklist":["Nom distinctif envisagé.","Recherches avant communication.","Périmètre de protection étudié."],"sources":[{"kind":"reference","label":"Bpifrance Création — Déposer une marque","url":"https://bpifrance-creation.fr/encyclopedie/trouver-proteger-tester-son-idee/proteger-son-idee/comment-deposer-marque"}],"order":83,"subcategory":"","homeRank":0,"tagSlugs":["decisions","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
