INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/reserver-nom-domaine','{"kind":"guides","slug":"reserver-nom-domaine","title":"Nom de domaine : garder la maîtrise de son adresse","description":"Choisir et réserver une adresse sans perdre le contrôle du compte.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : le titulaire et les accès comptent autant que le nom choisi.","sections":[{"title":"Vérifier le choix","paragraphs":["Contrôlez la disponibilité de l’adresse et les droits antérieurs susceptibles de s’y opposer. Une réservation possible ne prouve pas que le nom peut être utilisé sans conflit. Comparez les extensions pertinentes pour votre public."]},{"title":"Identifier le titulaire","paragraphs":["Lorsqu’un prestataire s’occupe de la réservation, vérifiez que le titulaire prévu est bien votre entreprise. Clarifiez qui gère le compte, les renouvellements et les échanges avec le bureau d’enregistrement."]},{"title":"Préparer la continuité","paragraphs":["Conservez les justificatifs et les accès dans un espace maîtrisé. Notez l’échéance de renouvellement et utilisez une adresse de contact durable. Prévoyez la récupération du domaine si vous changez de prestataire."]}],"checklist":["Disponibilité et droits examinés.","Titulaire correct.","Renouvellement et accès suivis."],"sources":[{"kind":"reference","label":"Bpifrance Création — Le nom de domaine","url":"https://bpifrance-creation.fr/encyclopedie/trouver-proteger-tester-son-idee/proteger-son-idee/nom-domaine"}],"order":84,"subcategory":"","homeRank":0,"tagSlugs":["donnees-personnelles","entreprendre"]}','{"kind":"guides","slug":"reserver-nom-domaine","title":"Nom de domaine : garder la maîtrise de son adresse","description":"Choisir et réserver une adresse sans perdre le contrôle du compte.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : le titulaire et les accès comptent autant que le nom choisi.","sections":[{"title":"Vérifier le choix","paragraphs":["Contrôlez la disponibilité de l’adresse et les droits antérieurs susceptibles de s’y opposer. Une réservation possible ne prouve pas que le nom peut être utilisé sans conflit. Comparez les extensions pertinentes pour votre public."]},{"title":"Identifier le titulaire","paragraphs":["Lorsqu’un prestataire s’occupe de la réservation, vérifiez que le titulaire prévu est bien votre entreprise. Clarifiez qui gère le compte, les renouvellements et les échanges avec le bureau d’enregistrement."]},{"title":"Préparer la continuité","paragraphs":["Conservez les justificatifs et les accès dans un espace maîtrisé. Notez l’échéance de renouvellement et utilisez une adresse de contact durable. Prévoyez la récupération du domaine si vous changez de prestataire."]}],"checklist":["Disponibilité et droits examinés.","Titulaire correct.","Renouvellement et accès suivis."],"sources":[{"kind":"reference","label":"Bpifrance Création — Le nom de domaine","url":"https://bpifrance-creation.fr/encyclopedie/trouver-proteger-tester-son-idee/proteger-son-idee/nom-domaine"}],"order":84,"subcategory":"","homeRank":0,"tagSlugs":["donnees-personnelles","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
