INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/pitch-projet','{"kind":"guides","slug":"pitch-projet","title":"Présenter son projet : finir par une demande claire","description":"Adapter votre présentation à l’interlocuteur et à la décision attendue.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : expliquez ce dont votre interlocuteur a besoin pour décider.","sections":[{"title":"Comprendre le rendez-vous","paragraphs":["Un partenaire, un banquier et un futur client n’attendent pas la même présentation. Identifiez leur rôle, leurs critères et le temps disponible. Fixez l’objectif précis de la rencontre."]},{"title":"Construire un fil simple","paragraphs":["Présentez le problème, le public concerné, votre proposition et les éléments qui la rendent crédible. Distinguez les résultats déjà obtenus des prévisions. Préparez les chiffres détaillés pour les questions plutôt que de tout réciter."]},{"title":"Formuler la suite","paragraphs":["Terminez par une demande concrète : rendez-vous technique, retour sur une hypothèse ou examen d’un financement. Entraînez-vous à voix haute et raccourcissez les passages qui empêchent de comprendre le projet."]}],"checklist":["Interlocuteur identifié.","Preuves séparées des prévisions.","Prochaine étape formulée."],"sources":[{"kind":"reference","label":"Bpifrance Création — Présenter oralement son projet","url":"https://bpifrance-creation.fr/encyclopedie/porteur-projet-preparation-droits-obligations/preparation/presenter-oralement-son"}],"order":85,"subcategory":"","homeRank":0,"tagSlugs":["decisions","entreprendre"]}','{"kind":"guides","slug":"pitch-projet","title":"Présenter son projet : finir par une demande claire","description":"Adapter votre présentation à l’interlocuteur et à la décision attendue.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : expliquez ce dont votre interlocuteur a besoin pour décider.","sections":[{"title":"Comprendre le rendez-vous","paragraphs":["Un partenaire, un banquier et un futur client n’attendent pas la même présentation. Identifiez leur rôle, leurs critères et le temps disponible. Fixez l’objectif précis de la rencontre."]},{"title":"Construire un fil simple","paragraphs":["Présentez le problème, le public concerné, votre proposition et les éléments qui la rendent crédible. Distinguez les résultats déjà obtenus des prévisions. Préparez les chiffres détaillés pour les questions plutôt que de tout réciter."]},{"title":"Formuler la suite","paragraphs":["Terminez par une demande concrète : rendez-vous technique, retour sur une hypothèse ou examen d’un financement. Entraînez-vous à voix haute et raccourcissez les passages qui empêchent de comprendre le projet."]}],"checklist":["Interlocuteur identifié.","Preuves séparées des prévisions.","Prochaine étape formulée."],"sources":[{"kind":"reference","label":"Bpifrance Création — Présenter oralement son projet","url":"https://bpifrance-creation.fr/encyclopedie/porteur-projet-preparation-droits-obligations/preparation/presenter-oralement-son"}],"order":85,"subcategory":"","homeRank":0,"tagSlugs":["decisions","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
