INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/franchise-comprendre-engagement','{"kind":"guides","slug":"franchise-comprendre-engagement","title":"Franchise : examiner l’engagement derrière l’enseigne","description":"Comprendre la relation avec le réseau avant de vous engager.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : une marque connue ne remplace pas l’analyse de votre propre projet.","sections":[{"title":"Identifier ce qui est transmis","paragraphs":["La franchise associe notamment une enseigne, un savoir-faire et une assistance, en contrepartie d’engagements financiers. Demandez ce que chacun de ces éléments signifie concrètement dans le réseau envisagé."]},{"title":"Lire les obligations réciproques","paragraphs":["Comparez les promesses commerciales au contrat proposé. Listez ce que le franchiseur fournit et ce que vous devez respecter. Ne présumez pas qu’une simple licence de marque apporte la même assistance."]},{"title":"Rester responsable du projet","paragraphs":["Franchiseur et franchisé demeurent juridiquement et financièrement indépendants. Étudiez vos moyens, votre marché local et les conditions contractuelles avec un conseil adapté avant de signer. Gardez une version complète des documents reçus."]}],"checklist":["Apports du réseau précisés.","Obligations et coûts examinés.","Projet local étudié indépendamment."],"sources":[{"kind":"reference","label":"Bpifrance Création — Le contrat de franchise","url":"https://bpifrance-creation.fr/encyclopedie/differentes-facons-dentreprendre/entreprendre-franchise/contrat-franchise"}],"order":86,"subcategory":"","homeRank":0,"tagSlugs":["budget","entreprendre"]}','{"kind":"guides","slug":"franchise-comprendre-engagement","title":"Franchise : examiner l’engagement derrière l’enseigne","description":"Comprendre la relation avec le réseau avant de vous engager.","categoryId":"entrepreneuriat","themeId":"projets","reviewedAt":"2026-09-29","intro":"La règle d’or : une marque connue ne remplace pas l’analyse de votre propre projet.","sections":[{"title":"Identifier ce qui est transmis","paragraphs":["La franchise associe notamment une enseigne, un savoir-faire et une assistance, en contrepartie d’engagements financiers. Demandez ce que chacun de ces éléments signifie concrètement dans le réseau envisagé."]},{"title":"Lire les obligations réciproques","paragraphs":["Comparez les promesses commerciales au contrat proposé. Listez ce que le franchiseur fournit et ce que vous devez respecter. Ne présumez pas qu’une simple licence de marque apporte la même assistance."]},{"title":"Rester responsable du projet","paragraphs":["Franchiseur et franchisé demeurent juridiquement et financièrement indépendants. Étudiez vos moyens, votre marché local et les conditions contractuelles avec un conseil adapté avant de signer. Gardez une version complète des documents reçus."]}],"checklist":["Apports du réseau précisés.","Obligations et coûts examinés.","Projet local étudié indépendamment."],"sources":[{"kind":"reference","label":"Bpifrance Création — Le contrat de franchise","url":"https://bpifrance-creation.fr/encyclopedie/differentes-facons-dentreprendre/entreprendre-franchise/contrat-franchise"}],"order":86,"subcategory":"","homeRank":0,"tagSlugs":["budget","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
