INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/faux-support-technique','{"kind":"guides","slug":"faux-support-technique","title":"Fausse alerte informatique : ne pas appeler le numéro affiché","description":"Reprendre la main face à une demande de dépannage suspecte.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : une fenêtre alarmante ne prouve pas que votre appareil est infecté.","sections":[{"title":"Couper le scénario","paragraphs":["Ne téléphonez pas au numéro présenté et ne donnez aucun accès à distance. Photographiez le message puis fermez la fenêtre. Si la fausse page bloque la navigation, un redémarrage peut permettre de reprendre la main."]},{"title":"Traiter un accès déjà accordé","paragraphs":["Si un prétendu technicien a contrôlé votre ordinateur, faites retirer son outil d’accès et vérifier l’appareil. Changez les mots de passe depuis un équipement sûr. En entreprise, prévenez immédiatement le service informatique."]},{"title":"Réagir au paiement","paragraphs":["Contactez votre banque sans attendre si vous avez communiqué votre carte ou payé. Conservez messages, factures et références des opérations pour déposer plainte. Ne payez pas une seconde intervention censée réparer la première."]}],"checklist":["Numéro frauduleux ignoré.","Accès à distance contrôlés.","Banque et preuves mobilisées si nécessaire."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Faux support technique","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/arnaques-au-faux-support-technique"}],"order":87,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","arnaques","recours"]}','{"kind":"guides","slug":"faux-support-technique","title":"Fausse alerte informatique : ne pas appeler le numéro affiché","description":"Reprendre la main face à une demande de dépannage suspecte.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : une fenêtre alarmante ne prouve pas que votre appareil est infecté.","sections":[{"title":"Couper le scénario","paragraphs":["Ne téléphonez pas au numéro présenté et ne donnez aucun accès à distance. Photographiez le message puis fermez la fenêtre. Si la fausse page bloque la navigation, un redémarrage peut permettre de reprendre la main."]},{"title":"Traiter un accès déjà accordé","paragraphs":["Si un prétendu technicien a contrôlé votre ordinateur, faites retirer son outil d’accès et vérifier l’appareil. Changez les mots de passe depuis un équipement sûr. En entreprise, prévenez immédiatement le service informatique."]},{"title":"Réagir au paiement","paragraphs":["Contactez votre banque sans attendre si vous avez communiqué votre carte ou payé. Conservez messages, factures et références des opérations pour déposer plainte. Ne payez pas une seconde intervention censée réparer la première."]}],"checklist":["Numéro frauduleux ignoré.","Accès à distance contrôlés.","Banque et preuves mobilisées si nécessaire."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Faux support technique","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/arnaques-au-faux-support-technique"}],"order":87,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","arnaques","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
