INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/chantage-webcam-message','{"kind":"guides","slug":"chantage-webcam-message","title":"Chantage à la webcam : garder son calme et les preuves","description":"Réagir à un message prétendant détenir des images intimes.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : un ancien mot de passe affiché dans un courriel ne prouve pas le piratage de votre caméra.","sections":[{"title":"Identifier la pression","paragraphs":["Ces messages cherchent à provoquer un paiement urgent en affirmant détenir une vidéo. L’adresse d’expéditeur peut être usurpée et un mot de passe provenir d’une ancienne fuite. Ne répondez pas et ne versez pas de rançon."]},{"title":"Protéger les accès exposés","paragraphs":["Si le mot de passe cité est encore utilisé, remplacez-le sur tous les comptes concernés par des mots de passe distincts. Conservez le message et ses informations avant tout signalement."]},{"title":"Demander de l’aide","paragraphs":["Déposez plainte avec vos preuves ; contactez la banque si vous avez payé. Si des images existent réellement, demandez un accompagnement adapté sans rester isolé : ce guide traite surtout des messages de piratage prétendu."]}],"checklist":["Aucune réponse ni rançon.","Mot de passe exposé remplacé.","Message conservé et aide sollicitée."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Chantage à la webcam","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/chantage-a-lordinateur-ou-a-la-webcam-pretendus-pirates"}],"order":88,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","arnaques","recours"]}','{"kind":"guides","slug":"chantage-webcam-message","title":"Chantage à la webcam : garder son calme et les preuves","description":"Réagir à un message prétendant détenir des images intimes.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : un ancien mot de passe affiché dans un courriel ne prouve pas le piratage de votre caméra.","sections":[{"title":"Identifier la pression","paragraphs":["Ces messages cherchent à provoquer un paiement urgent en affirmant détenir une vidéo. L’adresse d’expéditeur peut être usurpée et un mot de passe provenir d’une ancienne fuite. Ne répondez pas et ne versez pas de rançon."]},{"title":"Protéger les accès exposés","paragraphs":["Si le mot de passe cité est encore utilisé, remplacez-le sur tous les comptes concernés par des mots de passe distincts. Conservez le message et ses informations avant tout signalement."]},{"title":"Demander de l’aide","paragraphs":["Déposez plainte avec vos preuves ; contactez la banque si vous avez payé. Si des images existent réellement, demandez un accompagnement adapté sans rester isolé : ce guide traite surtout des messages de piratage prétendu."]}],"checklist":["Aucune réponse ni rançon.","Mot de passe exposé remplacé.","Message conservé et aide sollicitée."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Chantage à la webcam","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/chantage-a-lordinateur-ou-a-la-webcam-pretendus-pirates"}],"order":88,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","arnaques","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/guides/chantage-webcam-message','guides/chantage-webcam-message',1,'{"kind":"guides","slug":"chantage-webcam-message","title":"Chantage à la webcam : garder son calme et les preuves","description":"Réagir à un message prétendant détenir des images intimes.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : un ancien mot de passe affiché dans un courriel ne prouve pas le piratage de votre caméra.","sections":[{"title":"Identifier la pression","paragraphs":["Ces messages cherchent à provoquer un paiement urgent en affirmant détenir une vidéo. L’adresse d’expéditeur peut être usurpée et un mot de passe provenir d’une ancienne fuite. Ne répondez pas et ne versez pas de rançon."]},{"title":"Protéger les accès exposés","paragraphs":["Si le mot de passe cité est encore utilisé, remplacez-le sur tous les comptes concernés par des mots de passe distincts. Conservez le message et ses informations avant tout signalement."]},{"title":"Demander de l’aide","paragraphs":["Déposez plainte avec vos preuves ; contactez la banque si vous avez payé. Si des images existent réellement, demandez un accompagnement adapté sans rester isolé : ce guide traite surtout des messages de piratage prétendu."]}],"checklist":["Aucune réponse ni rançon.","Mot de passe exposé remplacé.","Message conservé et aide sollicitée."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Chantage à la webcam","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/chantage-a-lordinateur-ou-a-la-webcam-pretendus-pirates"}],"order":88,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","arnaques","recours"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/cyberharcelement-preuves-aide','{"kind":"guides","slug":"cyberharcelement-preuves-aide","title":"Cyberharcèlement : conserver les preuves et se faire aider","description":"Organiser les premiers gestes face à des attaques répétées en ligne.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : ne restez pas seul face aux messages et publications qui vous visent.","sections":[{"title":"Préserver les éléments utiles","paragraphs":["Gardez les messages, captures, dates, adresses des publications et identifiants des comptes. Évitez de répondre aux provocations. Demandez à une personne de confiance de vous aider à rassembler ces éléments."]},{"title":"Réduire l’exposition","paragraphs":["Signalez les contenus et les comportements à la plateforme, puis bloquez les comptes concernés. Revoyez les paramètres de confidentialité et la visibilité de votre liste de contacts. Conservez la preuve des signalements."]},{"title":"Chercher un soutien","paragraphs":["Parlez-en à un proche ou, pour un élève, à un adulte de confiance dans l’établissement. Les preuves peuvent accompagner une plainte. Ne considérez pas le simple blocage comme une solution suffisante si les attaques continuent ou si vous êtes menacé."]}],"checklist":["Messages et liens sauvegardés.","Plateforme alertée.","Personne de confiance sollicitée."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Cyberharcèlement","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/que-faire-en-cas-de-cyberharcelement-ou-harcelement-en-ligne"}],"order":89,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles","recours"]}','{"kind":"guides","slug":"cyberharcelement-preuves-aide","title":"Cyberharcèlement : conserver les preuves et se faire aider","description":"Organiser les premiers gestes face à des attaques répétées en ligne.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : ne restez pas seul face aux messages et publications qui vous visent.","sections":[{"title":"Préserver les éléments utiles","paragraphs":["Gardez les messages, captures, dates, adresses des publications et identifiants des comptes. Évitez de répondre aux provocations. Demandez à une personne de confiance de vous aider à rassembler ces éléments."]},{"title":"Réduire l’exposition","paragraphs":["Signalez les contenus et les comportements à la plateforme, puis bloquez les comptes concernés. Revoyez les paramètres de confidentialité et la visibilité de votre liste de contacts. Conservez la preuve des signalements."]},{"title":"Chercher un soutien","paragraphs":["Parlez-en à un proche ou, pour un élève, à un adulte de confiance dans l’établissement. Les preuves peuvent accompagner une plainte. Ne considérez pas le simple blocage comme une solution suffisante si les attaques continuent ou si vous êtes menacé."]}],"checklist":["Messages et liens sauvegardés.","Plateforme alertée.","Personne de confiance sollicitée."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Cyberharcèlement","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/que-faire-en-cas-de-cyberharcelement-ou-harcelement-en-ligne"}],"order":89,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
