INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/escroquerie-sentimentale','{"kind":"guides","slug":"escroquerie-sentimentale","title":"Rencontre en ligne : refuser les demandes d’argent","description":"Repérer les pressions financières dans une relation à distance.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : l’attachement ne dispense pas de vérifier une histoire.","sections":[{"title":"Reconnaître les signaux","paragraphs":["Rencontres toujours repoussées, urgence financière et volonté de vous éloigner de vos proches doivent alerter. Une photo convaincante ou de longs échanges ne prouvent pas l’identité de votre interlocuteur."]},{"title":"Prendre un avis extérieur","paragraphs":["Parlez de la situation à un proche. Une recherche inversée des photos peut révéler une usurpation, sans garantir à elle seule l’authenticité d’un profil. N’envoyez ni argent ni contenu intime à un contact uniquement virtuel."]},{"title":"Stopper les échanges frauduleux","paragraphs":["Si vous identifiez une escroquerie, interrompez la relation et conservez les messages ainsi que les références des paiements. Déposez plainte et contactez rapidement votre banque si un transfert a été effectué."]}],"checklist":["Demande d’argent refusée.","Avis d’un proche recherché.","Échanges et paiements documentés."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Escroquerie sentimentale","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/comment-reagir-en-cas-descroquerie-sentimentale"}],"order":90,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","arnaques"]}','{"kind":"guides","slug":"escroquerie-sentimentale","title":"Rencontre en ligne : refuser les demandes d’argent","description":"Repérer les pressions financières dans une relation à distance.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : l’attachement ne dispense pas de vérifier une histoire.","sections":[{"title":"Reconnaître les signaux","paragraphs":["Rencontres toujours repoussées, urgence financière et volonté de vous éloigner de vos proches doivent alerter. Une photo convaincante ou de longs échanges ne prouvent pas l’identité de votre interlocuteur."]},{"title":"Prendre un avis extérieur","paragraphs":["Parlez de la situation à un proche. Une recherche inversée des photos peut révéler une usurpation, sans garantir à elle seule l’authenticité d’un profil. N’envoyez ni argent ni contenu intime à un contact uniquement virtuel."]},{"title":"Stopper les échanges frauduleux","paragraphs":["Si vous identifiez une escroquerie, interrompez la relation et conservez les messages ainsi que les références des paiements. Déposez plainte et contactez rapidement votre banque si un transfert a été effectué."]}],"checklist":["Demande d’argent refusée.","Avis d’un proche recherché.","Échanges et paiements documentés."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Escroquerie sentimentale","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/comment-reagir-en-cas-descroquerie-sentimentale"}],"order":90,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","arnaques"]}',1,'2026-10-01T06:41:56.605Z','migration');
