INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/fausse-offre-emploi','{"kind":"guides","slug":"fausse-offre-emploi","title":"Offre d’emploi : vérifier le recruteur avant d’envoyer ses documents","description":"Éviter les annonces destinées à voler de l’argent ou des données.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : un recrutement ne commence pas par un transfert d’argent au recruteur.","sections":[{"title":"Vérifier par un autre canal","paragraphs":["Recherchez l’entreprise et contactez-la avec des coordonnées trouvées indépendamment de l’annonce. Un nom réel ou un numéro SIRET peut être usurpé. Une rémunération exceptionnelle sans sélection mérite une vérification attentive."]},{"title":"Protéger argent et identité","paragraphs":["N’avancez pas d’argent pour obtenir le poste et n’achetez pas de matériel pour un inconnu qui promet un remboursement. Ne transmettez pas de coordonnées bancaires ou de documents sensibles avant d’avoir vérifié la réalité du recrutement."]},{"title":"Garder les traces","paragraphs":["Conservez l’annonce, les messages et les coordonnées utilisées. Signalez l’offre à la plateforme qui l’héberge. Si vous avez payé ou transmis des éléments exploitables, sollicitez rapidement l’assistance appropriée et votre banque selon le cas."]}],"checklist":["Entreprise contactée indépendamment.","Aucun paiement au recruteur.","Annonce et échanges conservés."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Fausses offres d’emploi","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/fausses-offres-demploi-creees-par-des-fraudeurs"}],"order":91,"subcategory":"","homeRank":0,"tagSlugs":["arnaques","travail","decisions"]}','{"kind":"guides","slug":"fausse-offre-emploi","title":"Offre d’emploi : vérifier le recruteur avant d’envoyer ses documents","description":"Éviter les annonces destinées à voler de l’argent ou des données.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : un recrutement ne commence pas par un transfert d’argent au recruteur.","sections":[{"title":"Vérifier par un autre canal","paragraphs":["Recherchez l’entreprise et contactez-la avec des coordonnées trouvées indépendamment de l’annonce. Un nom réel ou un numéro SIRET peut être usurpé. Une rémunération exceptionnelle sans sélection mérite une vérification attentive."]},{"title":"Protéger argent et identité","paragraphs":["N’avancez pas d’argent pour obtenir le poste et n’achetez pas de matériel pour un inconnu qui promet un remboursement. Ne transmettez pas de coordonnées bancaires ou de documents sensibles avant d’avoir vérifié la réalité du recrutement."]},{"title":"Garder les traces","paragraphs":["Conservez l’annonce, les messages et les coordonnées utilisées. Signalez l’offre à la plateforme qui l’héberge. Si vous avez payé ou transmis des éléments exploitables, sollicitez rapidement l’assistance appropriée et votre banque selon le cas."]}],"checklist":["Entreprise contactée indépendamment.","Aucun paiement au recruteur.","Annonce et échanges conservés."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Fausses offres d’emploi","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/fausses-offres-demploi-creees-par-des-fraudeurs"}],"order":91,"subcategory":"","homeRank":0,"tagSlugs":["arnaques","travail","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
