INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/rancongiciel-entreprise','{"kind":"guides","slug":"rancongiciel-entreprise","title":"Rançongiciel : isoler les appareils et alerter","description":"Organiser les premiers gestes lorsque les fichiers deviennent inaccessibles.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : faites contenir l’incident avant de tenter une réparation improvisée.","sections":[{"title":"Isoler sans effacer","paragraphs":["Déconnectez du réseau les appareils touchés et protégez les sauvegardes connectées. Ne relancez pas les machines éteintes. Faites décider l’arrêt ou le maintien des appareils par l’intervenant : les preuves et un chiffrement encore actif demandent des arbitrages."]},{"title":"Mobiliser les bons interlocuteurs","paragraphs":["Alertez immédiatement le service informatique ou un professionnel spécialisé. Notez l’heure, les symptômes et les actions effectuées. Photographiez la demande de rançon et évitez les outils de récupération trouvés au hasard."]},{"title":"Organiser la suite","paragraphs":["Ne payez pas : la récupération et la non-divulgation des données ne sont pas garanties. Faites préserver les preuves, déposez plainte et coordonnez la continuité de l’activité. La restauration doit suivre l’analyse et la sécurisation du système."]}],"checklist":["Machines isolées.","Intervenant alerté et journal commencé.","Preuves préservées sans rançon."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Rançongiciels dans les organisations","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/rancongiciels-ransomwares"}],"order":92,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","recours","entreprendre"]}','{"kind":"guides","slug":"rancongiciel-entreprise","title":"Rançongiciel : isoler les appareils et alerter","description":"Organiser les premiers gestes lorsque les fichiers deviennent inaccessibles.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : faites contenir l’incident avant de tenter une réparation improvisée.","sections":[{"title":"Isoler sans effacer","paragraphs":["Déconnectez du réseau les appareils touchés et protégez les sauvegardes connectées. Ne relancez pas les machines éteintes. Faites décider l’arrêt ou le maintien des appareils par l’intervenant : les preuves et un chiffrement encore actif demandent des arbitrages."]},{"title":"Mobiliser les bons interlocuteurs","paragraphs":["Alertez immédiatement le service informatique ou un professionnel spécialisé. Notez l’heure, les symptômes et les actions effectuées. Photographiez la demande de rançon et évitez les outils de récupération trouvés au hasard."]},{"title":"Organiser la suite","paragraphs":["Ne payez pas : la récupération et la non-divulgation des données ne sont pas garanties. Faites préserver les preuves, déposez plainte et coordonnez la continuité de l’activité. La restauration doit suivre l’analyse et la sécurisation du système."]}],"checklist":["Machines isolées.","Intervenant alerté et journal commencé.","Preuves préservées sans rançon."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Rançongiciels dans les organisations","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/rancongiciels-ransomwares"}],"order":92,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","recours","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/guides/rancongiciel-entreprise','guides/rancongiciel-entreprise',1,'{"kind":"guides","slug":"rancongiciel-entreprise","title":"Rançongiciel : isoler les appareils et alerter","description":"Organiser les premiers gestes lorsque les fichiers deviennent inaccessibles.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : faites contenir l’incident avant de tenter une réparation improvisée.","sections":[{"title":"Isoler sans effacer","paragraphs":["Déconnectez du réseau les appareils touchés et protégez les sauvegardes connectées. Ne relancez pas les machines éteintes. Faites décider l’arrêt ou le maintien des appareils par l’intervenant : les preuves et un chiffrement encore actif demandent des arbitrages."]},{"title":"Mobiliser les bons interlocuteurs","paragraphs":["Alertez immédiatement le service informatique ou un professionnel spécialisé. Notez l’heure, les symptômes et les actions effectuées. Photographiez la demande de rançon et évitez les outils de récupération trouvés au hasard."]},{"title":"Organiser la suite","paragraphs":["Ne payez pas : la récupération et la non-divulgation des données ne sont pas garanties. Faites préserver les preuves, déposez plainte et coordonnez la continuité de l’activité. La restauration doit suivre l’analyse et la sécurisation du système."]}],"checklist":["Machines isolées.","Intervenant alerté et journal commencé.","Preuves préservées sans rançon."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Rançongiciels dans les organisations","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/rancongiciels-ransomwares"}],"order":92,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","recours","entreprendre"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/mises-a-jour-securite','{"kind":"guides","slug":"mises-a-jour-securite","title":"Mises à jour : ne pas oublier les appareils discrets","description":"Maintenir les logiciels et équipements sans suivre une fausse alerte.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : les correctifs concernent aussi les appareils que vous ouvrez rarement.","sections":[{"title":"Faire l’inventaire","paragraphs":["Listez ordinateur, téléphone, tablette, navigateur et objets connectés. Les mises à jour corrigent notamment des failles de sécurité ; elles ne servent pas seulement à ajouter des fonctions. Un appareil oublié peut rester exposé."]},{"title":"Passer par le bon chemin","paragraphs":["Utilisez les réglages de l’appareil ou le site officiel de l’éditeur. Une publicité ou un message reçu peut proposer une fausse mise à jour. N’installez pas un fichier simplement parce qu’il promet une protection urgente."]},{"title":"Vérifier le résultat","paragraphs":["Activez les mises à jour automatiques lorsqu’elles sont proposées et contrôlez qu’elles s’effectuent réellement. Prévoyez le redémarrage nécessaire. Pour une machine professionnelle, suivez la procédure du service informatique plutôt que de la contourner."]}],"checklist":["Équipements recensés.","Canal officiel utilisé.","Installation et redémarrage vérifiés."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Mises à jour","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/mises-a-jour"}],"order":93,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite"]}','{"kind":"guides","slug":"mises-a-jour-securite","title":"Mises à jour : ne pas oublier les appareils discrets","description":"Maintenir les logiciels et équipements sans suivre une fausse alerte.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : les correctifs concernent aussi les appareils que vous ouvrez rarement.","sections":[{"title":"Faire l’inventaire","paragraphs":["Listez ordinateur, téléphone, tablette, navigateur et objets connectés. Les mises à jour corrigent notamment des failles de sécurité ; elles ne servent pas seulement à ajouter des fonctions. Un appareil oublié peut rester exposé."]},{"title":"Passer par le bon chemin","paragraphs":["Utilisez les réglages de l’appareil ou le site officiel de l’éditeur. Une publicité ou un message reçu peut proposer une fausse mise à jour. N’installez pas un fichier simplement parce qu’il promet une protection urgente."]},{"title":"Vérifier le résultat","paragraphs":["Activez les mises à jour automatiques lorsqu’elles sont proposées et contrôlez qu’elles s’effectuent réellement. Prévoyez le redémarrage nécessaire. Pour une machine professionnelle, suivez la procédure du service informatique plutôt que de la contourner."]}],"checklist":["Équipements recensés.","Canal officiel utilisé.","Installation et redémarrage vérifiés."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Mises à jour","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/mises-a-jour"}],"order":93,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite"]}',1,'2026-10-01T06:41:56.605Z','migration');
