INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/objets-connectes-securiser','{"kind":"guides","slug":"objets-connectes-securiser","title":"Objets connectés : sécuriser avant de les installer","description":"Configurer caméras, enceintes et autres équipements de la maison.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : la connexion facile ne doit pas laisser l’accès ouvert.","sections":[{"title":"Se renseigner avant l’achat","paragraphs":["Examinez le fonctionnement, les données collectées et le suivi proposé par le fabricant. Une caméra ou un babyphone accède à des espaces intimes : vérifiez les possibilités de contrôle et de mise à jour."]},{"title":"Modifier la configuration initiale","paragraphs":["Remplacez les mots de passe par défaut et protégez le compte associé avec un mot de passe unique. Installez les correctifs disponibles. Contrôlez qui peut se connecter à l’objet et quelles fonctions distantes sont activées."]},{"title":"Réduire les informations partagées","paragraphs":["Ne renseignez que les données nécessaires. Revoyez les paramètres de l’application et les personnes autorisées. Avant une cession, consultez la procédure du fabricant pour retirer le compte et effacer les données de l’appareil."]}],"checklist":["Suivi du fabricant examiné.","Accès par défaut remplacés.","Données et utilisateurs contrôlés."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Objets connectés","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/securite-objets-connectes-iot"}],"order":94,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles","logement"]}','{"kind":"guides","slug":"objets-connectes-securiser","title":"Objets connectés : sécuriser avant de les installer","description":"Configurer caméras, enceintes et autres équipements de la maison.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : la connexion facile ne doit pas laisser l’accès ouvert.","sections":[{"title":"Se renseigner avant l’achat","paragraphs":["Examinez le fonctionnement, les données collectées et le suivi proposé par le fabricant. Une caméra ou un babyphone accède à des espaces intimes : vérifiez les possibilités de contrôle et de mise à jour."]},{"title":"Modifier la configuration initiale","paragraphs":["Remplacez les mots de passe par défaut et protégez le compte associé avec un mot de passe unique. Installez les correctifs disponibles. Contrôlez qui peut se connecter à l’objet et quelles fonctions distantes sont activées."]},{"title":"Réduire les informations partagées","paragraphs":["Ne renseignez que les données nécessaires. Revoyez les paramètres de l’application et les personnes autorisées. Avant une cession, consultez la procédure du fabricant pour retirer le compte et effacer les données de l’appareil."]}],"checklist":["Suivi du fabricant examiné.","Accès par défaut remplacés.","Données et utilisateurs contrôlés."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Objets connectés","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/securite-objets-connectes-iot"}],"order":94,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles","logement"]}',1,'2026-10-01T06:41:56.605Z','migration');
