INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/reseaux-sociaux-confidentialite','{"kind":"guides","slug":"reseaux-sociaux-confidentialite","title":"Réseaux sociaux : choisir qui voit quoi","description":"Revoir l’audience des publications et protéger le compte.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : une publication réservée à quelques personnes peut quand même être rediffusée.","sections":[{"title":"Contrôler la visibilité","paragraphs":["Ouvrez les paramètres de confidentialité et vérifiez l’audience du profil, des publications et des coordonnées personnelles. Réexaminez-les régulièrement : ne supposez pas que les réglages initiaux correspondent encore à votre choix."]},{"title":"Limiter ce que vous exposez","paragraphs":["Évitez les informations sensibles sur vous, vos proches ou votre travail. Avant de publier une photo ou une anecdote, envisagez sa circulation hors du groupe prévu. Un réglage privé ne supprime pas le risque de capture."]},{"title":"Protéger les accès","paragraphs":["Utilisez un mot de passe propre au service et activez la double authentification. Méfiez-vous aussi des demandes inhabituelles provenant d’un ami : son compte peut être piraté. Confirmez par un autre moyen avant de répondre."]}],"checklist":["Audience vérifiée.","Informations sensibles retirées.","Accès et demandes inhabituelles contrôlés."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Réseaux sociaux","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/reseaux-sociaux"}],"order":95,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles"]}','{"kind":"guides","slug":"reseaux-sociaux-confidentialite","title":"Réseaux sociaux : choisir qui voit quoi","description":"Revoir l’audience des publications et protéger le compte.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : une publication réservée à quelques personnes peut quand même être rediffusée.","sections":[{"title":"Contrôler la visibilité","paragraphs":["Ouvrez les paramètres de confidentialité et vérifiez l’audience du profil, des publications et des coordonnées personnelles. Réexaminez-les régulièrement : ne supposez pas que les réglages initiaux correspondent encore à votre choix."]},{"title":"Limiter ce que vous exposez","paragraphs":["Évitez les informations sensibles sur vous, vos proches ou votre travail. Avant de publier une photo ou une anecdote, envisagez sa circulation hors du groupe prévu. Un réglage privé ne supprime pas le risque de capture."]},{"title":"Protéger les accès","paragraphs":["Utilisez un mot de passe propre au service et activez la double authentification. Méfiez-vous aussi des demandes inhabituelles provenant d’un ami : son compte peut être piraté. Confirmez par un autre moyen avant de répondre."]}],"checklist":["Audience vérifiée.","Informations sensibles retirées.","Accès et demandes inhabituelles contrôlés."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Réseaux sociaux","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/reseaux-sociaux"}],"order":95,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles"]}',1,'2026-10-01T06:41:56.605Z','migration');
