INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/smartphone-protection','{"kind":"guides","slug":"smartphone-protection","title":"Téléphone : protéger ce qui tient dans votre poche","description":"Verrouiller l’appareil et limiter les accès des applications.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : préparez la perte du téléphone avant qu’elle ne se produise.","sections":[{"title":"Verrouiller l’accès","paragraphs":["Choisissez un code difficile à deviner et activez le verrouillage automatique. Vérifiez le chiffrement proposé par votre appareil. Le code de la carte SIM et celui de l’écran répondent à des besoins différents."]},{"title":"Garder une copie indépendante","paragraphs":["Sauvegardez régulièrement contacts, photos et documents importants. Vérifiez que vous savez accéder à cette copie sans le téléphone : une sauvegarde inutilisable au moment de la perte n’apporte pas la protection attendue."]},{"title":"Contrôler les applications","paragraphs":["Installez-les depuis les magasins officiels et appliquez les mises à jour. Examinez les autorisations demandées : microphone, position ou contacts doivent correspondre à un usage compréhensible. Revoyez ces accès après les mises à jour."]}],"checklist":["Verrouillage actif.","Sauvegarde accessible.","Autorisations examinées."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Appareils mobiles","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/appareils-mobiles"}],"order":96,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles"]}','{"kind":"guides","slug":"smartphone-protection","title":"Téléphone : protéger ce qui tient dans votre poche","description":"Verrouiller l’appareil et limiter les accès des applications.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : préparez la perte du téléphone avant qu’elle ne se produise.","sections":[{"title":"Verrouiller l’accès","paragraphs":["Choisissez un code difficile à deviner et activez le verrouillage automatique. Vérifiez le chiffrement proposé par votre appareil. Le code de la carte SIM et celui de l’écran répondent à des besoins différents."]},{"title":"Garder une copie indépendante","paragraphs":["Sauvegardez régulièrement contacts, photos et documents importants. Vérifiez que vous savez accéder à cette copie sans le téléphone : une sauvegarde inutilisable au moment de la perte n’apporte pas la protection attendue."]},{"title":"Contrôler les applications","paragraphs":["Installez-les depuis les magasins officiels et appliquez les mises à jour. Examinez les autorisations demandées : microphone, position ou contacts doivent correspondre à un usage compréhensible. Revoyez ces accès après les mises à jour."]}],"checklist":["Verrouillage actif.","Sauvegarde accessible.","Autorisations examinées."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Appareils mobiles","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/appareils-mobiles"}],"order":96,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles"]}',1,'2026-10-01T06:41:56.605Z','migration');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/guides/smartphone-protection','guides/smartphone-protection',1,'{"kind":"guides","slug":"smartphone-protection","title":"Téléphone : protéger ce qui tient dans votre poche","description":"Verrouiller l’appareil et limiter les accès des applications.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : préparez la perte du téléphone avant qu’elle ne se produise.","sections":[{"title":"Verrouiller l’accès","paragraphs":["Choisissez un code difficile à deviner et activez le verrouillage automatique. Vérifiez le chiffrement proposé par votre appareil. Le code de la carte SIM et celui de l’écran répondent à des besoins différents."]},{"title":"Garder une copie indépendante","paragraphs":["Sauvegardez régulièrement contacts, photos et documents importants. Vérifiez que vous savez accéder à cette copie sans le téléphone : une sauvegarde inutilisable au moment de la perte n’apporte pas la protection attendue."]},{"title":"Contrôler les applications","paragraphs":["Installez-les depuis les magasins officiels et appliquez les mises à jour. Examinez les autorisations demandées : microphone, position ou contacts doivent correspondre à un usage compréhensible. Revoyez ces accès après les mises à jour."]}],"checklist":["Verrouillage actif.","Sauvegarde accessible.","Autorisations examinées."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Appareils mobiles","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/appareils-mobiles"}],"order":96,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/separer-usages-pro-perso','{"kind":"guides","slug":"separer-usages-pro-perso","title":"Travail et vie privée : séparer les espaces numériques","description":"Éviter que les documents et les comptes se mélangent.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : un outil pratique n’est pas forcément autorisé pour les données professionnelles.","sections":[{"title":"Séparer les comptes","paragraphs":["Utilisez des mots de passe distincts et les messageries prévues pour chaque usage. Une compromission personnelle ne doit pas ouvrir directement l’accès au travail. Vérifiez le destinataire avant d’envoyer un document."]},{"title":"Choisir le bon stockage","paragraphs":["Ne transférez pas automatiquement les dossiers professionnels vers votre messagerie ou votre espace personnel. Demandez une solution validée lorsque vous devez travailler à distance ou partager un fichier volumineux."]},{"title":"Clarifier les règles","paragraphs":["Consultez les consignes de votre organisation concernant appareils, logiciels et supports externes. Signalez une erreur de transfert rapidement afin qu’elle puisse être traitée. La séparation protège aussi vos échanges privés d’une diffusion involontaire au travail."]}],"checklist":["Comptes et mots de passe séparés.","Stockage autorisé utilisé.","Règles et interlocuteur connus."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Usages professionnels et personnels","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/securite-usages-pro-perso"}],"order":97,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles","travail"]}','{"kind":"guides","slug":"separer-usages-pro-perso","title":"Travail et vie privée : séparer les espaces numériques","description":"Éviter que les documents et les comptes se mélangent.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : un outil pratique n’est pas forcément autorisé pour les données professionnelles.","sections":[{"title":"Séparer les comptes","paragraphs":["Utilisez des mots de passe distincts et les messageries prévues pour chaque usage. Une compromission personnelle ne doit pas ouvrir directement l’accès au travail. Vérifiez le destinataire avant d’envoyer un document."]},{"title":"Choisir le bon stockage","paragraphs":["Ne transférez pas automatiquement les dossiers professionnels vers votre messagerie ou votre espace personnel. Demandez une solution validée lorsque vous devez travailler à distance ou partager un fichier volumineux."]},{"title":"Clarifier les règles","paragraphs":["Consultez les consignes de votre organisation concernant appareils, logiciels et supports externes. Signalez une erreur de transfert rapidement afin qu’elle puisse être traitée. La séparation protège aussi vos échanges privés d’une diffusion involontaire au travail."]}],"checklist":["Comptes et mots de passe séparés.","Stockage autorisé utilisé.","Règles et interlocuteur connus."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Usages professionnels et personnels","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/securite-usages-pro-perso"}],"order":97,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles","travail"]}',1,'2026-10-01T06:41:56.605Z','migration');
