INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/faux-ordre-virement','{"kind":"guides","slug":"faux-ordre-virement","title":"Virement urgent : vérifier la demande hors du message","description":"Déjouer une usurpation de dirigeant ou de fournisseur.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : l’urgence et la confidentialité ne doivent pas supprimer les contrôles de paiement.","sections":[{"title":"Faire confirmer le changement","paragraphs":["Un nouveau compte bancaire ou une demande inhabituelle mérite une confirmation indépendante. Appelez votre interlocuteur habituel avec un numéro déjà connu, sans reprendre celui fourni dans le message suspect."]},{"title":"Respecter la procédure","paragraphs":["Maintenez la validation interne prévue même si le demandeur prétend être un dirigeant pressé. Définissez à l’avance qui peut modifier les coordonnées bancaires et autoriser les virements. Sensibilisez aussi les remplaçants."]},{"title":"Agir si le virement est parti","paragraphs":["Prévenez immédiatement la banque, la hiérarchie et la comptabilité. Identifiez les opérations déjà exécutées ou programmées vers le compte frauduleux, puis faites bloquer son utilisation. Conservez les échanges pour les démarches et le dépôt de plainte."]}],"checklist":["Identité confirmée autrement.","Validation interne respectée.","Opérations suspectes recensées."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Fraude au virement","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/escroquerie-faux-ordres-virement-fovi"}],"order":98,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","arnaques","entreprendre"]}','{"kind":"guides","slug":"faux-ordre-virement","title":"Virement urgent : vérifier la demande hors du message","description":"Déjouer une usurpation de dirigeant ou de fournisseur.","categoryId":"cybersecurite","themeId":"numerique","reviewedAt":"2026-09-29","intro":"La règle d’or : l’urgence et la confidentialité ne doivent pas supprimer les contrôles de paiement.","sections":[{"title":"Faire confirmer le changement","paragraphs":["Un nouveau compte bancaire ou une demande inhabituelle mérite une confirmation indépendante. Appelez votre interlocuteur habituel avec un numéro déjà connu, sans reprendre celui fourni dans le message suspect."]},{"title":"Respecter la procédure","paragraphs":["Maintenez la validation interne prévue même si le demandeur prétend être un dirigeant pressé. Définissez à l’avance qui peut modifier les coordonnées bancaires et autoriser les virements. Sensibilisez aussi les remplaçants."]},{"title":"Agir si le virement est parti","paragraphs":["Prévenez immédiatement la banque, la hiérarchie et la comptabilité. Identifiez les opérations déjà exécutées ou programmées vers le compte frauduleux, puis faites bloquer son utilisation. Conservez les échanges pour les démarches et le dépôt de plainte."]}],"checklist":["Identité confirmée autrement.","Validation interne respectée.","Opérations suspectes recensées."],"sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Fraude au virement","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/escroquerie-faux-ordres-virement-fovi"}],"order":98,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","arnaques","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
