INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/assurance-location-garanties','{"kind":"guides","slug":"assurance-location-garanties","title":"Assurance locataire : vérifier ce qui est réellement couvert","description":"Distinguer les risques locatifs de la protection de vos biens.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : une attestation ne signifie pas que tous vos dommages sont assurés.","sections":[{"title":"Couvrir le logement loué","paragraphs":["Pour un bail d’habitation, y compris un bail mobilité, le locataire doit assurer les risques locatifs : incendie, explosion et dégât des eaux. Les locations touristiques relèvent de règles différentes."]},{"title":"Examiner les limites","paragraphs":["Cette garantie minimale ne couvre pas automatiquement vos biens ni les dommages aux voisins. Comparez les garanties complémentaires, exclusions, plafonds et franchises du contrat avant de choisir selon le seul prix."]},{"title":"Garder l’attestation disponible","paragraphs":["Remettez l’attestation lors de la remise des clés, puis chaque année si le bailleur la demande. Prévenez l’assureur des changements de situation. Conservez le contrat complet pour retrouver les conditions applicables en cas de sinistre."]}],"checklist":["Risques locatifs assurés.","Biens et voisins examinés.","Attestation conservée."],"sources":[{"kind":"reference","label":"Service Public — Assurance du locataire","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31300"}],"order":99,"subcategory":"","homeRank":0,"tagSlugs":["budget","logement"]}','{"kind":"guides","slug":"assurance-location-garanties","title":"Assurance locataire : vérifier ce qui est réellement couvert","description":"Distinguer les risques locatifs de la protection de vos biens.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : une attestation ne signifie pas que tous vos dommages sont assurés.","sections":[{"title":"Couvrir le logement loué","paragraphs":["Pour un bail d’habitation, y compris un bail mobilité, le locataire doit assurer les risques locatifs : incendie, explosion et dégât des eaux. Les locations touristiques relèvent de règles différentes."]},{"title":"Examiner les limites","paragraphs":["Cette garantie minimale ne couvre pas automatiquement vos biens ni les dommages aux voisins. Comparez les garanties complémentaires, exclusions, plafonds et franchises du contrat avant de choisir selon le seul prix."]},{"title":"Garder l’attestation disponible","paragraphs":["Remettez l’attestation lors de la remise des clés, puis chaque année si le bailleur la demande. Prévenez l’assureur des changements de situation. Conservez le contrat complet pour retrouver les conditions applicables en cas de sinistre."]}],"checklist":["Risques locatifs assurés.","Biens et voisins examinés.","Attestation conservée."],"sources":[{"kind":"reference","label":"Service Public — Assurance du locataire","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31300"}],"order":99,"subcategory":"","homeRank":0,"tagSlugs":["budget","logement"]}',1,'2026-10-01T06:41:56.605Z','migration');
