INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/quittance-loyer-demander','{"kind":"guides","slug":"quittance-loyer-demander","title":"Quittance de loyer : demander le bon justificatif","description":"Obtenir une preuve du paiement du loyer et des charges.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : distinguez une quittance d’un simple avis demandant de payer.","sections":[{"title":"Vérifier le paiement","paragraphs":["Une quittance atteste du règlement du loyer et des charges. L’avis d’échéance annonce une somme à payer et ne prouve pas son règlement. Conservez également votre propre preuve de paiement."]},{"title":"Faire une demande précise","paragraphs":["Demandez au bailleur ou à l’agence les quittances des mois concernés. Elles doivent distinguer le loyer et les charges et être transmises gratuitement. L’envoi par courriel est possible avec votre accord."]},{"title":"Contrôler le document","paragraphs":["Vérifiez la période, l’adresse et les montants. En cas de paiement partiel, le document adapté est un reçu indiquant la somme versée. Classez vos justificatifs par année pour les retrouver lors d’une nouvelle recherche de logement."]}],"checklist":["Période précisée.","Loyer et charges détaillés.","Quittance ou reçu classé."],"sources":[{"kind":"reference","label":"Service Public — Documents remis par le bailleur","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2066"}],"order":100,"subcategory":"","homeRank":0,"tagSlugs":["logement","recours"]}','{"kind":"guides","slug":"quittance-loyer-demander","title":"Quittance de loyer : demander le bon justificatif","description":"Obtenir une preuve du paiement du loyer et des charges.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : distinguez une quittance d’un simple avis demandant de payer.","sections":[{"title":"Vérifier le paiement","paragraphs":["Une quittance atteste du règlement du loyer et des charges. L’avis d’échéance annonce une somme à payer et ne prouve pas son règlement. Conservez également votre propre preuve de paiement."]},{"title":"Faire une demande précise","paragraphs":["Demandez au bailleur ou à l’agence les quittances des mois concernés. Elles doivent distinguer le loyer et les charges et être transmises gratuitement. L’envoi par courriel est possible avec votre accord."]},{"title":"Contrôler le document","paragraphs":["Vérifiez la période, l’adresse et les montants. En cas de paiement partiel, le document adapté est un reçu indiquant la somme versée. Classez vos justificatifs par année pour les retrouver lors d’une nouvelle recherche de logement."]}],"checklist":["Période précisée.","Loyer et charges détaillés.","Quittance ou reçu classé."],"sources":[{"kind":"reference","label":"Service Public — Documents remis par le bailleur","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2066"}],"order":100,"subcategory":"","homeRank":0,"tagSlugs":["logement","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
