INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/preavis-location-depart','{"kind":"guides","slug":"preavis-location-depart","title":"Quitter sa location : sécuriser la date du préavis","description":"Choisir la bonne forme de congé et garder la preuve de réception.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : la date d’envoi ne suffit pas à fixer la fin du bail.","sections":[{"title":"Identifier votre situation","paragraphs":["Vérifiez si le logement est vide ou meublé et si un motif permet un délai réduit. Utilisez la fiche officielle pour votre cas et joignez les justificatifs requis. Un départ en couple ou en colocation demande aussi des vérifications."]},{"title":"Utiliser une forme valable","paragraphs":["Le congé peut être adressé par recommandé avec avis de réception, remis contre récépissé signé ou signifié par commissaire de justice. Un simple courriel ne suffit pas. Gardez une copie complète."]},{"title":"Calculer depuis le bon événement","paragraphs":["Pour un recommandé, le délai commence à la réception effective par le destinataire. Une lettre non retirée peut compromettre le calendrier. Vérifiez la preuve de remise avant de fixer définitivement déménagement et état des lieux."]}],"checklist":["Délai applicable vérifié.","Congé formalisé.","Réception suivie."],"sources":[{"kind":"reference","label":"Service Public — Préavis du locataire","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F1168"}],"order":101,"subcategory":"","homeRank":0,"tagSlugs":["logement","decisions"]}','{"kind":"guides","slug":"preavis-location-depart","title":"Quitter sa location : sécuriser la date du préavis","description":"Choisir la bonne forme de congé et garder la preuve de réception.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : la date d’envoi ne suffit pas à fixer la fin du bail.","sections":[{"title":"Identifier votre situation","paragraphs":["Vérifiez si le logement est vide ou meublé et si un motif permet un délai réduit. Utilisez la fiche officielle pour votre cas et joignez les justificatifs requis. Un départ en couple ou en colocation demande aussi des vérifications."]},{"title":"Utiliser une forme valable","paragraphs":["Le congé peut être adressé par recommandé avec avis de réception, remis contre récépissé signé ou signifié par commissaire de justice. Un simple courriel ne suffit pas. Gardez une copie complète."]},{"title":"Calculer depuis le bon événement","paragraphs":["Pour un recommandé, le délai commence à la réception effective par le destinataire. Une lettre non retirée peut compromettre le calendrier. Vérifiez la preuve de remise avant de fixer définitivement déménagement et état des lieux."]}],"checklist":["Délai applicable vérifié.","Congé formalisé.","Réception suivie."],"sources":[{"kind":"reference","label":"Service Public — Préavis du locataire","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F1168"}],"order":101,"subcategory":"","homeRank":0,"tagSlugs":["logement","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/guides/preavis-location-depart','guides/preavis-location-depart',1,'{"kind":"guides","slug":"preavis-location-depart","title":"Quitter sa location : sécuriser la date du préavis","description":"Choisir la bonne forme de congé et garder la preuve de réception.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : la date d’envoi ne suffit pas à fixer la fin du bail.","sections":[{"title":"Identifier votre situation","paragraphs":["Vérifiez si le logement est vide ou meublé et si un motif permet un délai réduit. Utilisez la fiche officielle pour votre cas et joignez les justificatifs requis. Un départ en couple ou en colocation demande aussi des vérifications."]},{"title":"Utiliser une forme valable","paragraphs":["Le congé peut être adressé par recommandé avec avis de réception, remis contre récépissé signé ou signifié par commissaire de justice. Un simple courriel ne suffit pas. Gardez une copie complète."]},{"title":"Calculer depuis le bon événement","paragraphs":["Pour un recommandé, le délai commence à la réception effective par le destinataire. Une lettre non retirée peut compromettre le calendrier. Vérifiez la preuve de remise avant de fixer définitivement déménagement et état des lieux."]}],"checklist":["Délai applicable vérifié.","Congé formalisé.","Réception suivie."],"sources":[{"kind":"reference","label":"Service Public — Préavis du locataire","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F1168"}],"order":101,"subcategory":"","homeRank":0,"tagSlugs":["logement","decisions"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/charges-location-regularisation','{"kind":"guides","slug":"charges-location-regularisation","title":"Charges locatives : comprendre la régularisation","description":"Comparer les provisions aux dépenses justifiées.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : vérifiez d’abord si vos charges sont au forfait ou au réel.","sections":[{"title":"Relire le bail","paragraphs":["Un forfait, possible dans certains baux, ne suit pas la même logique que des provisions régularisées. Identifiez la formule prévue avant d’examiner une demande de complément."]},{"title":"Comparer les bons montants","paragraphs":["Pour les provisions, la régularisation rapproche les sommes versées des dépenses récupérables effectives. Le bailleur doit communiquer le décompte par nature et la répartition. Un trop-perçu doit être reversé ; un manque peut entraîner un complément."]},{"title":"Demander les justificatifs","paragraphs":["Les pièces doivent rester à disposition pendant six mois après l’envoi du décompte. Repérez les lignes incomprises et demandez une explication écrite. En cas de difficulté financière ou de désaccord, sollicitez un accompagnement avant de laisser la situation s’aggraver."]}],"checklist":["Forfait ou provisions identifié.","Décompte rapproché des versements.","Justificatifs demandés si besoin."],"sources":[{"kind":"reference","label":"Service Public — Charges locatives","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F947"}],"order":102,"subcategory":"","homeRank":0,"tagSlugs":["budget","logement","recours"]}','{"kind":"guides","slug":"charges-location-regularisation","title":"Charges locatives : comprendre la régularisation","description":"Comparer les provisions aux dépenses justifiées.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : vérifiez d’abord si vos charges sont au forfait ou au réel.","sections":[{"title":"Relire le bail","paragraphs":["Un forfait, possible dans certains baux, ne suit pas la même logique que des provisions régularisées. Identifiez la formule prévue avant d’examiner une demande de complément."]},{"title":"Comparer les bons montants","paragraphs":["Pour les provisions, la régularisation rapproche les sommes versées des dépenses récupérables effectives. Le bailleur doit communiquer le décompte par nature et la répartition. Un trop-perçu doit être reversé ; un manque peut entraîner un complément."]},{"title":"Demander les justificatifs","paragraphs":["Les pièces doivent rester à disposition pendant six mois après l’envoi du décompte. Repérez les lignes incomprises et demandez une explication écrite. En cas de difficulté financière ou de désaccord, sollicitez un accompagnement avant de laisser la situation s’aggraver."]}],"checklist":["Forfait ou provisions identifié.","Décompte rapproché des versements.","Justificatifs demandés si besoin."],"sources":[{"kind":"reference","label":"Service Public — Charges locatives","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F947"}],"order":102,"subcategory":"","homeRank":0,"tagSlugs":["budget","logement","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
