INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/revision-loyer-verifier','{"kind":"guides","slug":"revision-loyer-verifier","title":"Hausse de loyer : vérifier la clause avant le calcul","description":"Contrôler une révision annuelle en cours de bail.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : une augmentation annuelle n’est pas automatique.","sections":[{"title":"Chercher la clause","paragraphs":["Dans le cas général d’un bail d’habitation privé, la révision annuelle doit être prévue au contrat. Retrouvez la clause, la date de révision et l’indice de référence utilisé avant de contrôler le nouveau montant."]},{"title":"Vérifier les restrictions","paragraphs":["Des règles particulières concernent notamment les logements classés F ou G, selon la date du bail et le territoire. Les logements sociaux, conventionnés ou soumis à la loi de 1948 demandent une vérification distincte."]},{"title":"Reconstituer la demande","paragraphs":["Demandez le détail du calcul et comparez les indices correspondants dans la fiche officielle ou son simulateur. Gardez le bail, le DPE et le courrier de hausse. Si les éléments ne concordent pas, demandez conseil à l’ADIL."]}],"checklist":["Clause retrouvée.","Type de bail et DPE vérifiés.","Calcul documenté."],"sources":[{"kind":"reference","label":"Service Public — Révision du loyer","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F1311"}],"order":103,"subcategory":"","homeRank":0,"tagSlugs":["budget","logement","recours"]}','{"kind":"guides","slug":"revision-loyer-verifier","title":"Hausse de loyer : vérifier la clause avant le calcul","description":"Contrôler une révision annuelle en cours de bail.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : une augmentation annuelle n’est pas automatique.","sections":[{"title":"Chercher la clause","paragraphs":["Dans le cas général d’un bail d’habitation privé, la révision annuelle doit être prévue au contrat. Retrouvez la clause, la date de révision et l’indice de référence utilisé avant de contrôler le nouveau montant."]},{"title":"Vérifier les restrictions","paragraphs":["Des règles particulières concernent notamment les logements classés F ou G, selon la date du bail et le territoire. Les logements sociaux, conventionnés ou soumis à la loi de 1948 demandent une vérification distincte."]},{"title":"Reconstituer la demande","paragraphs":["Demandez le détail du calcul et comparez les indices correspondants dans la fiche officielle ou son simulateur. Gardez le bail, le DPE et le courrier de hausse. Si les éléments ne concordent pas, demandez conseil à l’ADIL."]}],"checklist":["Clause retrouvée.","Type de bail et DPE vérifiés.","Calcul documenté."],"sources":[{"kind":"reference","label":"Service Public — Révision du loyer","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F1311"}],"order":103,"subcategory":"","homeRank":0,"tagSlugs":["budget","logement","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
