INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/dossier-location-justificatifs','{"kind":"guides","slug":"dossier-location-justificatifs","title":"Dossier de location : transmettre seulement les pièces autorisées","description":"Préparer sa candidature sans multiplier les documents sensibles.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : un dossier complet ne signifie pas donner tous ses documents personnels.","sections":[{"title":"Partir de la liste officielle","paragraphs":["Le bailleur peut vérifier identité, domicile, activité et ressources avec certains justificatifs autorisés. Comparez sa demande à la liste de Service Public plutôt que de fournir tout ce qui vous est réclamé."]},{"title":"Choisir un envoi maîtrisé","paragraphs":["Le service public DossierFacile permet de préparer et partager les justificatifs du dossier. Vérifiez toujours l’identité du destinataire et le logement concerné avant de transmettre des pièces contenant des données personnelles."]},{"title":"Refuser la réservation payante","paragraphs":["Pour un bail d’habitation, aucune somme ne doit être réclamée par le propriétaire avant sa signature pour réserver le logement. Gardez l’annonce et les échanges si l’on vous presse de payer pour obtenir une visite ou bloquer le bien."]}],"checklist":["Pièces comparées à la liste.","Destinataire vérifié.","Aucun paiement de réservation."],"sources":[{"kind":"reference","label":"Service Public — Justificatifs du futur locataire","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F1169"}],"order":104,"subcategory":"","homeRank":0,"tagSlugs":["donnees-personnelles","arnaques","logement"]}','{"kind":"guides","slug":"dossier-location-justificatifs","title":"Dossier de location : transmettre seulement les pièces autorisées","description":"Préparer sa candidature sans multiplier les documents sensibles.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : un dossier complet ne signifie pas donner tous ses documents personnels.","sections":[{"title":"Partir de la liste officielle","paragraphs":["Le bailleur peut vérifier identité, domicile, activité et ressources avec certains justificatifs autorisés. Comparez sa demande à la liste de Service Public plutôt que de fournir tout ce qui vous est réclamé."]},{"title":"Choisir un envoi maîtrisé","paragraphs":["Le service public DossierFacile permet de préparer et partager les justificatifs du dossier. Vérifiez toujours l’identité du destinataire et le logement concerné avant de transmettre des pièces contenant des données personnelles."]},{"title":"Refuser la réservation payante","paragraphs":["Pour un bail d’habitation, aucune somme ne doit être réclamée par le propriétaire avant sa signature pour réserver le logement. Gardez l’annonce et les échanges si l’on vous presse de payer pour obtenir une visite ou bloquer le bien."]}],"checklist":["Pièces comparées à la liste.","Destinataire vérifié.","Aucun paiement de réservation."],"sources":[{"kind":"reference","label":"Service Public — Justificatifs du futur locataire","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F1169"}],"order":104,"subcategory":"","homeRank":0,"tagSlugs":["donnees-personnelles","arnaques","logement"]}',1,'2026-10-01T06:41:56.605Z','migration');
