INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/colocation-bail-solidarite','{"kind":"guides","slug":"colocation-bail-solidarite","title":"Colocation : lire la solidarité avant de partager le loyer","description":"Comprendre ce que votre signature peut vous engager à payer.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : la répartition entre colocataires ne limite pas toujours ce que le bailleur peut réclamer.","sections":[{"title":"Identifier le contrat","paragraphs":["Bail commun ou contrats individuels : commencez par ce choix. Dans un bail commun, chaque colocataire doit signer et conserver un exemplaire. Payer une part sans être signataire ne donne pas les mêmes droits."]},{"title":"Examiner la solidarité","paragraphs":["Avec une clause de solidarité, un colocataire peut devoir payer les sommes impayées par les autres. Ne vous contentez pas de votre accord oral sur le partage du loyer : lisez aussi les engagements des cautions."]},{"title":"Prévoir le départ","paragraphs":["Le départ d’un occupant ne met pas automatiquement fin à tous ses engagements. Vérifiez les règles du préavis, du remplacement et de la solidarité. Écrivez entre colocataires comment seront traitées les dépenses communes et la part du dépôt de garantie."]}],"checklist":["Signatures vérifiées.","Solidarité comprise.","Modalités de départ préparées."],"sources":[{"kind":"reference","label":"Service Public — Colocation","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F34661"}],"order":105,"subcategory":"","homeRank":0,"tagSlugs":["budget","logement"]}','{"kind":"guides","slug":"colocation-bail-solidarite","title":"Colocation : lire la solidarité avant de partager le loyer","description":"Comprendre ce que votre signature peut vous engager à payer.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : la répartition entre colocataires ne limite pas toujours ce que le bailleur peut réclamer.","sections":[{"title":"Identifier le contrat","paragraphs":["Bail commun ou contrats individuels : commencez par ce choix. Dans un bail commun, chaque colocataire doit signer et conserver un exemplaire. Payer une part sans être signataire ne donne pas les mêmes droits."]},{"title":"Examiner la solidarité","paragraphs":["Avec une clause de solidarité, un colocataire peut devoir payer les sommes impayées par les autres. Ne vous contentez pas de votre accord oral sur le partage du loyer : lisez aussi les engagements des cautions."]},{"title":"Prévoir le départ","paragraphs":["Le départ d’un occupant ne met pas automatiquement fin à tous ses engagements. Vérifiez les règles du préavis, du remplacement et de la solidarité. Écrivez entre colocataires comment seront traitées les dépenses communes et la part du dépôt de garantie."]}],"checklist":["Signatures vérifiées.","Solidarité comprise.","Modalités de départ préparées."],"sources":[{"kind":"reference","label":"Service Public — Colocation","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F34661"}],"order":105,"subcategory":"","homeRank":0,"tagSlugs":["budget","logement"]}',1,'2026-10-01T06:41:56.605Z','migration');
