INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/se-porter-caution-location','{"kind":"guides","slug":"se-porter-caution-location","title":"Se porter caution : mesurer l’engagement avant de signer","description":"Comprendre les dettes couvertes et le type de cautionnement.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : être garant peut engager vos revenus et votre patrimoine.","sections":[{"title":"Distinguer les termes","paragraphs":["La caution est la personne ou l’organisme qui garantit les dettes du locataire. Le dépôt de garantie est une somme versée au bailleur : ce sont deux mécanismes différents. Lisez l’acte proposé dans son ensemble."]},{"title":"Repérer la solidarité","paragraphs":["Une caution solidaire peut être sollicitée dès le premier impayé sans recherche préalable du paiement auprès du locataire. Vérifiez le type de caution, les dettes concernées, la durée et les limites de votre engagement."]},{"title":"Évaluer votre capacité","paragraphs":["Chiffrez ce que vous pourriez réellement payer si le locataire rencontre une difficulté. Conservez l’acte signé et les documents du bail. Demandez une explication avant de signer toute formulation que vous ne comprenez pas."]}],"checklist":["Caution distinguée du dépôt.","Durée et étendue relues.","Capacité financière évaluée."],"sources":[{"kind":"reference","label":"Service Public — Caution locative","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31267"}],"order":106,"subcategory":"","homeRank":0,"tagSlugs":["budget","logement","decisions"]}','{"kind":"guides","slug":"se-porter-caution-location","title":"Se porter caution : mesurer l’engagement avant de signer","description":"Comprendre les dettes couvertes et le type de cautionnement.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : être garant peut engager vos revenus et votre patrimoine.","sections":[{"title":"Distinguer les termes","paragraphs":["La caution est la personne ou l’organisme qui garantit les dettes du locataire. Le dépôt de garantie est une somme versée au bailleur : ce sont deux mécanismes différents. Lisez l’acte proposé dans son ensemble."]},{"title":"Repérer la solidarité","paragraphs":["Une caution solidaire peut être sollicitée dès le premier impayé sans recherche préalable du paiement auprès du locataire. Vérifiez le type de caution, les dettes concernées, la durée et les limites de votre engagement."]},{"title":"Évaluer votre capacité","paragraphs":["Chiffrez ce que vous pourriez réellement payer si le locataire rencontre une difficulté. Conservez l’acte signé et les documents du bail. Demandez une explication avant de signer toute formulation que vous ne comprenez pas."]}],"checklist":["Caution distinguée du dépôt.","Durée et étendue relues.","Capacité financière évaluée."],"sources":[{"kind":"reference","label":"Service Public — Caution locative","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31267"}],"order":106,"subcategory":"","homeRank":0,"tagSlugs":["budget","logement","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
