INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/sous-location-autorisation','{"kind":"guides","slug":"sous-location-autorisation","title":"Sous-location : obtenir l’accord avant de publier l’annonce","description":"Vérifier les conditions d’une sous-location classique dans le privé.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : une absence temporaire ne vous autorise pas à sous-louer librement.","sections":[{"title":"Vérifier le régime du bail","paragraphs":["Les règles diffèrent selon le logement et le contrat. Pour une sous-location classique d’un logement vide du secteur privé, l’accord écrit du propriétaire porte sur le principe et sur le montant du loyer demandé."]},{"title":"Encadrer le prix et la durée","paragraphs":["Dans ce cas, le loyer au mètre carré de la sous-location ne peut dépasser celui que vous payez. Sa durée ne peut aller au-delà de votre propre bail. Ne transposez pas ces repères aux régimes particuliers sans vérification."]},{"title":"Transmettre les documents","paragraphs":["Le sous-locataire doit recevoir l’autorisation écrite et une copie du bail en cours. Une sous-location non autorisée peut mener à la résiliation et à des demandes financières. Faites vérifier le projet avant toute réservation."]}],"checklist":["Régime identifié.","Accord écrit obtenu.","Documents transmis."],"sources":[{"kind":"reference","label":"Service Public — Sous-location","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2449"}],"order":107,"subcategory":"","homeRank":0,"tagSlugs":["logement","decisions"]}','{"kind":"guides","slug":"sous-location-autorisation","title":"Sous-location : obtenir l’accord avant de publier l’annonce","description":"Vérifier les conditions d’une sous-location classique dans le privé.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : une absence temporaire ne vous autorise pas à sous-louer librement.","sections":[{"title":"Vérifier le régime du bail","paragraphs":["Les règles diffèrent selon le logement et le contrat. Pour une sous-location classique d’un logement vide du secteur privé, l’accord écrit du propriétaire porte sur le principe et sur le montant du loyer demandé."]},{"title":"Encadrer le prix et la durée","paragraphs":["Dans ce cas, le loyer au mètre carré de la sous-location ne peut dépasser celui que vous payez. Sa durée ne peut aller au-delà de votre propre bail. Ne transposez pas ces repères aux régimes particuliers sans vérification."]},{"title":"Transmettre les documents","paragraphs":["Le sous-locataire doit recevoir l’autorisation écrite et une copie du bail en cours. Une sous-location non autorisée peut mener à la résiliation et à des demandes financières. Faites vérifier le projet avant toute réservation."]}],"checklist":["Régime identifié.","Accord écrit obtenu.","Documents transmis."],"sources":[{"kind":"reference","label":"Service Public — Sous-location","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F2449"}],"order":107,"subcategory":"","homeRank":0,"tagSlugs":["logement","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
