INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/entretien-locataire','{"kind":"guides","slug":"entretien-locataire","title":"Locataire : organiser l’entretien courant du logement","description":"Repérer les petits gestes et garder les justificatifs.","categoryId":"argent-consommation","themeId":"travaux","reviewedAt":"2026-09-29","intro":"La règle d’or : traitez les petits défauts tôt sans vous attribuer toutes les réparations.","sections":[{"title":"Repérer les tâches courantes","paragraphs":["L’entretien comprend notamment le nettoyage et certaines petites réparations : mécanismes de portes, poignées ou joints selon les cas. Consultez la liste officielle par équipement pour préparer un suivi adapté à votre logement."]},{"title":"Documenter une anomalie","paragraphs":["Notez le défaut, sa date et les circonstances ; photographiez-le si utile. Une panne ne signifie pas automatiquement que tout remplacement vous incombe. Signalez au bailleur ce qui semble dépasser l’entretien courant."]},{"title":"Conserver les interventions","paragraphs":["Classez factures et attestations d’entretien avec les documents du logement. N’improvisez pas une intervention technique dangereuse. Lors d’un désaccord, faites préciser la cause du problème et la répartition des obligations avant de commander les travaux."]}],"checklist":["Équipements suivis.","Anomalies signalées.","Justificatifs conservés."],"sources":[{"kind":"reference","label":"Service Public — Entretien et réparations locatives","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31697"}],"order":108,"subcategory":"","homeRank":0,"tagSlugs":["logement","travaux"]}','{"kind":"guides","slug":"entretien-locataire","title":"Locataire : organiser l’entretien courant du logement","description":"Repérer les petits gestes et garder les justificatifs.","categoryId":"argent-consommation","themeId":"travaux","reviewedAt":"2026-09-29","intro":"La règle d’or : traitez les petits défauts tôt sans vous attribuer toutes les réparations.","sections":[{"title":"Repérer les tâches courantes","paragraphs":["L’entretien comprend notamment le nettoyage et certaines petites réparations : mécanismes de portes, poignées ou joints selon les cas. Consultez la liste officielle par équipement pour préparer un suivi adapté à votre logement."]},{"title":"Documenter une anomalie","paragraphs":["Notez le défaut, sa date et les circonstances ; photographiez-le si utile. Une panne ne signifie pas automatiquement que tout remplacement vous incombe. Signalez au bailleur ce qui semble dépasser l’entretien courant."]},{"title":"Conserver les interventions","paragraphs":["Classez factures et attestations d’entretien avec les documents du logement. N’improvisez pas une intervention technique dangereuse. Lors d’un désaccord, faites préciser la cause du problème et la répartition des obligations avant de commander les travaux."]}],"checklist":["Équipements suivis.","Anomalies signalées.","Justificatifs conservés."],"sources":[{"kind":"reference","label":"Service Public — Entretien et réparations locatives","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31697"}],"order":108,"subcategory":"","homeRank":0,"tagSlugs":["logement","travaux"]}',1,'2026-10-01T06:41:56.605Z','migration');
