INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/bruit-voisinage-demarches','{"kind":"guides","slug":"bruit-voisinage-demarches","title":"Voisin bruyant : décrire les faits avant d’escalader","description":"Chercher une solution et constituer un dossier précis.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : des dates et des faits sont plus utiles qu’un échange agressif.","sections":[{"title":"Décrire la gêne","paragraphs":["Notez origine, fréquence, durée et horaires des bruits. Un trouble peut exister aussi en journée : la situation ne se résume pas à une autorisation de faire du bruit avant 22 heures."]},{"title":"Commencer par une démarche calme","paragraphs":["Lorsque la situation le permet, expliquez la gêne au voisin. Si elle persiste, adressez un courrier puis un recommandé. Consultez le règlement de copropriété et les règles locales ; informez les interlocuteurs concernés."]},{"title":"Préparer la suite","paragraphs":["Gardez les échanges et des preuves recueillies loyalement, sans filmer quelqu’un chez lui à son insu. Un conciliateur peut aider à rechercher un accord. Faites-vous renseigner sur les démarches préalables avant une action judiciaire."]}],"checklist":["Faits datés.","Démarches écrites conservées.","Solution amiable recherchée."],"sources":[{"kind":"reference","label":"Service Public — Bruits de voisinage","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F612"}],"order":109,"subcategory":"","homeRank":0,"tagSlugs":["logement","recours"]}','{"kind":"guides","slug":"bruit-voisinage-demarches","title":"Voisin bruyant : décrire les faits avant d’escalader","description":"Chercher une solution et constituer un dossier précis.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : des dates et des faits sont plus utiles qu’un échange agressif.","sections":[{"title":"Décrire la gêne","paragraphs":["Notez origine, fréquence, durée et horaires des bruits. Un trouble peut exister aussi en journée : la situation ne se résume pas à une autorisation de faire du bruit avant 22 heures."]},{"title":"Commencer par une démarche calme","paragraphs":["Lorsque la situation le permet, expliquez la gêne au voisin. Si elle persiste, adressez un courrier puis un recommandé. Consultez le règlement de copropriété et les règles locales ; informez les interlocuteurs concernés."]},{"title":"Préparer la suite","paragraphs":["Gardez les échanges et des preuves recueillies loyalement, sans filmer quelqu’un chez lui à son insu. Un conciliateur peut aider à rechercher un accord. Faites-vous renseigner sur les démarches préalables avant une action judiciaire."]}],"checklist":["Faits datés.","Démarches écrites conservées.","Solution amiable recherchée."],"sources":[{"kind":"reference","label":"Service Public — Bruits de voisinage","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F612"}],"order":109,"subcategory":"","homeRank":0,"tagSlugs":["logement","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
