INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/demenagement-demarches','{"kind":"guides","slug":"demenagement-demarches","title":"Déménagement : préparer les démarches des deux logements","description":"Coordonner contrats, adresse et relevés de compteurs.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : traitez le départ et l’arrivée dans un même calendrier.","sections":[{"title":"Préparer les échéances","paragraphs":["Notez préavis, remise des clés, état des lieux et date d’entrée. Ajoutez les démarches scolaires ou professionnelles qui vous concernent. Les délais ne sont pas identiques pour tous les organismes."]},{"title":"Organiser les contrats","paragraphs":["Contactez les fournisseurs d’énergie pour l’ancien et le nouveau logement, puis relevez les compteurs aux dates utiles. Vérifiez assurance, eau et accès internet plutôt que de supposer que les contrats suivent automatiquement."]},{"title":"Mettre à jour les coordonnées","paragraphs":["Déclarez l’adresse aux organismes concernés : administrations, banque, assureur et autres correspondants. Le téléservice de changement d’adresse peut regrouper plusieurs démarches, mais pas toutes. Conservez les confirmations et suivez les dernières factures de l’ancienne adresse."]}],"checklist":["Calendrier de départ et arrivée.","Contrats et relevés suivis.","Changements d’adresse confirmés."],"sources":[{"kind":"reference","label":"Service Public — Déménager en France","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F14128"}],"order":110,"subcategory":"","homeRank":0,"tagSlugs":["budget","logement"]}','{"kind":"guides","slug":"demenagement-demarches","title":"Déménagement : préparer les démarches des deux logements","description":"Coordonner contrats, adresse et relevés de compteurs.","categoryId":"argent-consommation","themeId":"logement","reviewedAt":"2026-09-29","intro":"La règle d’or : traitez le départ et l’arrivée dans un même calendrier.","sections":[{"title":"Préparer les échéances","paragraphs":["Notez préavis, remise des clés, état des lieux et date d’entrée. Ajoutez les démarches scolaires ou professionnelles qui vous concernent. Les délais ne sont pas identiques pour tous les organismes."]},{"title":"Organiser les contrats","paragraphs":["Contactez les fournisseurs d’énergie pour l’ancien et le nouveau logement, puis relevez les compteurs aux dates utiles. Vérifiez assurance, eau et accès internet plutôt que de supposer que les contrats suivent automatiquement."]},{"title":"Mettre à jour les coordonnées","paragraphs":["Déclarez l’adresse aux organismes concernés : administrations, banque, assureur et autres correspondants. Le téléservice de changement d’adresse peut regrouper plusieurs démarches, mais pas toutes. Conservez les confirmations et suivez les dernières factures de l’ancienne adresse."]}],"checklist":["Calendrier de départ et arrivée.","Contrats et relevés suivis.","Changements d’adresse confirmés."],"sources":[{"kind":"reference","label":"Service Public — Déménager en France","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F14128"}],"order":110,"subcategory":"","homeRank":0,"tagSlugs":["budget","logement"]}',1,'2026-10-01T06:41:56.605Z','migration');
