INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/auto-ecole-comparer','{"kind":"guides","slug":"auto-ecole-comparer","title":"Auto-école : comparer le contrat, pas seulement le forfait","description":"Évaluer le contenu de la formation et les frais supplémentaires.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : comparez le coût d’un parcours réaliste plutôt que le prix d’appel.","sections":[{"title":"Vérifier l’établissement","paragraphs":["Repérez son agrément et demandez les modalités de formation. La proximité peut compter autant que le tarif si les créneaux disponibles ne correspondent pas à votre emploi du temps."]},{"title":"Décomposer le forfait","paragraphs":["Comparez le nombre et la durée des leçons, les prestations incluses, le prix des heures supplémentaires et la durée de validité du forfait. Demandez les conditions d’annulation des rendez-vous avant de vous engager."]},{"title":"Lire avant de signer","paragraphs":["Pour le permis B, un contrat-type formalise les obligations de chacun. Prenez le temps de le lire et conservez votre exemplaire avec les justificatifs de paiement. Faites préciser par écrit les promesses importantes faites oralement."]}],"checklist":["Agrément repéré.","Prestations et suppléments comparés.","Contrat conservé."],"sources":[{"kind":"reference","label":"DGCCRF — Auto-école","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/auto-ecole"}],"order":111,"subcategory":"","homeRank":0,"tagSlugs":["budget","automobile"]}','{"kind":"guides","slug":"auto-ecole-comparer","title":"Auto-école : comparer le contrat, pas seulement le forfait","description":"Évaluer le contenu de la formation et les frais supplémentaires.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : comparez le coût d’un parcours réaliste plutôt que le prix d’appel.","sections":[{"title":"Vérifier l’établissement","paragraphs":["Repérez son agrément et demandez les modalités de formation. La proximité peut compter autant que le tarif si les créneaux disponibles ne correspondent pas à votre emploi du temps."]},{"title":"Décomposer le forfait","paragraphs":["Comparez le nombre et la durée des leçons, les prestations incluses, le prix des heures supplémentaires et la durée de validité du forfait. Demandez les conditions d’annulation des rendez-vous avant de vous engager."]},{"title":"Lire avant de signer","paragraphs":["Pour le permis B, un contrat-type formalise les obligations de chacun. Prenez le temps de le lire et conservez votre exemplaire avec les justificatifs de paiement. Faites préciser par écrit les promesses importantes faites oralement."]}],"checklist":["Agrément repéré.","Prestations et suppléments comparés.","Contrat conservé."],"sources":[{"kind":"reference","label":"DGCCRF — Auto-école","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/auto-ecole"}],"order":111,"subcategory":"","homeRank":0,"tagSlugs":["budget","automobile"]}',1,'2026-10-01T06:41:56.605Z','migration');
