INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/voiture-neuve-bon-commande','{"kind":"guides","slug":"voiture-neuve-bon-commande","title":"Voiture neuve : relire le bon de commande ligne par ligne","description":"Fixer le modèle, le prix et la livraison par écrit.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : le véhicule commandé doit être décrit aussi précisément que celui présenté.","sections":[{"title":"Identifier la version","paragraphs":["Vérifiez modèle, motorisation, version, équipements et options. Une photo ou une brochure générale ne remplace pas le détail de la commande. Faites corriger toute différence avant signature."]},{"title":"Comprendre le prix","paragraphs":["Distinguez le prix TTC et les options expressément demandées. Les frais de préparation obligatoires ne doivent pas réapparaître comme un forfait ajouté au prix annoncé. Contrôlez aussi le mode de financement indiqué."]},{"title":"Préparer la livraison","paragraphs":["Retrouvez la date limite prévue. Lors de la remise, comparez le véhicule aux documents, examinez son état et demandez les pièces nécessaires. Conservez commande, facture, garanties et futurs justificatifs d’entretien dans un même dossier."]}],"checklist":["Version et options exactes.","Prix détaillé.","Date et conformité contrôlées."],"sources":[{"kind":"reference","label":"DGCCRF — Achat d’un véhicule neuf","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/achat-dun-vehicule-neuf-quelles-sont-les-obligations-du-vendeur"}],"order":112,"subcategory":"","homeRank":0,"tagSlugs":["budget","automobile"]}','{"kind":"guides","slug":"voiture-neuve-bon-commande","title":"Voiture neuve : relire le bon de commande ligne par ligne","description":"Fixer le modèle, le prix et la livraison par écrit.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : le véhicule commandé doit être décrit aussi précisément que celui présenté.","sections":[{"title":"Identifier la version","paragraphs":["Vérifiez modèle, motorisation, version, équipements et options. Une photo ou une brochure générale ne remplace pas le détail de la commande. Faites corriger toute différence avant signature."]},{"title":"Comprendre le prix","paragraphs":["Distinguez le prix TTC et les options expressément demandées. Les frais de préparation obligatoires ne doivent pas réapparaître comme un forfait ajouté au prix annoncé. Contrôlez aussi le mode de financement indiqué."]},{"title":"Préparer la livraison","paragraphs":["Retrouvez la date limite prévue. Lors de la remise, comparez le véhicule aux documents, examinez son état et demandez les pièces nécessaires. Conservez commande, facture, garanties et futurs justificatifs d’entretien dans un même dossier."]}],"checklist":["Version et options exactes.","Prix détaillé.","Date et conformité contrôlées."],"sources":[{"kind":"reference","label":"DGCCRF — Achat d’un véhicule neuf","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/achat-dun-vehicule-neuf-quelles-sont-les-obligations-du-vendeur"}],"order":112,"subcategory":"","homeRank":0,"tagSlugs":["budget","automobile"]}',1,'2026-10-01T06:41:56.605Z','migration');
