INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/controle-technique-anticiper','{"kind":"guides","slug":"controle-technique-anticiper","title":"Contrôle technique : lire le procès-verbal, pas seulement la vignette","description":"Anticiper les échéances et les suites des défaillances relevées.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : le résultat du contrôle doit déclencher les actions nécessaires.","sections":[{"title":"Vérifier votre échéance","paragraphs":["La périodicité dépend du type et de l’âge du véhicule. Retrouvez sa catégorie et la date du précédent contrôle. Réservez dans un centre agréé suffisamment tôt pour pouvoir organiser d’éventuelles réparations."]},{"title":"Comprendre le résultat","paragraphs":["Lisez les défaillances indiquées et demandez au centre ce qu’elles impliquent. Une contre-visite, un délai ou une restriction de circulation ne se devinent pas à partir d’une simple remarque orale."]},{"title":"Organiser la suite","paragraphs":["Conservez le procès-verbal et faites établir les réparations nécessaires. Notez la date limite applicable à votre situation. Le contrôle technique ne remplace pas l’entretien du véhicule et ne garantit pas l’absence de panne future."]}],"checklist":["Catégorie et échéance vérifiées.","Procès-verbal compris.","Réparations et contre-visite planifiées."],"sources":[{"kind":"reference","label":"DGCCRF — Contrôle technique","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/controle-technique-comment-proceder"}],"order":113,"subcategory":"","homeRank":0,"tagSlugs":["automobile"]}','{"kind":"guides","slug":"controle-technique-anticiper","title":"Contrôle technique : lire le procès-verbal, pas seulement la vignette","description":"Anticiper les échéances et les suites des défaillances relevées.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : le résultat du contrôle doit déclencher les actions nécessaires.","sections":[{"title":"Vérifier votre échéance","paragraphs":["La périodicité dépend du type et de l’âge du véhicule. Retrouvez sa catégorie et la date du précédent contrôle. Réservez dans un centre agréé suffisamment tôt pour pouvoir organiser d’éventuelles réparations."]},{"title":"Comprendre le résultat","paragraphs":["Lisez les défaillances indiquées et demandez au centre ce qu’elles impliquent. Une contre-visite, un délai ou une restriction de circulation ne se devinent pas à partir d’une simple remarque orale."]},{"title":"Organiser la suite","paragraphs":["Conservez le procès-verbal et faites établir les réparations nécessaires. Notez la date limite applicable à votre situation. Le contrôle technique ne remplace pas l’entretien du véhicule et ne garantit pas l’absence de panne future."]}],"checklist":["Catégorie et échéance vérifiées.","Procès-verbal compris.","Réparations et contre-visite planifiées."],"sources":[{"kind":"reference","label":"DGCCRF — Contrôle technique","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/controle-technique-comment-proceder"}],"order":113,"subcategory":"","homeRank":0,"tagSlugs":["automobile"]}',1,'2026-10-01T06:41:56.605Z','migration');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/guides/controle-technique-anticiper','guides/controle-technique-anticiper',1,'{"kind":"guides","slug":"controle-technique-anticiper","title":"Contrôle technique : lire le procès-verbal, pas seulement la vignette","description":"Anticiper les échéances et les suites des défaillances relevées.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : le résultat du contrôle doit déclencher les actions nécessaires.","sections":[{"title":"Vérifier votre échéance","paragraphs":["La périodicité dépend du type et de l’âge du véhicule. Retrouvez sa catégorie et la date du précédent contrôle. Réservez dans un centre agréé suffisamment tôt pour pouvoir organiser d’éventuelles réparations."]},{"title":"Comprendre le résultat","paragraphs":["Lisez les défaillances indiquées et demandez au centre ce qu’elles impliquent. Une contre-visite, un délai ou une restriction de circulation ne se devinent pas à partir d’une simple remarque orale."]},{"title":"Organiser la suite","paragraphs":["Conservez le procès-verbal et faites établir les réparations nécessaires. Notez la date limite applicable à votre situation. Le contrôle technique ne remplace pas l’entretien du véhicule et ne garantit pas l’absence de panne future."]}],"checklist":["Catégorie et échéance vérifiées.","Procès-verbal compris.","Réparations et contre-visite planifiées."],"sources":[{"kind":"reference","label":"DGCCRF — Contrôle technique","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/controle-technique-comment-proceder"}],"order":113,"subcategory":"","homeRank":0,"tagSlugs":["automobile"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/covoiturage-assurance-frais','{"kind":"guides","slug":"covoiturage-assurance-frais","title":"Covoiturage : clarifier frais, trajet et assurance","description":"Préparer un trajet partagé sans mauvaise surprise.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : accordez-vous sur le trajet et les conditions avant le départ.","sections":[{"title":"Fixer les détails pratiques","paragraphs":["Confirmez départ, arrivée, horaires, bagages et participation aux frais. Le covoiturage correspond à un partage des coûts d’un déplacement effectué par le conducteur pour son propre compte, sans bénéfice."]},{"title":"Vérifier le contrat auto","paragraphs":["La responsabilité civile couvre les dommages causés aux passagers, mais certaines situations demandent une vérification : trajet domicile-travail ou prêt du volant notamment. Interrogez l’assureur avant de laisser un passager conduire."]},{"title":"Lire les conditions de la plateforme","paragraphs":["Regardez les frais de service, l’annulation et l’éventuelle assurance complémentaire. Conservez la réservation et les échanges utiles. Une couverture proposée par une plateforme ne dispense pas de vérifier votre propre assurance automobile."]}],"checklist":["Trajet et frais convenus.","Usages assurés vérifiés.","Conditions de réservation lues."],"sources":[{"kind":"reference","label":"DGCCRF — Covoiturage","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/covoiturage-la-reglementation-applicable"}],"order":114,"subcategory":"","homeRank":0,"tagSlugs":["budget","automobile"]}','{"kind":"guides","slug":"covoiturage-assurance-frais","title":"Covoiturage : clarifier frais, trajet et assurance","description":"Préparer un trajet partagé sans mauvaise surprise.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : accordez-vous sur le trajet et les conditions avant le départ.","sections":[{"title":"Fixer les détails pratiques","paragraphs":["Confirmez départ, arrivée, horaires, bagages et participation aux frais. Le covoiturage correspond à un partage des coûts d’un déplacement effectué par le conducteur pour son propre compte, sans bénéfice."]},{"title":"Vérifier le contrat auto","paragraphs":["La responsabilité civile couvre les dommages causés aux passagers, mais certaines situations demandent une vérification : trajet domicile-travail ou prêt du volant notamment. Interrogez l’assureur avant de laisser un passager conduire."]},{"title":"Lire les conditions de la plateforme","paragraphs":["Regardez les frais de service, l’annulation et l’éventuelle assurance complémentaire. Conservez la réservation et les échanges utiles. Une couverture proposée par une plateforme ne dispense pas de vérifier votre propre assurance automobile."]}],"checklist":["Trajet et frais convenus.","Usages assurés vérifiés.","Conditions de réservation lues."],"sources":[{"kind":"reference","label":"DGCCRF — Covoiturage","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/covoiturage-la-reglementation-applicable"}],"order":114,"subcategory":"","homeRank":0,"tagSlugs":["budget","automobile"]}',1,'2026-10-01T06:41:56.605Z','migration');
