INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/loa-contrat-cout','{"kind":"guides","slug":"loa-contrat-cout","title":"LOA : regarder au-delà du loyer mensuel","description":"Comprendre qui loue le véhicule et ce que prévoit le contrat.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : une petite mensualité ne décrit pas l’engagement complet.","sections":[{"title":"Identifier le contrat","paragraphs":["La location avec option d’achat permet de louer puis, éventuellement, d’acheter à un prix fixé dès le départ. Identifiez le bailleur financier et distinguez le contrat des documents publicitaires du concessionnaire."]},{"title":"Comparer deux scénarios","paragraphs":["Additionnez les sommes prévues en cas de restitution, puis en cas d’achat final. Examinez les conditions d’usage, les frais possibles et l’assurance. Demandez une explication écrite de chaque poste que vous ne comprenez pas."]},{"title":"Repérer les dates utiles","paragraphs":["Le délai de rétractation prévu pour la LOA court en principe pendant quatorze jours à partir de l’acceptation du contrat, pas de la livraison. Conservez le contrat complet et la notice d’assurance, avec les exclusions et la durée de couverture."]}],"checklist":["Bailleur identifié.","Coûts des deux scénarios comparés.","Dates et documents conservés."],"sources":[{"kind":"reference","label":"DGCCRF — Location avec option d’achat","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/location-avec-option-dachat-loa-dun-vehicule-quelles-sont-les-regles-connaitre"}],"order":115,"subcategory":"","homeRank":0,"tagSlugs":["budget","automobile"]}','{"kind":"guides","slug":"loa-contrat-cout","title":"LOA : regarder au-delà du loyer mensuel","description":"Comprendre qui loue le véhicule et ce que prévoit le contrat.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : une petite mensualité ne décrit pas l’engagement complet.","sections":[{"title":"Identifier le contrat","paragraphs":["La location avec option d’achat permet de louer puis, éventuellement, d’acheter à un prix fixé dès le départ. Identifiez le bailleur financier et distinguez le contrat des documents publicitaires du concessionnaire."]},{"title":"Comparer deux scénarios","paragraphs":["Additionnez les sommes prévues en cas de restitution, puis en cas d’achat final. Examinez les conditions d’usage, les frais possibles et l’assurance. Demandez une explication écrite de chaque poste que vous ne comprenez pas."]},{"title":"Repérer les dates utiles","paragraphs":["Le délai de rétractation prévu pour la LOA court en principe pendant quatorze jours à partir de l’acceptation du contrat, pas de la livraison. Conservez le contrat complet et la notice d’assurance, avec les exclusions et la durée de couverture."]}],"checklist":["Bailleur identifié.","Coûts des deux scénarios comparés.","Dates et documents conservés."],"sources":[{"kind":"reference","label":"DGCCRF — Location avec option d’achat","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/location-avec-option-dachat-loa-dun-vehicule-quelles-sont-les-regles-connaitre"}],"order":115,"subcategory":"","homeRank":0,"tagSlugs":["budget","automobile"]}',1,'2026-10-01T06:41:56.605Z','migration');
