INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/depannage-autoroute-facture','{"kind":"guides","slug":"depannage-autoroute-facture","title":"Dépannage sur autoroute : distinguer forfait et suppléments","description":"Comprendre l’intervention agréée et contrôler la facture.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : vérifiez ce qui est compris avant d’accepter des prestations supplémentaires.","sections":[{"title":"Passer par le dispositif autoroutier","paragraphs":["Après votre mise en sécurité, utilisez les moyens d’alerte de l’autoroute et indiquez votre position précise. Seules les entreprises agréées sont habilitées à intervenir sur autoroute ou route express."]},{"title":"Demander le détail du prix","paragraphs":["Les tarifs de certaines interventions sont réglementés et actualisés. Demandez le forfait applicable à votre véhicule et à l’horaire, puis ce qui serait facturé en supplément. Consultez le barème officiel actuel plutôt qu’un ancien montant mémorisé."]},{"title":"Contacter votre assistance","paragraphs":["Vérifiez la prise en charge avec l’assistance de votre contrat automobile. Conservez la facture détaillée et les échanges concernant remorquage, destination et réparation. Une intervention urgente ne justifie pas de renoncer à comprendre les prestations facturées."]}],"checklist":["Dépanneur agréé.","Forfait et suppléments expliqués.","Assistance et justificatifs suivis."],"sources":[{"kind":"reference","label":"DGCCRF — Panne sur autoroute","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/vehicules-que-faire-en-cas-de-panne-sur-autoroute"}],"order":116,"subcategory":"","homeRank":0,"tagSlugs":["budget","automobile","recours"]}','{"kind":"guides","slug":"depannage-autoroute-facture","title":"Dépannage sur autoroute : distinguer forfait et suppléments","description":"Comprendre l’intervention agréée et contrôler la facture.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : vérifiez ce qui est compris avant d’accepter des prestations supplémentaires.","sections":[{"title":"Passer par le dispositif autoroutier","paragraphs":["Après votre mise en sécurité, utilisez les moyens d’alerte de l’autoroute et indiquez votre position précise. Seules les entreprises agréées sont habilitées à intervenir sur autoroute ou route express."]},{"title":"Demander le détail du prix","paragraphs":["Les tarifs de certaines interventions sont réglementés et actualisés. Demandez le forfait applicable à votre véhicule et à l’horaire, puis ce qui serait facturé en supplément. Consultez le barème officiel actuel plutôt qu’un ancien montant mémorisé."]},{"title":"Contacter votre assistance","paragraphs":["Vérifiez la prise en charge avec l’assistance de votre contrat automobile. Conservez la facture détaillée et les échanges concernant remorquage, destination et réparation. Une intervention urgente ne justifie pas de renoncer à comprendre les prestations facturées."]}],"checklist":["Dépanneur agréé.","Forfait et suppléments expliqués.","Assistance et justificatifs suivis."],"sources":[{"kind":"reference","label":"DGCCRF — Panne sur autoroute","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/vehicules-que-faire-en-cas-de-panne-sur-autoroute"}],"order":116,"subcategory":"","homeRank":0,"tagSlugs":["budget","automobile","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
