INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/garage-ordre-reparation','{"kind":"guides","slug":"garage-ordre-reparation","title":"Garage : écrire ce que vous autorisez à réparer","description":"Cadrer le diagnostic, le coût et les travaux supplémentaires.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : ne laissez pas une demande de diagnostic devenir une autorisation illimitée.","sections":[{"title":"Décrire les symptômes","paragraphs":["Lors du dépôt, demandez un ordre de réparation précisant les problèmes signalés, l’état du véhicule et les opérations demandées. Gardez votre exemplaire signé, avec une estimation lorsqu’elle est possible."]},{"title":"Demander un devis","paragraphs":["Pour des travaux importants, faites détailler pièces, main-d’œuvre et délais. Clarifiez le coût du diagnostic et les conditions applicables si vous refusez la réparation proposée. Comparez plusieurs offres lorsque le véhicule et l’urgence le permettent."]},{"title":"Faire valider les changements","paragraphs":["Demandez à être recontacté avant toute opération supplémentaire. À la restitution, rapprochez la facture des travaux acceptés et faites expliquer les écarts. Conservez les documents pour pouvoir discuter d’une panne persistante ou d’une prestation contestée."]}],"checklist":["Demande écrite.","Devis compris.","Suppléments validés avant intervention."],"sources":[{"kind":"reference","label":"DGCCRF — Ordre de réparation","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques-et-les-faq/vehicule-automobile-lordre-de-reparation-decrit-la-nature"}],"order":117,"subcategory":"","homeRank":0,"tagSlugs":["budget","automobile","recours"]}','{"kind":"guides","slug":"garage-ordre-reparation","title":"Garage : écrire ce que vous autorisez à réparer","description":"Cadrer le diagnostic, le coût et les travaux supplémentaires.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : ne laissez pas une demande de diagnostic devenir une autorisation illimitée.","sections":[{"title":"Décrire les symptômes","paragraphs":["Lors du dépôt, demandez un ordre de réparation précisant les problèmes signalés, l’état du véhicule et les opérations demandées. Gardez votre exemplaire signé, avec une estimation lorsqu’elle est possible."]},{"title":"Demander un devis","paragraphs":["Pour des travaux importants, faites détailler pièces, main-d’œuvre et délais. Clarifiez le coût du diagnostic et les conditions applicables si vous refusez la réparation proposée. Comparez plusieurs offres lorsque le véhicule et l’urgence le permettent."]},{"title":"Faire valider les changements","paragraphs":["Demandez à être recontacté avant toute opération supplémentaire. À la restitution, rapprochez la facture des travaux acceptés et faites expliquer les écarts. Conservez les documents pour pouvoir discuter d’une panne persistante ou d’une prestation contestée."]}],"checklist":["Demande écrite.","Devis compris.","Suppléments validés avant intervention."],"sources":[{"kind":"reference","label":"DGCCRF — Ordre de réparation","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques-et-les-faq/vehicule-automobile-lordre-de-reparation-decrit-la-nature"}],"order":117,"subcategory":"","homeRank":0,"tagSlugs":["budget","automobile","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
