INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/vol-annule-retarde','{"kind":"guides","slug":"vol-annule-retarde","title":"Avion annulé ou retardé : garder les preuves du voyage","description":"Distinguer assistance, remboursement et indemnisation.","categoryId":"argent-consommation","themeId":"tourisme","reviewedAt":"2026-09-29","intro":"La règle d’or : demandez les options proposées avant d’acheter un nouveau trajet.","sections":[{"title":"Identifier le cadre applicable","paragraphs":["Les droits dépendent notamment du départ, de la destination et de la compagnie. Consultez la fiche officielle avec vos informations de vol. Ne supposez pas que tous les trajets mondiaux relèvent des mêmes règles."]},{"title":"Demander une prise en charge","paragraphs":["En cas de perturbation, faites préciser les possibilités de réacheminement ou de remboursement ainsi que l’assistance applicable. Gardez les messages de la compagnie et les justificatifs des dépenses nécessaires engagées faute de prise en charge."]},{"title":"Faire une réclamation distincte","paragraphs":["Une indemnisation éventuelle répond à d’autres conditions, dont les circonstances et le retard à l’arrivée. Conservez billet, carte d’embarquement, horaires et réponse du transporteur. Un remboursement du billet et une indemnité ne désignent pas la même chose."]}],"checklist":["Vol et transporteur identifiés.","Options demandées.","Preuves et reçus conservés."],"sources":[{"kind":"reference","label":"DGCCRF — Droits des passagers aériens","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/voyager-en-avion-quels-droits-pour-les-passagers"}],"order":118,"subcategory":"","homeRank":0,"tagSlugs":["tourisme","budget","recours"]}','{"kind":"guides","slug":"vol-annule-retarde","title":"Avion annulé ou retardé : garder les preuves du voyage","description":"Distinguer assistance, remboursement et indemnisation.","categoryId":"argent-consommation","themeId":"tourisme","reviewedAt":"2026-09-29","intro":"La règle d’or : demandez les options proposées avant d’acheter un nouveau trajet.","sections":[{"title":"Identifier le cadre applicable","paragraphs":["Les droits dépendent notamment du départ, de la destination et de la compagnie. Consultez la fiche officielle avec vos informations de vol. Ne supposez pas que tous les trajets mondiaux relèvent des mêmes règles."]},{"title":"Demander une prise en charge","paragraphs":["En cas de perturbation, faites préciser les possibilités de réacheminement ou de remboursement ainsi que l’assistance applicable. Gardez les messages de la compagnie et les justificatifs des dépenses nécessaires engagées faute de prise en charge."]},{"title":"Faire une réclamation distincte","paragraphs":["Une indemnisation éventuelle répond à d’autres conditions, dont les circonstances et le retard à l’arrivée. Conservez billet, carte d’embarquement, horaires et réponse du transporteur. Un remboursement du billet et une indemnité ne désignent pas la même chose."]}],"checklist":["Vol et transporteur identifiés.","Options demandées.","Preuves et reçus conservés."],"sources":[{"kind":"reference","label":"DGCCRF — Droits des passagers aériens","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/voyager-en-avion-quels-droits-pour-les-passagers"}],"order":118,"subcategory":"","homeRank":0,"tagSlugs":["tourisme","budget","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/guides/vol-annule-retarde','guides/vol-annule-retarde',1,'{"kind":"guides","slug":"vol-annule-retarde","title":"Avion annulé ou retardé : garder les preuves du voyage","description":"Distinguer assistance, remboursement et indemnisation.","categoryId":"argent-consommation","themeId":"tourisme","reviewedAt":"2026-09-29","intro":"La règle d’or : demandez les options proposées avant d’acheter un nouveau trajet.","sections":[{"title":"Identifier le cadre applicable","paragraphs":["Les droits dépendent notamment du départ, de la destination et de la compagnie. Consultez la fiche officielle avec vos informations de vol. Ne supposez pas que tous les trajets mondiaux relèvent des mêmes règles."]},{"title":"Demander une prise en charge","paragraphs":["En cas de perturbation, faites préciser les possibilités de réacheminement ou de remboursement ainsi que l’assistance applicable. Gardez les messages de la compagnie et les justificatifs des dépenses nécessaires engagées faute de prise en charge."]},{"title":"Faire une réclamation distincte","paragraphs":["Une indemnisation éventuelle répond à d’autres conditions, dont les circonstances et le retard à l’arrivée. Conservez billet, carte d’embarquement, horaires et réponse du transporteur. Un remboursement du billet et une indemnité ne désignent pas la même chose."]}],"checklist":["Vol et transporteur identifiés.","Options demandées.","Preuves et reçus conservés."],"sources":[{"kind":"reference","label":"DGCCRF — Droits des passagers aériens","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/voyager-en-avion-quels-droits-pour-les-passagers"}],"order":118,"subcategory":"","homeRank":0,"tagSlugs":["tourisme","budget","recours"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/train-retard-reclamation','{"kind":"guides","slug":"train-retard-reclamation","title":"Train en retard : conserver le billet et l’heure d’arrivée","description":"Vérifier les droits applicables à votre trajet ferroviaire.","categoryId":"argent-consommation","themeId":"tourisme","reviewedAt":"2026-09-29","intro":"La règle d’or : distinguez la garantie commerciale du transporteur des droits réglementaires.","sections":[{"title":"Identifier le trajet","paragraphs":["TGV, Intercités, TER et parcours internationaux ne suivent pas tous les mêmes modalités. Retrouvez la réservation, les correspondances et les conditions du transporteur pour vérifier ce qui s’applique."]},{"title":"Demander les solutions","paragraphs":["Lors d’une annulation ou d’un retard important, renseignez-vous sur la poursuite du trajet, le réacheminement, le remboursement et l’assistance. Gardez une trace du choix proposé et des informations reçues."]},{"title":"Déposer une demande documentée","paragraphs":["Conservez l’heure d’arrivée réelle, les justificatifs et la référence du billet. Certaines garanties commerciales commencent plus tôt que les seuils réglementaires. Vérifiez aussi les exceptions : toute perturbation ne donne pas automatiquement droit au même dédommagement."]}],"checklist":["Type de train vérifié.","Solution retenue documentée.","Réclamation avec justificatifs."],"sources":[{"kind":"reference","label":"DGCCRF — Voyager en train","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/voyager-en-train-les-regles-connaitre"}],"order":119,"subcategory":"","homeRank":0,"tagSlugs":["tourisme","recours"]}','{"kind":"guides","slug":"train-retard-reclamation","title":"Train en retard : conserver le billet et l’heure d’arrivée","description":"Vérifier les droits applicables à votre trajet ferroviaire.","categoryId":"argent-consommation","themeId":"tourisme","reviewedAt":"2026-09-29","intro":"La règle d’or : distinguez la garantie commerciale du transporteur des droits réglementaires.","sections":[{"title":"Identifier le trajet","paragraphs":["TGV, Intercités, TER et parcours internationaux ne suivent pas tous les mêmes modalités. Retrouvez la réservation, les correspondances et les conditions du transporteur pour vérifier ce qui s’applique."]},{"title":"Demander les solutions","paragraphs":["Lors d’une annulation ou d’un retard important, renseignez-vous sur la poursuite du trajet, le réacheminement, le remboursement et l’assistance. Gardez une trace du choix proposé et des informations reçues."]},{"title":"Déposer une demande documentée","paragraphs":["Conservez l’heure d’arrivée réelle, les justificatifs et la référence du billet. Certaines garanties commerciales commencent plus tôt que les seuils réglementaires. Vérifiez aussi les exceptions : toute perturbation ne donne pas automatiquement droit au même dédommagement."]}],"checklist":["Type de train vérifié.","Solution retenue documentée.","Réclamation avec justificatifs."],"sources":[{"kind":"reference","label":"DGCCRF — Voyager en train","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/voyager-en-train-les-regles-connaitre"}],"order":119,"subcategory":"","homeRank":0,"tagSlugs":["tourisme","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
