INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/voyage-forfait-verifications','{"kind":"guides","slug":"voyage-forfait-verifications","title":"Voyage organisé : lire ce que le forfait inclut","description":"Comparer prestations, frais et conditions d’annulation.","categoryId":"argent-consommation","themeId":"tourisme","reviewedAt":"2026-09-29","intro":"La règle d’or : faites préciser les éléments essentiels avant de réserver.","sections":[{"title":"Identifier le professionnel","paragraphs":["Vérifiez l’organisateur, le vendeur et l’immatriculation applicable au registre Atout France. Gardez leurs coordonnées. Assurez-vous de comprendre si l’offre constitue bien un forfait touristique."]},{"title":"Décomposer la promesse","paragraphs":["Relisez transport, nuitées, repas, excursions, taille du groupe et accessibilité. Examinez le prix total et les frais annoncés. Une photographie séduisante ne remplace pas les caractéristiques inscrites au contrat."]},{"title":"Préparer les imprévus","paragraphs":["Vérifiez conditions d’annulation, nombre minimal de participants, formalités de voyage et assurances proposées. Conservez les informations précontractuelles et le contrat. Signalez rapidement sur place une prestation non conforme afin de laisser au professionnel la possibilité d’y remédier."]}],"checklist":["Professionnel identifié.","Prestations détaillées.","Annulation et formalités vérifiées."],"sources":[{"kind":"reference","label":"DGCCRF — Voyages et séjours à forfait","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/voyages-et-sejours-forfait-les-points-verifier"}],"order":120,"subcategory":"","homeRank":0,"tagSlugs":["tourisme","budget"]}','{"kind":"guides","slug":"voyage-forfait-verifications","title":"Voyage organisé : lire ce que le forfait inclut","description":"Comparer prestations, frais et conditions d’annulation.","categoryId":"argent-consommation","themeId":"tourisme","reviewedAt":"2026-09-29","intro":"La règle d’or : faites préciser les éléments essentiels avant de réserver.","sections":[{"title":"Identifier le professionnel","paragraphs":["Vérifiez l’organisateur, le vendeur et l’immatriculation applicable au registre Atout France. Gardez leurs coordonnées. Assurez-vous de comprendre si l’offre constitue bien un forfait touristique."]},{"title":"Décomposer la promesse","paragraphs":["Relisez transport, nuitées, repas, excursions, taille du groupe et accessibilité. Examinez le prix total et les frais annoncés. Une photographie séduisante ne remplace pas les caractéristiques inscrites au contrat."]},{"title":"Préparer les imprévus","paragraphs":["Vérifiez conditions d’annulation, nombre minimal de participants, formalités de voyage et assurances proposées. Conservez les informations précontractuelles et le contrat. Signalez rapidement sur place une prestation non conforme afin de laisser au professionnel la possibilité d’y remédier."]}],"checklist":["Professionnel identifié.","Prestations détaillées.","Annulation et formalités vérifiées."],"sources":[{"kind":"reference","label":"DGCCRF — Voyages et séjours à forfait","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/voyages-et-sejours-forfait-les-points-verifier"}],"order":120,"subcategory":"","homeRank":0,"tagSlugs":["tourisme","budget"]}',1,'2026-10-01T06:41:56.605Z','migration');
