INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/taxi-vtc-prix-course','{"kind":"guides","slug":"taxi-vtc-prix-course","title":"Taxi ou VTC : comprendre le prix avant de monter","description":"Identifier le service réservé et obtenir une note de la course.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : vérifiez le mode de calcul au lieu de supposer un tarif fixe.","sections":[{"title":"Identifier la prestation","paragraphs":["Taxi et VTC ne fonctionnent pas de la même façon. Pour un VTC réservé, comparez les informations du véhicule et du chauffeur à la réservation. Gardez la confirmation de trajet."]},{"title":"Comprendre la tarification","paragraphs":["Le taxi utilise une tarification réglementée, avec des forfaits dans certains cas. Le VTC fixe librement ses prix : ils peuvent être annoncés à la réservation ou calculés selon la durée et la distance. Vérifiez les conditions affichées."]},{"title":"Demander le justificatif","paragraphs":["Une note doit être remise à partir de 25 €, et en dessous sur demande. Conservez-la si vous contestez une somme. Les taxis doivent accepter la carte bancaire quel que soit le montant de la course."]}],"checklist":["Service identifié.","Calcul du prix compris.","Note conservée."],"sources":[{"kind":"reference","label":"DGCCRF — Taxis et VTC","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/taxis-vtc-motos-pro-ce-quil-faut-savoir"}],"order":121,"subcategory":"","homeRank":0,"tagSlugs":["budget","automobile","recours"]}','{"kind":"guides","slug":"taxi-vtc-prix-course","title":"Taxi ou VTC : comprendre le prix avant de monter","description":"Identifier le service réservé et obtenir une note de la course.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : vérifiez le mode de calcul au lieu de supposer un tarif fixe.","sections":[{"title":"Identifier la prestation","paragraphs":["Taxi et VTC ne fonctionnent pas de la même façon. Pour un VTC réservé, comparez les informations du véhicule et du chauffeur à la réservation. Gardez la confirmation de trajet."]},{"title":"Comprendre la tarification","paragraphs":["Le taxi utilise une tarification réglementée, avec des forfaits dans certains cas. Le VTC fixe librement ses prix : ils peuvent être annoncés à la réservation ou calculés selon la durée et la distance. Vérifiez les conditions affichées."]},{"title":"Demander le justificatif","paragraphs":["Une note doit être remise à partir de 25 €, et en dessous sur demande. Conservez-la si vous contestez une somme. Les taxis doivent accepter la carte bancaire quel que soit le montant de la course."]}],"checklist":["Service identifié.","Calcul du prix compris.","Note conservée."],"sources":[{"kind":"reference","label":"DGCCRF — Taxis et VTC","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/taxis-vtc-motos-pro-ce-quil-faut-savoir"}],"order":121,"subcategory":"","homeRank":0,"tagSlugs":["budget","automobile","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
