INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/trottinette-electrique-achat','{"kind":"guides","slug":"trottinette-electrique-achat","title":"Trottinette électrique : vérifier l’usage autorisé avant l’achat","description":"Choisir un engin adapté à la circulation prévue.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : la vitesse promise par une publicité ne prouve pas que l’engin peut circuler sur la voie publique.","sections":[{"title":"Contrôler les caractéristiques","paragraphs":["Vérifiez la vitesse maximale par construction, l’identification du fabricant et la documentation. Méfiez-vous des annonces vantant le débridage : une possibilité technique ne constitue pas une autorisation d’usage."]},{"title":"Préparer le trajet","paragraphs":["Consultez les règles de circulation et les éventuelles dispositions locales. L’usage se fait seul sur l’engin ; les voies autorisées dépendent du lieu. Vérifiez également les équipements et l’assurance nécessaires avant le premier trajet."]},{"title":"Suivre les consignes","paragraphs":["Lisez la notice pour la charge, l’entretien et le stockage. N’utilisez pas un chargeur choisi au hasard. Conservez référence, facture et coordonnées du vendeur pour un éventuel rappel ou une demande de service après-vente."]}],"checklist":["Conformité à l’usage vérifiée.","Règles et assurance contrôlées.","Notice et facture conservées."],"sources":[{"kind":"reference","label":"DGCCRF — Trottinettes électriques","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/trottinettes-electriques-les-conseils-pour-un-achat-et-une-utilisation-en-toute-securite"}],"order":122,"subcategory":"","homeRank":0,"tagSlugs":["automobile","achats"]}','{"kind":"guides","slug":"trottinette-electrique-achat","title":"Trottinette électrique : vérifier l’usage autorisé avant l’achat","description":"Choisir un engin adapté à la circulation prévue.","categoryId":"argent-consommation","themeId":"automobile","reviewedAt":"2026-09-29","intro":"La règle d’or : la vitesse promise par une publicité ne prouve pas que l’engin peut circuler sur la voie publique.","sections":[{"title":"Contrôler les caractéristiques","paragraphs":["Vérifiez la vitesse maximale par construction, l’identification du fabricant et la documentation. Méfiez-vous des annonces vantant le débridage : une possibilité technique ne constitue pas une autorisation d’usage."]},{"title":"Préparer le trajet","paragraphs":["Consultez les règles de circulation et les éventuelles dispositions locales. L’usage se fait seul sur l’engin ; les voies autorisées dépendent du lieu. Vérifiez également les équipements et l’assurance nécessaires avant le premier trajet."]},{"title":"Suivre les consignes","paragraphs":["Lisez la notice pour la charge, l’entretien et le stockage. N’utilisez pas un chargeur choisi au hasard. Conservez référence, facture et coordonnées du vendeur pour un éventuel rappel ou une demande de service après-vente."]}],"checklist":["Conformité à l’usage vérifiée.","Règles et assurance contrôlées.","Notice et facture conservées."],"sources":[{"kind":"reference","label":"DGCCRF — Trottinettes électriques","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/trottinettes-electriques-les-conseils-pour-un-achat-et-une-utilisation-en-toute-securite"}],"order":122,"subcategory":"","homeRank":0,"tagSlugs":["automobile","achats"]}',1,'2026-10-01T06:41:56.605Z','migration');
