INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/poste-ecran-reglages','{"kind":"guides","slug":"poste-ecran-reglages","title":"Travail sur écran : régler le poste autour de vous","description":"Adapter l’écran, le siège et les accessoires à votre activité.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : le matériel doit s’adapter à l’utilisateur, pas l’inverse.","sections":[{"title":"Partir de l’usage réel","paragraphs":["Placez l’écran le plus consulté face à vous et gardez les équipements utiles accessibles. Si vous utilisez durablement un portable, étudiez un écran externe ou un support avec clavier et souris séparés."]},{"title":"Ajuster les appuis","paragraphs":["Réglez le siège pour un soutien adapté et des pieds en appui ; un repose-pieds peut être nécessaire. Gardez assez d’espace pour changer de position. Demandez un accompagnement si les réglages ne conviennent pas."]},{"title":"Réexaminer après usage","paragraphs":["Testez le poste pendant vos tâches habituelles, pas uniquement assis quelques secondes. Signalez les difficultés à votre responsable ou au service de prévention et de santé au travail. Un équipement neuf ne corrige pas à lui seul une organisation inadaptée."]}],"checklist":["Écran principal bien placé.","Appuis ajustés.","Confort vérifié en situation."],"sources":[{"kind":"reference","label":"INRS — Prévention du travail sur écran","url":"https://www.inrs.fr/risques/travail-ecran/prevention-risques"}],"order":123,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}','{"kind":"guides","slug":"poste-ecran-reglages","title":"Travail sur écran : régler le poste autour de vous","description":"Adapter l’écran, le siège et les accessoires à votre activité.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : le matériel doit s’adapter à l’utilisateur, pas l’inverse.","sections":[{"title":"Partir de l’usage réel","paragraphs":["Placez l’écran le plus consulté face à vous et gardez les équipements utiles accessibles. Si vous utilisez durablement un portable, étudiez un écran externe ou un support avec clavier et souris séparés."]},{"title":"Ajuster les appuis","paragraphs":["Réglez le siège pour un soutien adapté et des pieds en appui ; un repose-pieds peut être nécessaire. Gardez assez d’espace pour changer de position. Demandez un accompagnement si les réglages ne conviennent pas."]},{"title":"Réexaminer après usage","paragraphs":["Testez le poste pendant vos tâches habituelles, pas uniquement assis quelques secondes. Signalez les difficultés à votre responsable ou au service de prévention et de santé au travail. Un équipement neuf ne corrige pas à lui seul une organisation inadaptée."]}],"checklist":["Écran principal bien placé.","Appuis ajustés.","Confort vérifié en situation."],"sources":[{"kind":"reference","label":"INRS — Prévention du travail sur écran","url":"https://www.inrs.fr/risques/travail-ecran/prevention-risques"}],"order":123,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
