INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/bruit-travail-prevenir','{"kind":"guides","slug":"bruit-travail-prevenir","title":"Bruit au travail : agir d’abord sur la source","description":"Faire remonter les situations gênantes et examiner les protections collectives.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : ne réduisez pas la prévention au port d’un casque.","sections":[{"title":"Décrire les situations","paragraphs":["Repérez les machines, les tâches et les moments les plus bruyants. Notez aussi les difficultés à communiquer. Faites remonter ces observations pour qu’une évaluation adaptée soit organisée."]},{"title":"Chercher des solutions collectives","paragraphs":["La prévention peut agir sur les équipements, leur implantation, l’acoustique des locaux ou l’organisation. Réduire le bruit à la source et sa propagation doit être étudié en priorité."]},{"title":"Compléter et suivre","paragraphs":["Lorsque des protections individuelles sont nécessaires, leur choix et leur utilisation doivent être adaptés. Demandez les consignes et la formation utiles. Après une modification, vérifiez avec les personnes concernées si l’exposition et la gêne diminuent réellement."]}],"checklist":["Situations signalées.","Réduction collective étudiée.","Mesures suivies."],"sources":[{"kind":"reference","label":"INRS — Prévention du bruit","url":"https://www.inrs.fr/risques/bruit/demarche-prevention"}],"order":124,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}','{"kind":"guides","slug":"bruit-travail-prevenir","title":"Bruit au travail : agir d’abord sur la source","description":"Faire remonter les situations gênantes et examiner les protections collectives.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : ne réduisez pas la prévention au port d’un casque.","sections":[{"title":"Décrire les situations","paragraphs":["Repérez les machines, les tâches et les moments les plus bruyants. Notez aussi les difficultés à communiquer. Faites remonter ces observations pour qu’une évaluation adaptée soit organisée."]},{"title":"Chercher des solutions collectives","paragraphs":["La prévention peut agir sur les équipements, leur implantation, l’acoustique des locaux ou l’organisation. Réduire le bruit à la source et sa propagation doit être étudié en priorité."]},{"title":"Compléter et suivre","paragraphs":["Lorsque des protections individuelles sont nécessaires, leur choix et leur utilisation doivent être adaptés. Demandez les consignes et la formation utiles. Après une modification, vérifiez avec les personnes concernées si l’exposition et la gêne diminuent réellement."]}],"checklist":["Situations signalées.","Réduction collective étudiée.","Mesures suivies."],"sources":[{"kind":"reference","label":"INRS — Prévention du bruit","url":"https://www.inrs.fr/risques/bruit/demarche-prevention"}],"order":124,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
