INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/stress-charge-travail','{"kind":"guides","slug":"stress-charge-travail","title":"Surcharge au travail : rendre les difficultés discutables","description":"Décrire les obstacles et rechercher des changements d’organisation.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : une difficulté durable doit conduire à revoir les moyens et les priorités.","sections":[{"title":"Rassembler des faits","paragraphs":["Notez les tâches, délais, interruptions et ressources manquantes. Décrivez ce qui empêche de bien travailler plutôt que de conclure que vous devriez simplement mieux résister à la pression."]},{"title":"Demander un arbitrage","paragraphs":["Discutez des priorités, du volume et des moyens avec les interlocuteurs appropriés. L’INRS privilégie une prévention collective centrée sur le travail. Des exercices individuels ne remplacent pas la correction des causes organisationnelles."]},{"title":"Suivre les engagements","paragraphs":["Formalisez les actions retenues et une date de bilan. Si la situation affecte votre santé, sollicitez le service de prévention et de santé au travail ou un professionnel de santé. Un questionnaire interne n’est utile que s’il débouche sur des suites."]}],"checklist":["Difficultés décrites.","Priorités discutées.","Actions et bilan prévus."],"sources":[{"kind":"reference","label":"INRS — Prévention du stress","url":"https://www.inrs.fr/risques/stress/prevention"}],"order":125,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}','{"kind":"guides","slug":"stress-charge-travail","title":"Surcharge au travail : rendre les difficultés discutables","description":"Décrire les obstacles et rechercher des changements d’organisation.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : une difficulté durable doit conduire à revoir les moyens et les priorités.","sections":[{"title":"Rassembler des faits","paragraphs":["Notez les tâches, délais, interruptions et ressources manquantes. Décrivez ce qui empêche de bien travailler plutôt que de conclure que vous devriez simplement mieux résister à la pression."]},{"title":"Demander un arbitrage","paragraphs":["Discutez des priorités, du volume et des moyens avec les interlocuteurs appropriés. L’INRS privilégie une prévention collective centrée sur le travail. Des exercices individuels ne remplacent pas la correction des causes organisationnelles."]},{"title":"Suivre les engagements","paragraphs":["Formalisez les actions retenues et une date de bilan. Si la situation affecte votre santé, sollicitez le service de prévention et de santé au travail ou un professionnel de santé. Un questionnaire interne n’est utile que s’il débouche sur des suites."]}],"checklist":["Difficultés décrites.","Priorités discutées.","Actions et bilan prévus."],"sources":[{"kind":"reference","label":"INRS — Prévention du stress","url":"https://www.inrs.fr/risques/stress/prevention"}],"order":125,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
