INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/travail-isole-organisation','{"kind":"guides","slug":"travail-isole-organisation","title":"Travail isolé : préparer l’alerte avant l’intervention","description":"Organiser la prévention et les secours lorsqu’une personne travaille seule.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : un téléphone ne suffit pas à organiser les secours.","sections":[{"title":"Identifier l’isolement","paragraphs":["Repérez les moments où une personne ne peut pas être vue ou secourue rapidement. Cela peut être ponctuel, de nuit ou lors d’une intervention extérieure. Intégrez la tâche et l’environnement à l’évaluation."]},{"title":"Réduire la situation à risque","paragraphs":["L’employeur doit examiner l’organisation, les moyens de prévention et la formation. Cherchez d’abord comment éviter ou réduire l’isolement. Certaines tâches demandent des dispositions particulières : ne les improvisez pas."]},{"title":"Vérifier la chaîne de secours","paragraphs":["Précisez comment l’alerte est donnée, qui la reçoit et comment accéder au lieu. Testez les moyens prévus et expliquez les consignes. Un dispositif technique doit s’inscrire dans une organisation capable d’intervenir effectivement."]}],"checklist":["Situations recensées.","Organisation adaptée.","Alerte et accès testés."],"sources":[{"kind":"reference","label":"INRS — Travail isolé","url":"https://www.inrs.fr/risques/travail-isole/reglementation"}],"order":126,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}','{"kind":"guides","slug":"travail-isole-organisation","title":"Travail isolé : préparer l’alerte avant l’intervention","description":"Organiser la prévention et les secours lorsqu’une personne travaille seule.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : un téléphone ne suffit pas à organiser les secours.","sections":[{"title":"Identifier l’isolement","paragraphs":["Repérez les moments où une personne ne peut pas être vue ou secourue rapidement. Cela peut être ponctuel, de nuit ou lors d’une intervention extérieure. Intégrez la tâche et l’environnement à l’évaluation."]},{"title":"Réduire la situation à risque","paragraphs":["L’employeur doit examiner l’organisation, les moyens de prévention et la formation. Cherchez d’abord comment éviter ou réduire l’isolement. Certaines tâches demandent des dispositions particulières : ne les improvisez pas."]},{"title":"Vérifier la chaîne de secours","paragraphs":["Précisez comment l’alerte est donnée, qui la reçoit et comment accéder au lieu. Testez les moyens prévus et expliquez les consignes. Un dispositif technique doit s’inscrire dans une organisation capable d’intervenir effectivement."]}],"checklist":["Situations recensées.","Organisation adaptée.","Alerte et accès testés."],"sources":[{"kind":"reference","label":"INRS — Travail isolé","url":"https://www.inrs.fr/risques/travail-isole/reglementation"}],"order":126,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
