INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/chutes-plain-pied','{"kind":"guides","slug":"chutes-plain-pied","title":"Glissades au travail : corriger l’environnement","description":"Repérer les obstacles et les conditions qui favorisent une chute.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : une chute n’est pas forcément une simple maladresse.","sections":[{"title":"Observer le parcours","paragraphs":["Repérez sols glissants, câbles, objets au passage, éclairage insuffisant et petites ruptures de niveau. Les déplacements ordinaires méritent autant d’attention que les tâches considérées comme dangereuses."]},{"title":"Examiner l’organisation","paragraphs":["La précipitation, une charge qui masque la vue ou une interruption peuvent se combiner avec l’état des lieux. Signalez la situation complète plutôt que le seul obstacle. Associez les personnes qui utilisent le passage."]},{"title":"Corriger durablement","paragraphs":["Faites traiter rangement, circulation, nettoyage et éclairage avec les responsables concernés. Signalez provisoirement le danger selon les consignes du site. Après un incident évité de justesse, partagez le constat pour éviter qu’il ne se reproduise."]}],"checklist":["Parcours inspecté.","Causes combinées examinées.","Correction suivie."],"sources":[{"kind":"reference","label":"INRS — Chutes de plain-pied","url":"https://www.inrs.fr/risques/chutes-de-plain-pied/definition-et-caracteristiques.html"}],"order":127,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}','{"kind":"guides","slug":"chutes-plain-pied","title":"Glissades au travail : corriger l’environnement","description":"Repérer les obstacles et les conditions qui favorisent une chute.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : une chute n’est pas forcément une simple maladresse.","sections":[{"title":"Observer le parcours","paragraphs":["Repérez sols glissants, câbles, objets au passage, éclairage insuffisant et petites ruptures de niveau. Les déplacements ordinaires méritent autant d’attention que les tâches considérées comme dangereuses."]},{"title":"Examiner l’organisation","paragraphs":["La précipitation, une charge qui masque la vue ou une interruption peuvent se combiner avec l’état des lieux. Signalez la situation complète plutôt que le seul obstacle. Associez les personnes qui utilisent le passage."]},{"title":"Corriger durablement","paragraphs":["Faites traiter rangement, circulation, nettoyage et éclairage avec les responsables concernés. Signalez provisoirement le danger selon les consignes du site. Après un incident évité de justesse, partagez le constat pour éviter qu’il ne se reproduise."]}],"checklist":["Parcours inspecté.","Causes combinées examinées.","Correction suivie."],"sources":[{"kind":"reference","label":"INRS — Chutes de plain-pied","url":"https://www.inrs.fr/risques/chutes-de-plain-pied/definition-et-caracteristiques.html"}],"order":127,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/guides/chutes-plain-pied','guides/chutes-plain-pied',1,'{"kind":"guides","slug":"chutes-plain-pied","title":"Glissades au travail : corriger l’environnement","description":"Repérer les obstacles et les conditions qui favorisent une chute.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : une chute n’est pas forcément une simple maladresse.","sections":[{"title":"Observer le parcours","paragraphs":["Repérez sols glissants, câbles, objets au passage, éclairage insuffisant et petites ruptures de niveau. Les déplacements ordinaires méritent autant d’attention que les tâches considérées comme dangereuses."]},{"title":"Examiner l’organisation","paragraphs":["La précipitation, une charge qui masque la vue ou une interruption peuvent se combiner avec l’état des lieux. Signalez la situation complète plutôt que le seul obstacle. Associez les personnes qui utilisent le passage."]},{"title":"Corriger durablement","paragraphs":["Faites traiter rangement, circulation, nettoyage et éclairage avec les responsables concernés. Signalez provisoirement le danger selon les consignes du site. Après un incident évité de justesse, partagez le constat pour éviter qu’il ne se reproduise."]}],"checklist":["Parcours inspecté.","Causes combinées examinées.","Correction suivie."],"sources":[{"kind":"reference","label":"INRS — Chutes de plain-pied","url":"https://www.inrs.fr/risques/chutes-de-plain-pied/definition-et-caracteristiques.html"}],"order":127,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/manutention-reduire-effort','{"kind":"guides","slug":"manutention-reduire-effort","title":"Port de charges : réduire l’effort avant de corriger le geste","description":"Préparer les moyens et l’organisation des manutentions.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : la meilleure prévention commence par limiter ce qu’il faut porter.","sections":[{"title":"Examiner la tâche","paragraphs":["Regardez poids, encombrement, fréquence, distance et espace disponible. Le risque ne dépend pas uniquement du nombre de kilogrammes. Faites analyser la situation avant de retenir une solution standard."]},{"title":"Réduire les contraintes","paragraphs":["Étudiez des aides adaptées, un conditionnement plus léger ou un trajet plus court. Aménagez les hauteurs et les accès pour limiter les postures contraignantes. La mécanisation demande elle aussi un équipement et un usage appropriés."]},{"title":"Organiser et former","paragraphs":["Prévoyez le temps, les pauses et la formation nécessaires. Ne faites pas reposer toute la prévention sur une consigne de posture. Signalez les difficultés et réévaluez l’organisation avec les acteurs de prévention de l’entreprise."]}],"checklist":["Tâche évaluée globalement.","Efforts réduits.","Moyens et formation prévus."],"sources":[{"kind":"reference","label":"INRS — Prévention des contraintes physiques","url":"https://www.inrs.fr/risques/lombalgies/prevention"}],"order":128,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}','{"kind":"guides","slug":"manutention-reduire-effort","title":"Port de charges : réduire l’effort avant de corriger le geste","description":"Préparer les moyens et l’organisation des manutentions.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : la meilleure prévention commence par limiter ce qu’il faut porter.","sections":[{"title":"Examiner la tâche","paragraphs":["Regardez poids, encombrement, fréquence, distance et espace disponible. Le risque ne dépend pas uniquement du nombre de kilogrammes. Faites analyser la situation avant de retenir une solution standard."]},{"title":"Réduire les contraintes","paragraphs":["Étudiez des aides adaptées, un conditionnement plus léger ou un trajet plus court. Aménagez les hauteurs et les accès pour limiter les postures contraignantes. La mécanisation demande elle aussi un équipement et un usage appropriés."]},{"title":"Organiser et former","paragraphs":["Prévoyez le temps, les pauses et la formation nécessaires. Ne faites pas reposer toute la prévention sur une consigne de posture. Signalez les difficultés et réévaluez l’organisation avec les acteurs de prévention de l’entreprise."]}],"checklist":["Tâche évaluée globalement.","Efforts réduits.","Moyens et formation prévus."],"sources":[{"kind":"reference","label":"INRS — Prévention des contraintes physiques","url":"https://www.inrs.fr/risques/lombalgies/prevention"}],"order":128,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
