INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/accueil-nouveau-collegue','{"kind":"guides","slug":"accueil-nouveau-collegue","title":"Nouveau collègue : organiser un accueil utile dès le premier jour","description":"Préparer les repères, les risques et l’accompagnement au poste.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : l’expérience passée ne dispense pas d’expliquer les risques du nouveau poste.","sections":[{"title":"Préparer l’arrivée","paragraphs":["Désignez une personne disponible pour accompagner le nouvel arrivant. Prévoyez les accès, le matériel, les consignes et un temps de découverte. L’accueil concerne aussi les intérimaires, stagiaires et apprentis."]},{"title":"Montrer le travail réel","paragraphs":["Présentez les situations habituelles et celles qui demandent d’arrêter ou d’appeler un responsable. Faites identifier les dangers du poste avec la personne, plutôt que de lui remettre seulement une pile de documents."]},{"title":"Vérifier la compréhension","paragraphs":["Invitez-la à reformuler et à poser des questions. Programmez un point après les premières prises de poste pour corriger les difficultés. Les outils TutoPrév’ de l’INRS peuvent aider le tuteur à structurer cette démarche."]}],"checklist":["Accompagnateur identifié.","Risques expliqués au poste.","Point de suivi prévu."],"sources":[{"kind":"reference","label":"INRS — Accueil des nouveaux embauchés","url":"https://www.inrs.fr/demarche/nouveaux-embauches/ce-qu-il-faut-retenir.html"}],"order":129,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}','{"kind":"guides","slug":"accueil-nouveau-collegue","title":"Nouveau collègue : organiser un accueil utile dès le premier jour","description":"Préparer les repères, les risques et l’accompagnement au poste.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : l’expérience passée ne dispense pas d’expliquer les risques du nouveau poste.","sections":[{"title":"Préparer l’arrivée","paragraphs":["Désignez une personne disponible pour accompagner le nouvel arrivant. Prévoyez les accès, le matériel, les consignes et un temps de découverte. L’accueil concerne aussi les intérimaires, stagiaires et apprentis."]},{"title":"Montrer le travail réel","paragraphs":["Présentez les situations habituelles et celles qui demandent d’arrêter ou d’appeler un responsable. Faites identifier les dangers du poste avec la personne, plutôt que de lui remettre seulement une pile de documents."]},{"title":"Vérifier la compréhension","paragraphs":["Invitez-la à reformuler et à poser des questions. Programmez un point après les premières prises de poste pour corriger les difficultés. Les outils TutoPrév’ de l’INRS peuvent aider le tuteur à structurer cette démarche."]}],"checklist":["Accompagnateur identifié.","Risques expliqués au poste.","Point de suivi prévu."],"sources":[{"kind":"reference","label":"INRS — Accueil des nouveaux embauchés","url":"https://www.inrs.fr/demarche/nouveaux-embauches/ce-qu-il-faut-retenir.html"}],"order":129,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
