INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/evacuation-incendie-bureau','{"kind":"guides","slug":"evacuation-incendie-bureau","title":"Incendie au travail : connaître le parcours avant l’alarme","description":"Repérer les consignes et participer à une évacuation organisée.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : le jour de l’alerte ne doit pas être celui de la découverte des sorties.","sections":[{"title":"Lire les consignes du site","paragraphs":["Repérez les itinéraires, le point de rassemblement et les personnes chargées de l’évacuation. Les dispositions doivent aussi tenir compte des personnes ayant besoin d’une mise en sécurité adaptée."]},{"title":"Maintenir les passages disponibles","paragraphs":["Signalez les sorties encombrées ou une signalisation incompréhensible. Lors des exercices, suivez réellement le parcours prévu et faites remonter les obstacles rencontrés. La préparation concerne également les visiteurs."]},{"title":"Suivre l’organisation prévue","paragraphs":["À l’alarme, appliquez les consignes sans précipitation et rejoignez le lieu de recensement. Ne vous exposez pas aux fumées. L’alerte des secours et l’intervention nécessitent une organisation et une formation adaptées, pas une initiative improvisée."]}],"checklist":["Sorties et rassemblement repérés.","Passages dégagés.","Consignes et rôles connus."],"sources":[{"kind":"reference","label":"INRS — Évacuation et sécurité incendie","url":"https://www.inrs.fr/risques/incendie-lieu-travail/evacuation-intervention-consignes-securite.html"}],"order":130,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}','{"kind":"guides","slug":"evacuation-incendie-bureau","title":"Incendie au travail : connaître le parcours avant l’alarme","description":"Repérer les consignes et participer à une évacuation organisée.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : le jour de l’alerte ne doit pas être celui de la découverte des sorties.","sections":[{"title":"Lire les consignes du site","paragraphs":["Repérez les itinéraires, le point de rassemblement et les personnes chargées de l’évacuation. Les dispositions doivent aussi tenir compte des personnes ayant besoin d’une mise en sécurité adaptée."]},{"title":"Maintenir les passages disponibles","paragraphs":["Signalez les sorties encombrées ou une signalisation incompréhensible. Lors des exercices, suivez réellement le parcours prévu et faites remonter les obstacles rencontrés. La préparation concerne également les visiteurs."]},{"title":"Suivre l’organisation prévue","paragraphs":["À l’alarme, appliquez les consignes sans précipitation et rejoignez le lieu de recensement. Ne vous exposez pas aux fumées. L’alerte des secours et l’intervention nécessitent une organisation et une formation adaptées, pas une initiative improvisée."]}],"checklist":["Sorties et rassemblement repérés.","Passages dégagés.","Consignes et rôles connus."],"sources":[{"kind":"reference","label":"INRS — Évacuation et sécurité incendie","url":"https://www.inrs.fr/risques/incendie-lieu-travail/evacuation-intervention-consignes-securite.html"}],"order":130,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
