INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/deplacement-professionnel-route','{"kind":"guides","slug":"deplacement-professionnel-route","title":"Déplacement professionnel : prévoir le temps de rouler","description":"Organiser les missions sans transformer le trajet en course contre la montre.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : le temps de déplacement fait partie de l’organisation de la mission.","sections":[{"title":"Questionner le déplacement","paragraphs":["Vérifiez si un échange à distance ou un autre transport convient. Si la voiture est nécessaire, prévoyez un horaire réaliste, les aléas et les pauses. Ne construisez pas une tournée qui exige de compenser chaque retard au volant."]},{"title":"Préparer le véhicule","paragraphs":["Choisissez un véhicule adapté à la mission et faites vérifier son état. Assurez le rangement et l’arrimage des objets transportés. Remontez les défauts avant de partir plutôt que de les considérer comme une gêne habituelle."]},{"title":"Organiser les communications","paragraphs":["Convenez de moments d’appel à l’arrêt dans un lieu sûr. L’équipe doit savoir qu’une personne qui conduit n’est pas immédiatement joignable. Faites réexaminer les plannings qui rendent ces règles impossibles à respecter."]}],"checklist":["Trajet et alternatives étudiés.","Véhicule adapté.","Appels organisés hors conduite."],"sources":[{"kind":"reference","label":"INRS — Risques routiers professionnels","url":"https://www.inrs.fr/risques/routiers/ce-qu-il-faut-retenir.html"}],"order":131,"subcategory":"","homeRank":0,"tagSlugs":["automobile","travail","decisions"]}','{"kind":"guides","slug":"deplacement-professionnel-route","title":"Déplacement professionnel : prévoir le temps de rouler","description":"Organiser les missions sans transformer le trajet en course contre la montre.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : le temps de déplacement fait partie de l’organisation de la mission.","sections":[{"title":"Questionner le déplacement","paragraphs":["Vérifiez si un échange à distance ou un autre transport convient. Si la voiture est nécessaire, prévoyez un horaire réaliste, les aléas et les pauses. Ne construisez pas une tournée qui exige de compenser chaque retard au volant."]},{"title":"Préparer le véhicule","paragraphs":["Choisissez un véhicule adapté à la mission et faites vérifier son état. Assurez le rangement et l’arrimage des objets transportés. Remontez les défauts avant de partir plutôt que de les considérer comme une gêne habituelle."]},{"title":"Organiser les communications","paragraphs":["Convenez de moments d’appel à l’arrêt dans un lieu sûr. L’équipe doit savoir qu’une personne qui conduit n’est pas immédiatement joignable. Faites réexaminer les plannings qui rendent ces règles impossibles à respecter."]}],"checklist":["Trajet et alternatives étudiés.","Véhicule adapté.","Appels organisés hors conduite."],"sources":[{"kind":"reference","label":"INRS — Risques routiers professionnels","url":"https://www.inrs.fr/risques/routiers/ce-qu-il-faut-retenir.html"}],"order":131,"subcategory":"","homeRank":0,"tagSlugs":["automobile","travail","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
