INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/produits-chimiques-prevention','{"kind":"guides","slug":"produits-chimiques-prevention","title":"Produits chimiques au travail : identifier avant d’utiliser","description":"Faire évaluer les produits, les émissions et les protections.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : un produit courant peut présenter un risque dans vos conditions d’usage.","sections":[{"title":"Recenser les expositions","paragraphs":["Colles, peintures et produits d’entretien comptent, mais aussi poussières et fumées produites par l’activité. Signalez les usages réels et les situations inhabituelles aux responsables de prévention."]},{"title":"Chercher à supprimer le danger","paragraphs":["L’objectif prioritaire est de supprimer le produit dangereux ou de le remplacer par une solution moins nocive. Si cela reste impossible, des mesures collectives doivent limiter l’exposition, par exemple le captage à la source."]},{"title":"Appliquer des consignes adaptées","paragraphs":["Les équipements individuels complètent les autres mesures lorsqu’elles ne suffisent pas. Demandez les informations et la formation nécessaires, ainsi que la conduite à tenir en cas d’incident. N’inventez ni mélange ni méthode d’utilisation."]}],"checklist":["Produits et émissions identifiés.","Substitution étudiée.","Consignes et protections comprises."],"sources":[{"kind":"reference","label":"INRS — Risques chimiques","url":"https://www.inrs.fr/risques/chimiques/ce-qu-il-faut-retenir.html"}],"order":132,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}','{"kind":"guides","slug":"produits-chimiques-prevention","title":"Produits chimiques au travail : identifier avant d’utiliser","description":"Faire évaluer les produits, les émissions et les protections.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : un produit courant peut présenter un risque dans vos conditions d’usage.","sections":[{"title":"Recenser les expositions","paragraphs":["Colles, peintures et produits d’entretien comptent, mais aussi poussières et fumées produites par l’activité. Signalez les usages réels et les situations inhabituelles aux responsables de prévention."]},{"title":"Chercher à supprimer le danger","paragraphs":["L’objectif prioritaire est de supprimer le produit dangereux ou de le remplacer par une solution moins nocive. Si cela reste impossible, des mesures collectives doivent limiter l’exposition, par exemple le captage à la source."]},{"title":"Appliquer des consignes adaptées","paragraphs":["Les équipements individuels complètent les autres mesures lorsqu’elles ne suffisent pas. Demandez les informations et la formation nécessaires, ainsi que la conduite à tenir en cas d’incident. N’inventez ni mélange ni méthode d’utilisation."]}],"checklist":["Produits et émissions identifiés.","Substitution étudiée.","Consignes et protections comprises."],"sources":[{"kind":"reference","label":"INRS — Risques chimiques","url":"https://www.inrs.fr/risques/chimiques/ce-qu-il-faut-retenir.html"}],"order":132,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/guides/produits-chimiques-prevention','guides/produits-chimiques-prevention',1,'{"kind":"guides","slug":"produits-chimiques-prevention","title":"Produits chimiques au travail : identifier avant d’utiliser","description":"Faire évaluer les produits, les émissions et les protections.","categoryId":"management-travail","themeId":"travail","reviewedAt":"2026-09-29","intro":"La règle d’or : un produit courant peut présenter un risque dans vos conditions d’usage.","sections":[{"title":"Recenser les expositions","paragraphs":["Colles, peintures et produits d’entretien comptent, mais aussi poussières et fumées produites par l’activité. Signalez les usages réels et les situations inhabituelles aux responsables de prévention."]},{"title":"Chercher à supprimer le danger","paragraphs":["L’objectif prioritaire est de supprimer le produit dangereux ou de le remplacer par une solution moins nocive. Si cela reste impossible, des mesures collectives doivent limiter l’exposition, par exemple le captage à la source."]},{"title":"Appliquer des consignes adaptées","paragraphs":["Les équipements individuels complètent les autres mesures lorsqu’elles ne suffisent pas. Demandez les informations et la formation nécessaires, ainsi que la conduite à tenir en cas d’incident. N’inventez ni mélange ni méthode d’utilisation."]}],"checklist":["Produits et émissions identifiés.","Substitution étudiée.","Consignes et protections comprises."],"sources":[{"kind":"reference","label":"INRS — Risques chimiques","url":"https://www.inrs.fr/risques/chimiques/ce-qu-il-faut-retenir.html"}],"order":132,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/soldes-retour-garanties','{"kind":"guides","slug":"soldes-retour-garanties","title":"Article soldé : distinguer retour commercial et garantie","description":"Savoir quoi demander lorsqu’un achat soldé pose problème.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : une réduction de prix ne supprime pas les garanties légales.","sections":[{"title":"Identifier la raison du retour","paragraphs":["Un défaut et un simple changement d’avis ne relèvent pas de la même démarche. Décrivez précisément le problème avant de demander une solution au vendeur. Conservez le justificatif et l’annonce du produit."]},{"title":"Vérifier les engagements du magasin","paragraphs":["Pour un achat en magasin sans défaut, l’échange ou le remboursement dépend généralement de la politique commerciale annoncée. Regardez les conditions, délais et exceptions avant de payer ; gardez une photo de l’affichage utile."]},{"title":"Faire valoir les bons droits","paragraphs":["Un article soldé reste couvert par les garanties légales applicables. La mention « ni repris ni échangé » ne les écarte pas. Pour une vente à distance, vérifiez séparément le droit de rétractation et ses exceptions."]}],"checklist":["Motif du retour identifié.","Politique commerciale conservée.","Garantie distinguée du changement d’avis."],"sources":[{"kind":"reference","label":"DGCCRF — Soldes et droits des consommateurs","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/soldes-droit-des-consommateurs-et-obligations-des-commercants?post_id=noID"}],"order":133,"subcategory":"","homeRank":0,"tagSlugs":["promotions","achats","recours"]}','{"kind":"guides","slug":"soldes-retour-garanties","title":"Article soldé : distinguer retour commercial et garantie","description":"Savoir quoi demander lorsqu’un achat soldé pose problème.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : une réduction de prix ne supprime pas les garanties légales.","sections":[{"title":"Identifier la raison du retour","paragraphs":["Un défaut et un simple changement d’avis ne relèvent pas de la même démarche. Décrivez précisément le problème avant de demander une solution au vendeur. Conservez le justificatif et l’annonce du produit."]},{"title":"Vérifier les engagements du magasin","paragraphs":["Pour un achat en magasin sans défaut, l’échange ou le remboursement dépend généralement de la politique commerciale annoncée. Regardez les conditions, délais et exceptions avant de payer ; gardez une photo de l’affichage utile."]},{"title":"Faire valoir les bons droits","paragraphs":["Un article soldé reste couvert par les garanties légales applicables. La mention « ni repris ni échangé » ne les écarte pas. Pour une vente à distance, vérifiez séparément le droit de rétractation et ses exceptions."]}],"checklist":["Motif du retour identifié.","Politique commerciale conservée.","Garantie distinguée du changement d’avis."],"sources":[{"kind":"reference","label":"DGCCRF — Soldes et droits des consommateurs","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/soldes-droit-des-consommateurs-et-obligations-des-commercants?post_id=noID"}],"order":133,"subcategory":"","homeRank":0,"tagSlugs":["promotions","achats","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
