INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/acheter-reconditionne','{"kind":"guides","slug":"acheter-reconditionne","title":"Reconditionné : demander l’état réel du produit","description":"Comparer les tests, la batterie et les garanties avant l’achat.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : la fiche d’un appareil neuf ne décrit pas l’exemplaire reconditionné vendu.","sections":[{"title":"Examiner les caractéristiques","paragraphs":["Demandez l’état esthétique et les performances annoncées, notamment la capacité minimale de batterie pour un téléphone. Les appellations commerciales de qualité peuvent varier entre vendeurs : comparez leur définition concrète."]},{"title":"Comprendre le reconditionnement","paragraphs":["Le produit doit avoir subi des tests de ses fonctionnalités et, si nécessaire, une remise en état. Vérifiez le sens des mentions de certification. « Reconditionné en France » concerne les opérations de reconditionnement, pas nécessairement la fabrication initiale."]},{"title":"Conserver les garanties","paragraphs":["Auprès d’un vendeur professionnel, la garantie légale de conformité dure deux ans, avec des règles de preuve différentes du neuf. Ne la confondez pas avec une garantie commerciale plus courte. Gardez la description de l’exemplaire et la facture."]}],"checklist":["État et batterie précisés.","Mentions comprises.","Description et facture conservées."],"sources":[{"kind":"reference","label":"DGCCRF — Produits reconditionnés","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/produits-reconditionnes-quoi-faut-il-preter-attention-avant-dacheter"}],"order":134,"subcategory":"","homeRank":0,"tagSlugs":["budget","achats"]}','{"kind":"guides","slug":"acheter-reconditionne","title":"Reconditionné : demander l’état réel du produit","description":"Comparer les tests, la batterie et les garanties avant l’achat.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : la fiche d’un appareil neuf ne décrit pas l’exemplaire reconditionné vendu.","sections":[{"title":"Examiner les caractéristiques","paragraphs":["Demandez l’état esthétique et les performances annoncées, notamment la capacité minimale de batterie pour un téléphone. Les appellations commerciales de qualité peuvent varier entre vendeurs : comparez leur définition concrète."]},{"title":"Comprendre le reconditionnement","paragraphs":["Le produit doit avoir subi des tests de ses fonctionnalités et, si nécessaire, une remise en état. Vérifiez le sens des mentions de certification. « Reconditionné en France » concerne les opérations de reconditionnement, pas nécessairement la fabrication initiale."]},{"title":"Conserver les garanties","paragraphs":["Auprès d’un vendeur professionnel, la garantie légale de conformité dure deux ans, avec des règles de preuve différentes du neuf. Ne la confondez pas avec une garantie commerciale plus courte. Gardez la description de l’exemplaire et la facture."]}],"checklist":["État et batterie précisés.","Mentions comprises.","Description et facture conservées."],"sources":[{"kind":"reference","label":"DGCCRF — Produits reconditionnés","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/produits-reconditionnes-quoi-faut-il-preter-attention-avant-dacheter"}],"order":134,"subcategory":"","homeRank":0,"tagSlugs":["budget","achats"]}',1,'2026-10-01T06:41:56.605Z','migration');
