INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/avis-en-ligne-recul','{"kind":"guides","slug":"avis-en-ligne-recul","title":"Avis en ligne : lire les détails derrière les étoiles","description":"Croiser les témoignages sans confondre popularité et fiabilité.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : une moyenne élevée ne remplace pas des informations vérifiables.","sections":[{"title":"Examiner la méthode","paragraphs":["Cherchez comment le site collecte, vérifie et classe les avis. Regardez les dates de publication et d’expérience. La mention d’un contrôle mérite une explication, pas une confiance automatique."]},{"title":"Chercher des faits","paragraphs":["Privilégiez les détails sur l’usage du produit ou du service. Des phrases excessives ou très répétitives justifient la prudence, sans prouver à elles seules une fraude. Lisez aussi les critiques et les réponses apportées."]},{"title":"Croiser les sources","paragraphs":["Comparez plusieurs espaces d’avis avec les caractéristiques et les conditions du vendeur. Ne publiez pas un faux témoignage ou un avis positif imposé en échange d’un cadeau. Votre propre avis doit décrire votre expérience réelle."]}],"checklist":["Méthode de contrôle lue.","Dates et détails examinés.","Informations recoupées."],"sources":[{"kind":"reference","label":"DGCCRF — Avis en ligne","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/avis-en-ligne-attention-aux-faux-commentaires"}],"order":135,"subcategory":"","homeRank":0,"tagSlugs":["arnaques","achats","decisions"]}','{"kind":"guides","slug":"avis-en-ligne-recul","title":"Avis en ligne : lire les détails derrière les étoiles","description":"Croiser les témoignages sans confondre popularité et fiabilité.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : une moyenne élevée ne remplace pas des informations vérifiables.","sections":[{"title":"Examiner la méthode","paragraphs":["Cherchez comment le site collecte, vérifie et classe les avis. Regardez les dates de publication et d’expérience. La mention d’un contrôle mérite une explication, pas une confiance automatique."]},{"title":"Chercher des faits","paragraphs":["Privilégiez les détails sur l’usage du produit ou du service. Des phrases excessives ou très répétitives justifient la prudence, sans prouver à elles seules une fraude. Lisez aussi les critiques et les réponses apportées."]},{"title":"Croiser les sources","paragraphs":["Comparez plusieurs espaces d’avis avec les caractéristiques et les conditions du vendeur. Ne publiez pas un faux témoignage ou un avis positif imposé en échange d’un cadeau. Votre propre avis doit décrire votre expérience réelle."]}],"checklist":["Méthode de contrôle lue.","Dates et détails examinés.","Informations recoupées."],"sources":[{"kind":"reference","label":"DGCCRF — Avis en ligne","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/avis-en-ligne-attention-aux-faux-commentaires"}],"order":135,"subcategory":"","homeRank":0,"tagSlugs":["arnaques","achats","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
