INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/resilier-abonnement-en-ligne','{"kind":"guides","slug":"resilier-abonnement-en-ligne","title":"Abonnement : aller jusqu’à la confirmation de résiliation","description":"Vérifier les conditions et conserver la preuve de votre demande.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : fermer une application ou arrêter de l’utiliser ne résilie pas son abonnement.","sections":[{"title":"Relire l’engagement","paragraphs":["Retrouvez contrat, référence client, durée et conditions de rupture. La procédure de résiliation en ligne simplifie la démarche ; elle ne supprime pas automatiquement les délais ou sommes prévus par le contrat."]},{"title":"Utiliser la fonctionnalité prévue","paragraphs":["Lorsqu’un professionnel permet de souscrire en ligne, le dispositif applicable prévoit une fonctionnalité gratuite de résiliation en ligne, y compris pour des contrats souscrits autrement. Passez par son site ou son application officielle."]},{"title":"Garder la preuve","paragraphs":["Allez jusqu’à la validation finale et conservez la confirmation, la date d’effet et les éventuelles instructions de retour de matériel. Vérifiez ensuite la facture de clôture. Si la démarche échoue, gardez une trace du blocage et contactez le professionnel par écrit."]}],"checklist":["Conditions relues.","Demande validée.","Date d’effet et dernière facture contrôlées."],"sources":[{"kind":"reference","label":"Ministère de l’Économie — Résiliation en ligne des contrats","url":"https://presse.economie.gouv.fr/01062023-cp-entree-en-vigueur-de-la-resiliation-en-ligne-des-contrats-en-trois-clics/"}],"order":136,"subcategory":"","homeRank":0,"tagSlugs":["budget","achats","recours"]}','{"kind":"guides","slug":"resilier-abonnement-en-ligne","title":"Abonnement : aller jusqu’à la confirmation de résiliation","description":"Vérifier les conditions et conserver la preuve de votre demande.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : fermer une application ou arrêter de l’utiliser ne résilie pas son abonnement.","sections":[{"title":"Relire l’engagement","paragraphs":["Retrouvez contrat, référence client, durée et conditions de rupture. La procédure de résiliation en ligne simplifie la démarche ; elle ne supprime pas automatiquement les délais ou sommes prévus par le contrat."]},{"title":"Utiliser la fonctionnalité prévue","paragraphs":["Lorsqu’un professionnel permet de souscrire en ligne, le dispositif applicable prévoit une fonctionnalité gratuite de résiliation en ligne, y compris pour des contrats souscrits autrement. Passez par son site ou son application officielle."]},{"title":"Garder la preuve","paragraphs":["Allez jusqu’à la validation finale et conservez la confirmation, la date d’effet et les éventuelles instructions de retour de matériel. Vérifiez ensuite la facture de clôture. Si la démarche échoue, gardez une trace du blocage et contactez le professionnel par écrit."]}],"checklist":["Conditions relues.","Demande validée.","Date d’effet et dernière facture contrôlées."],"sources":[{"kind":"reference","label":"Ministère de l’Économie — Résiliation en ligne des contrats","url":"https://presse.economie.gouv.fr/01062023-cp-entree-en-vigueur-de-la-resiliation-en-ligne-des-contrats-en-trois-clics/"}],"order":136,"subcategory":"","homeRank":0,"tagSlugs":["budget","achats","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
