INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/foire-salon-signature','{"kind":"guides","slug":"foire-salon-signature","title":"Foire ou salon : ne pas signer pour simplement réserver un prix","description":"Prendre le temps de comparer avant un engagement sur un stand.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : n’imaginez pas disposer automatiquement de quatorze jours pour changer d’avis.","sections":[{"title":"Identifier l’engagement","paragraphs":["Un bon de commande signé peut vous engager immédiatement. Dans le cas habituel d’un contrat conclu sur une foire ou un salon, il n’existe pas de droit de rétractation automatique ; le professionnel doit vous en informer."]},{"title":"Emporter les éléments","paragraphs":["Demandez une proposition détaillée et comparez hors du stand : prestation, prix total, calendrier et identité du vendeur. Une remise annoncée comme valable quelques minutes ne justifie pas de signer un document incompris."]},{"title":"Vérifier un financement lié","paragraphs":["Un crédit affecté peut ouvrir des droits spécifiques, distincts d’un achat payé comptant. Faites vérifier les documents si vous souhaitez revenir sur un engagement. Conservez l’ensemble du contrat, pas seulement la première page ou le reçu d’acompte."]}],"checklist":["Document compris avant signature.","Offre comparée au calme.","Financement et droits vérifiés."],"sources":[{"kind":"reference","label":"DGCCRF — Contrats conclus dans les foires et salons","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/le-contrat-un-accord-entre-des-parties-bien-informees-au-prealable"}],"order":137,"subcategory":"","homeRank":0,"tagSlugs":["budget","achats","decisions"]}','{"kind":"guides","slug":"foire-salon-signature","title":"Foire ou salon : ne pas signer pour simplement réserver un prix","description":"Prendre le temps de comparer avant un engagement sur un stand.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : n’imaginez pas disposer automatiquement de quatorze jours pour changer d’avis.","sections":[{"title":"Identifier l’engagement","paragraphs":["Un bon de commande signé peut vous engager immédiatement. Dans le cas habituel d’un contrat conclu sur une foire ou un salon, il n’existe pas de droit de rétractation automatique ; le professionnel doit vous en informer."]},{"title":"Emporter les éléments","paragraphs":["Demandez une proposition détaillée et comparez hors du stand : prestation, prix total, calendrier et identité du vendeur. Une remise annoncée comme valable quelques minutes ne justifie pas de signer un document incompris."]},{"title":"Vérifier un financement lié","paragraphs":["Un crédit affecté peut ouvrir des droits spécifiques, distincts d’un achat payé comptant. Faites vérifier les documents si vous souhaitez revenir sur un engagement. Conservez l’ensemble du contrat, pas seulement la première page ou le reçu d’acompte."]}],"checklist":["Document compris avant signature.","Offre comparée au calme.","Financement et droits vérifiés."],"sources":[{"kind":"reference","label":"DGCCRF — Contrats conclus dans les foires et salons","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/le-contrat-un-accord-entre-des-parties-bien-informees-au-prealable"}],"order":137,"subcategory":"","homeRank":0,"tagSlugs":["budget","achats","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
