INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/comparateur-classement','{"kind":"guides","slug":"comparateur-classement","title":"Comparateur en ligne : vérifier ce que signifie la première place","description":"Comprendre le classement, les partenaires et le prix final.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : le premier résultat n’est pas nécessairement la meilleure offre pour vous.","sections":[{"title":"Lire le fonctionnement","paragraphs":["Cherchez les critères de classement et l’influence éventuelle d’une rémunération ou d’un partenariat. Le comparateur doit expliquer ces éléments. Modifiez le tri si le classement proposé ne correspond pas à votre besoin."]},{"title":"Examiner le périmètre","paragraphs":["Vérifiez si les offres sont exhaustives et quand elles sont actualisées. Un résultat absent ne signifie pas qu’une offre n’existe pas. Comparez des prestations équivalentes plutôt que des prix présentés sans leurs conditions."]},{"title":"Recontrôler chez le vendeur","paragraphs":["Avant de payer, vérifiez montant total, frais supplémentaires, garanties et disponibilité sur l’offre finale. Gardez les caractéristiques importantes. Un comparateur aide à présélectionner ; la décision exige encore de lire le contrat proposé."]}],"checklist":["Classement compris.","Périmètre et actualisation vérifiés.","Prix final recontrôlé."],"sources":[{"kind":"reference","label":"Ministère de l’Économie — Comparateurs en ligne","url":"https://www.economie.gouv.fr/particuliers/emprunter-et-sassurer/comparateurs-en-ligne-quelles-sont-les-obligations-dinformation"}],"order":138,"subcategory":"","homeRank":0,"tagSlugs":["budget","achats","decisions"]}','{"kind":"guides","slug":"comparateur-classement","title":"Comparateur en ligne : vérifier ce que signifie la première place","description":"Comprendre le classement, les partenaires et le prix final.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : le premier résultat n’est pas nécessairement la meilleure offre pour vous.","sections":[{"title":"Lire le fonctionnement","paragraphs":["Cherchez les critères de classement et l’influence éventuelle d’une rémunération ou d’un partenariat. Le comparateur doit expliquer ces éléments. Modifiez le tri si le classement proposé ne correspond pas à votre besoin."]},{"title":"Examiner le périmètre","paragraphs":["Vérifiez si les offres sont exhaustives et quand elles sont actualisées. Un résultat absent ne signifie pas qu’une offre n’existe pas. Comparez des prestations équivalentes plutôt que des prix présentés sans leurs conditions."]},{"title":"Recontrôler chez le vendeur","paragraphs":["Avant de payer, vérifiez montant total, frais supplémentaires, garanties et disponibilité sur l’offre finale. Gardez les caractéristiques importantes. Un comparateur aide à présélectionner ; la décision exige encore de lire le contrat proposé."]}],"checklist":["Classement compris.","Périmètre et actualisation vérifiés.","Prix final recontrôlé."],"sources":[{"kind":"reference","label":"Ministère de l’Économie — Comparateurs en ligne","url":"https://www.economie.gouv.fr/particuliers/emprunter-et-sassurer/comparateurs-en-ligne-quelles-sont-les-obligations-dinformation"}],"order":138,"subcategory":"","homeRank":0,"tagSlugs":["budget","achats","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
