INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/demarchage-domicile-contrat','{"kind":"guides","slug":"demarchage-domicile-contrat","title":"Démarchage à domicile : garder du temps pour décider","description":"Contrôler le contrat, le paiement et les modalités de rétractation.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : la présence du vendeur chez vous ne vous oblige pas à signer.","sections":[{"title":"Demander les documents","paragraphs":["Vérifiez l’identité de l’entreprise et obtenez la proposition complète. Si vous signez, un exemplaire du contrat doit vous être remis. Ne vous contentez pas d’une promesse d’envoi ultérieur."]},{"title":"Vérifier le paiement","paragraphs":["Sauf exceptions réglementaires, aucune contrepartie ne doit être versée durant les sept jours suivant la conclusion d’un contrat hors établissement. Un chèque postdaté ou une autorisation de prélèvement ne contourne pas cette règle."]},{"title":"Repérer votre recours","paragraphs":["Le délai de rétractation est généralement de quatorze jours, avec des exceptions et des modalités selon le contrat. Consultez la fiche officielle et gardez la preuve de votre notification. En cas de pression ou d’information manquante, conservez les échanges pour un signalement."]}],"checklist":["Entreprise et contrat vérifiés.","Paiement non précipité.","Modalités de rétractation retrouvées."],"sources":[{"kind":"reference","label":"DGCCRF — Démarchage à domicile","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/faq-contrats-conclus-hors-etablissement-et-demarchage-domicile"}],"order":139,"subcategory":"","homeRank":0,"tagSlugs":["arnaques","achats","recours"]}','{"kind":"guides","slug":"demarchage-domicile-contrat","title":"Démarchage à domicile : garder du temps pour décider","description":"Contrôler le contrat, le paiement et les modalités de rétractation.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : la présence du vendeur chez vous ne vous oblige pas à signer.","sections":[{"title":"Demander les documents","paragraphs":["Vérifiez l’identité de l’entreprise et obtenez la proposition complète. Si vous signez, un exemplaire du contrat doit vous être remis. Ne vous contentez pas d’une promesse d’envoi ultérieur."]},{"title":"Vérifier le paiement","paragraphs":["Sauf exceptions réglementaires, aucune contrepartie ne doit être versée durant les sept jours suivant la conclusion d’un contrat hors établissement. Un chèque postdaté ou une autorisation de prélèvement ne contourne pas cette règle."]},{"title":"Repérer votre recours","paragraphs":["Le délai de rétractation est généralement de quatorze jours, avec des exceptions et des modalités selon le contrat. Consultez la fiche officielle et gardez la preuve de votre notification. En cas de pression ou d’information manquante, conservez les échanges pour un signalement."]}],"checklist":["Entreprise et contrat vérifiés.","Paiement non précipité.","Modalités de rétractation retrouvées."],"sources":[{"kind":"reference","label":"DGCCRF — Démarchage à domicile","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/faq-contrats-conclus-hors-etablissement-et-demarchage-domicile"}],"order":139,"subcategory":"","homeRank":0,"tagSlugs":["arnaques","achats","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
