INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/labels-alimentaires-comprendre','{"kind":"guides","slug":"labels-alimentaires-comprendre","title":"Labels alimentaires : savoir ce que le logo garantit","description":"Distinguer origine, mode de production et qualité particulière.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : un label apporte une garantie précise, pas une supériorité sur tous les critères.","sections":[{"title":"Identifier le signe","paragraphs":["Cherchez le nom exact du label et son cahier des charges. Les signes officiels de qualité et d’origine reposent sur des exigences et des contrôles. Un décor de ferme ou une couleur verte ne constitue pas à lui seul un label."]},{"title":"Comparer la bonne promesse","paragraphs":["L’AOP rattache fortement un produit à un terroir et à un savoir-faire. Le Label Rouge porte sur une qualité supérieure par rapport à des produits similaires. D’autres signes répondent à d’autres critères : évitez de les traiter comme interchangeables."]},{"title":"Relire aussi l’étiquette","paragraphs":["Continuez à comparer ingrédients, quantité et prix selon vos besoins. Le logo ne remplace pas les informations du produit. Si une mention vous semble vague, consultez sa définition officielle avant d’accepter de payer davantage."]}],"checklist":["Label identifié.","Garantie exacte comprise.","Étiquette et prix comparés."],"sources":[{"kind":"reference","label":"Ministère de l’Économie — Labels alimentaires","url":"https://www.economie.gouv.fr/particuliers/mes-droits-conso/alimentation/aop-aoc-igp-ab-ce-quil-faut-savoir-sur-les-labels-de?language=fr"}],"order":140,"subcategory":"","homeRank":0,"tagSlugs":["budget","courses","achats"]}','{"kind":"guides","slug":"labels-alimentaires-comprendre","title":"Labels alimentaires : savoir ce que le logo garantit","description":"Distinguer origine, mode de production et qualité particulière.","categoryId":"argent-consommation","themeId":"achats","reviewedAt":"2026-09-29","intro":"La règle d’or : un label apporte une garantie précise, pas une supériorité sur tous les critères.","sections":[{"title":"Identifier le signe","paragraphs":["Cherchez le nom exact du label et son cahier des charges. Les signes officiels de qualité et d’origine reposent sur des exigences et des contrôles. Un décor de ferme ou une couleur verte ne constitue pas à lui seul un label."]},{"title":"Comparer la bonne promesse","paragraphs":["L’AOP rattache fortement un produit à un terroir et à un savoir-faire. Le Label Rouge porte sur une qualité supérieure par rapport à des produits similaires. D’autres signes répondent à d’autres critères : évitez de les traiter comme interchangeables."]},{"title":"Relire aussi l’étiquette","paragraphs":["Continuez à comparer ingrédients, quantité et prix selon vos besoins. Le logo ne remplace pas les informations du produit. Si une mention vous semble vague, consultez sa définition officielle avant d’accepter de payer davantage."]}],"checklist":["Label identifié.","Garantie exacte comprise.","Étiquette et prix comparés."],"sources":[{"kind":"reference","label":"Ministère de l’Économie — Labels alimentaires","url":"https://www.economie.gouv.fr/particuliers/mes-droits-conso/alimentation/aop-aoc-igp-ab-ce-quil-faut-savoir-sur-les-labels-de?language=fr"}],"order":140,"subcategory":"","homeRank":0,"tagSlugs":["budget","courses","achats"]}',1,'2026-10-01T06:41:56.605Z','migration');
