INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/formats-familiaux-prix-kilo','{"kind":"guides","slug":"formats-familiaux-prix-kilo","title":"Format familial : comparer avant de remplir le panier","description":"Comparer les quantités, le prix au kilo et ce que vous utiliserez vraiment.","intro":"La règle d’or : un grand paquet ne prouve pas une économie. Ramenez les offres à la même unité avant de choisir.","themeId":"achats","categoryId":"argent-consommation","reviewedAt":"2026-09-29","sections":[{"title":"Comparer des produits équivalents","paragraphs":["Vérifiez la référence, la composition et la quantité nette. La DGCCRF rappelle que le prix au kilo ou au litre accompagne le prix de vente pour la majorité des produits alimentaires préemballés, avec des exceptions. Deux emballages proches peuvent contenir des quantités différentes."]},{"title":"Faire un calcul simple","paragraphs":["Exemple fictif : 400 g à 3 € représentent 7,50 €/kg ; 750 g à 6 € représentent 8 €/kg. Le plus gros paquet revient ici plus cher à quantité égale. Divisez le prix par le poids en kilogrammes, ou par le volume en litres."]},{"title":"Acheter la quantité utile","paragraphs":["Comparez d’abord le montant payé immédiatement, puis les éventuels avantages différés. Un lot oblige parfois à acheter davantage que prévu. Avant de le choisir, vérifiez votre stock, la place disponible et la quantité que vous consommerez. L’analyse des formats proposée par Olivier Dauvers inspire ce réflexe ; ses exemples anciens ne constituent pas un relevé de prix actuel."]}],"checklist":["Même produit et même unité comparés.","Prix au kilo ou au litre recalculé en cas de doute.","Quantité adaptée aux besoins."],"sources":[{"label":"DGCCRF — L’information sur les prix","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/linformation-sur-les-prix","kind":"reference"},{"label":"Olivier Dauvers — Quiz Grande Conso, 23 août 2023","url":"https://www.olivierdauvers.fr/2023/08/23/les-quiz-grande-conso-jai-une-colle-pour-vous/","kind":"inspiration"}],"order":142,"subcategory":"","homeRank":0,"tagSlugs":["budget","courses","achats"]}','{"kind":"guides","slug":"formats-familiaux-prix-kilo","title":"Format familial : comparer avant de remplir le panier","description":"Comparer les quantités, le prix au kilo et ce que vous utiliserez vraiment.","intro":"La règle d’or : un grand paquet ne prouve pas une économie. Ramenez les offres à la même unité avant de choisir.","themeId":"achats","categoryId":"argent-consommation","reviewedAt":"2026-09-29","sections":[{"title":"Comparer des produits équivalents","paragraphs":["Vérifiez la référence, la composition et la quantité nette. La DGCCRF rappelle que le prix au kilo ou au litre accompagne le prix de vente pour la majorité des produits alimentaires préemballés, avec des exceptions. Deux emballages proches peuvent contenir des quantités différentes."]},{"title":"Faire un calcul simple","paragraphs":["Exemple fictif : 400 g à 3 € représentent 7,50 €/kg ; 750 g à 6 € représentent 8 €/kg. Le plus gros paquet revient ici plus cher à quantité égale. Divisez le prix par le poids en kilogrammes, ou par le volume en litres."]},{"title":"Acheter la quantité utile","paragraphs":["Comparez d’abord le montant payé immédiatement, puis les éventuels avantages différés. Un lot oblige parfois à acheter davantage que prévu. Avant de le choisir, vérifiez votre stock, la place disponible et la quantité que vous consommerez. L’analyse des formats proposée par Olivier Dauvers inspire ce réflexe ; ses exemples anciens ne constituent pas un relevé de prix actuel."]}],"checklist":["Même produit et même unité comparés.","Prix au kilo ou au litre recalculé en cas de doute.","Quantité adaptée aux besoins."],"sources":[{"label":"DGCCRF — L’information sur les prix","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/linformation-sur-les-prix","kind":"reference"},{"label":"Olivier Dauvers — Quiz Grande Conso, 23 août 2023","url":"https://www.olivierdauvers.fr/2023/08/23/les-quiz-grande-conso-jai-une-colle-pour-vous/","kind":"inspiration"}],"order":142,"subcategory":"","homeRank":0,"tagSlugs":["budget","courses","achats"]}',1,'2026-10-01T06:41:56.605Z','migration');
