é","paragraphs":["Prévenez votre banque si votre IBAN est exposé. Contrôlez régulièrement les opérations et les créanciers autorisés. Signalez immédiatement un prélèvement inconnu et demandez à votre conseiller les démarches adaptées. Une fuite d’IBAN et une carte compromise appellent des mesures différentes : précisez les informations divulguées."]},{"title":"Garder les preuves et demander de l’aide","paragraphs":["Archivez l’alerte, les échanges et les opérations suspectes. En cas d’utilisation frauduleuse, conservez les justificatifs et déposez plainte auprès de la police ou de la gendarmerie. Si vous estimez que l’organisme a insuffisamment sécurisé vos données, une plainte auprès de la CNIL relève d’une démarche distincte. Le service public 17Cyber peut vous orienter."]}],"checklist":["Alerte confirmée auprès de l’organisme concerné.","Données exposées identifiées.","Mots de passe concernés remplacés et double authentification activée.","Opérations bancaires surveillées si nécessaire.","Messages suspects et justificatifs conservés."],"reviewedAt":"2026-09-29","sources":[{"kind":"inspiration","label":"ZATAZ — Vos données ont-elles déjà fuité ?","url":"https://www.zataz.com/vos-donnees-ont-elles-deja-fuite/"},{"kind":"reference","label":"Cybermalveillance.gouv.fr — Fuite de données personnelles : que faire ?","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/que-faire-en-cas-de-fuite-de-donnees-personnelles"},{"kind":"reference","label":"CNIL — Fuite de données et vol de votre IBAN","url":"https://www.cnil.fr/fr/fuite-de-donnees-sur-internet-et-vol-de-votre-iban-comment-vous-proteger-si-vous-etes-concerne"}],"order":145,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles","arnaques"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/faux-conseiller-bancaire','{"kind":"guides","slug":"faux-conseiller-bancaire","title":"Faux conseiller bancaire : interrompre le piège","themeId":"numerique","categoryId":"cybersecurite","description":"Vérifier l’appel et agir rapidement si des opérations ont été validées.","intro":"La règle d’or : raccrochez et contactez votre banque par votre canal habituel avant toute validation. Un numéro affiché et des informations exactes ne prouvent pas l’identité de l’appelant.","sections":[{"title":"Pendant l’appel","paragraphs":["Ne donnez aucun code et ne confirmez pas une opération présentée comme une annulation de fraude. Ne remettez pas votre carte à un coursier. Retrouvez vous-même le contact de votre banque dans votre application ou vos documents."]},{"title":"Si vous avez déjà agi","paragraphs":["Alertez immédiatement la banque, faites opposition à la carte compromise et signalez précisément les paiements ou virements concernés. Demandez les mesures de blocage et de récupération possibles. Faites réinitialiser vos accès si nécessaire."]},{"title":"Conserver les éléments utiles","paragraphs":["Gardez les messages, numéros, horaires et références des opérations ; déposez plainte. Une demande de remboursement doit être examinée selon les faits : ne présumez ni son acceptation ni son refus."]}],"checklist":["Contact bancaire retrouvé indépendamment.","Opérations suspectes listées.","Preuves conservées."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Fraude au faux conseiller bancaire","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/fraude-faux-conseiller-bancaire"}],"order":146,"subcategory":"","homeRank":1,"tagSlugs":["cybersecurite","arnaques","recours"]}','{"kind":"guides","slug":"faux-conseiller-bancaire","title":"Faux conseiller bancaire : interrompre le piège","themeId":"numerique","categoryId":"cybersecurite","description":"Vérifier l’appel et agir rapidement si des opérations ont été validées.","intro":"La règle d’or : raccrochez et contactez votre banque par votre canal habituel avant toute validation. Un numéro affiché et des informations exactes ne prouvent pas l’identité de l’appelant.","sections":[{"title":"Pendant l’appel","paragraphs":["Ne donnez aucun code et ne confirmez pas une opération présentée comme une annulation de fraude. Ne remettez pas votre carte à un coursier. Retrouvez vous-même le contact de votre banque dans votre application ou vos documents."]},{"title":"Si vous avez déjà agi","paragraphs":["Alertez immédiatement la banque, faites opposition à la carte compromise et signalez précisément les paiements ou virements concernés. Demandez les mesures de blocage et de récupération possibles. Faites réinitialiser vos accès si nécessaire."]},{"title":"Conserver les éléments utiles","paragraphs":["Gardez les messages, numéros, horaires et références des opérations ; déposez plainte. Une demande de remboursement doit être examinée selon les faits : ne présumez ni son acceptation ni son refus."]}],"checklist":["Contact bancaire retrouvé indépendamment.","Opérations suspectes listées.","Preuves conservées."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Fraude au faux conseiller bancaire","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/fraude-faux-conseiller-bancaire"}],"order":146,"subcategory":"","homeRank":1,"tagSlugs":["cybersecurite","arnaques","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
