INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/colis-livre-introuvable','{"kind":"guides","slug":"colis-livre-introuvable","title":"Colis annoncé livré mais introuvable : contester par écrit","themeId":"achats","categoryId":"argent-consommation","description":"Rassembler le suivi et solliciter le vendeur professionnel.","intro":"La règle d’or : pour un achat en ligne auprès d’un professionnel, adressez la réclamation au vendeur, sans vous limiter au transporteur.","sections":[{"title":"Vérifier sans attendre","paragraphs":["Contrôlez l’adresse de commande, le suivi et les éventuelles consignes de livraison. Enregistrez une capture du statut et la confirmation d’achat. Notez clairement que vous n’avez pas reçu le colis, sans signer de déclaration inexacte."]},{"title":"Contacter le bon interlocuteur","paragraphs":["Demandez au vendeur une vérification de la remise et une solution. Il répond en principe du transport organisé par ses soins. La situation diffère si vous avez choisi un transporteur autre que ceux proposés. Sur une marketplace, identifiez le vendeur réel."]},{"title":"Formaliser la suite","paragraphs":["Conservez les réponses et les pièces demandées. Pour un litige transfrontalier européen, le Centre Européen des Consommateurs peut vous orienter. Une mention informatique « livré » doit être confrontée aux faits : expliquez précisément votre contestation."]}],"checklist":["Commande et suivi archivés.","Vendeur identifié.","Réclamation datée conservée."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Centre Européen des Consommateurs — Réception de colis","url":"https://www.europe-consommateurs.eu/thematiques/achats/colis/reception/"}],"order":147,"subcategory":"","homeRank":2,"tagSlugs":["achats","recours"]}','{"kind":"guides","slug":"colis-livre-introuvable","title":"Colis annoncé livré mais introuvable : contester par écrit","themeId":"achats","categoryId":"argent-consommation","description":"Rassembler le suivi et solliciter le vendeur professionnel.","intro":"La règle d’or : pour un achat en ligne auprès d’un professionnel, adressez la réclamation au vendeur, sans vous limiter au transporteur.","sections":[{"title":"Vérifier sans attendre","paragraphs":["Contrôlez l’adresse de commande, le suivi et les éventuelles consignes de livraison. Enregistrez une capture du statut et la confirmation d’achat. Notez clairement que vous n’avez pas reçu le colis, sans signer de déclaration inexacte."]},{"title":"Contacter le bon interlocuteur","paragraphs":["Demandez au vendeur une vérification de la remise et une solution. Il répond en principe du transport organisé par ses soins. La situation diffère si vous avez choisi un transporteur autre que ceux proposés. Sur une marketplace, identifiez le vendeur réel."]},{"title":"Formaliser la suite","paragraphs":["Conservez les réponses et les pièces demandées. Pour un litige transfrontalier européen, le Centre Européen des Consommateurs peut vous orienter. Une mention informatique « livré » doit être confrontée aux faits : expliquez précisément votre contestation."]}],"checklist":["Commande et suivi archivés.","Vendeur identifié.","Réclamation datée conservée."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Centre Européen des Consommateurs — Réception de colis","url":"https://www.europe-consommateurs.eu/thematiques/achats/colis/reception/"}],"order":147,"subcategory":"","homeRank":2,"tagSlugs":["achats","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
