INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/appareil-panne-garantie','{"kind":"guides","slug":"appareil-panne-garantie","title":"Appareil en panne : identifier la garantie à utiliser","themeId":"achats","categoryId":"argent-consommation","description":"Distinguer garantie légale et garantie commerciale avant de payer une réparation.","intro":"La règle d’or : pour la garantie légale de conformité, contactez le vendeur professionnel avec votre preuve d’achat.","sections":[{"title":"Qualifier le problème","paragraphs":["Décrivez le défaut, son apparition et les conditions d’utilisation. La garantie concerne une non-conformité existant à la délivrance ; une mauvaise utilisation n’est pas couverte. Conservez facture, date de réception, photos et échanges."]},{"title":"Demander la prise en charge","paragraphs":["Pour un bien matériel, le délai de principe est de deux ans après sa délivrance. Demandez réparation ou remplacement selon les conditions légales. Un remboursement immédiat n’est pas automatique ; il devient possible dans certaines situations prévues par la loi."]},{"title":"Éviter la confusion","paragraphs":["Une extension payante ou une garantie du fabricant est distincte de la garantie légale. Ne concluez pas que vous n’avez aucun droit parce que cette offre commerciale est expirée. Des règles particulières existent pour les éléments numériques et les biens d’occasion : consultez la fiche officielle."]}],"checklist":["Date de délivrance retrouvée.","Défaut documenté.","Vendeur sollicité par écrit."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Service Public — Garantie légale de conformité","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F11094"}],"order":148,"subcategory":"","homeRank":0,"tagSlugs":["achats","recours"]}','{"kind":"guides","slug":"appareil-panne-garantie","title":"Appareil en panne : identifier la garantie à utiliser","themeId":"achats","categoryId":"argent-consommation","description":"Distinguer garantie légale et garantie commerciale avant de payer une réparation.","intro":"La règle d’or : pour la garantie légale de conformité, contactez le vendeur professionnel avec votre preuve d’achat.","sections":[{"title":"Qualifier le problème","paragraphs":["Décrivez le défaut, son apparition et les conditions d’utilisation. La garantie concerne une non-conformité existant à la délivrance ; une mauvaise utilisation n’est pas couverte. Conservez facture, date de réception, photos et échanges."]},{"title":"Demander la prise en charge","paragraphs":["Pour un bien matériel, le délai de principe est de deux ans après sa délivrance. Demandez réparation ou remplacement selon les conditions légales. Un remboursement immédiat n’est pas automatique ; il devient possible dans certaines situations prévues par la loi."]},{"title":"Éviter la confusion","paragraphs":["Une extension payante ou une garantie du fabricant est distincte de la garantie légale. Ne concluez pas que vous n’avez aucun droit parce que cette offre commerciale est expirée. Des règles particulières existent pour les éléments numériques et les biens d’occasion : consultez la fiche officielle."]}],"checklist":["Date de délivrance retrouvée.","Défaut documenté.","Vendeur sollicité par écrit."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Service Public — Garantie légale de conformité","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F11094"}],"order":148,"subcategory":"","homeRank":0,"tagSlugs":["achats","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
