INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/achat-retractation','{"kind":"guides","slug":"achat-retractation","title":"Achat en ligne : se rétracter sans rater les étapes","themeId":"achats","categoryId":"argent-consommation","description":"Vérifier le droit applicable, notifier sa décision et prouver le retour.","intro":"La règle d’or : annoncez explicitement votre rétractation ; renvoyer simplement le colis ne suffit pas.","sections":[{"title":"Vérifier que le droit existe","paragraphs":["Pour un achat de bien à distance auprès d’un professionnel européen, le délai est en principe de quatorze jours à compter du lendemain de la réception. Des exceptions concernent notamment les produits personnalisés ou périssables. Un achat en magasin n’ouvre pas systématiquement ce droit."]},{"title":"Notifier puis retourner","paragraphs":["Utilisez le formulaire proposé ou un écrit clair et conservez une preuve d’envoi. Renvoyez ensuite le bien dans les quatorze jours suivant la notification, à l’adresse indiquée. Vérifiez les frais de retour annoncés avant l’achat."]},{"title":"Suivre le remboursement","paragraphs":["Gardez la preuve d’expédition et photographiez le contenu. Le vendeur peut, sous conditions, différer le remboursement jusqu’au retour du bien ou à la preuve d’envoi. Si le produit est défectueux, distinguez cette démarche d’une demande au titre de la garantie."]}],"checklist":["Exceptions vérifiées.","Décision notifiée.","Retour traçable conservé."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Centre Européen des Consommateurs — Rétractation","url":"https://www.europe-consommateurs.eu/thematiques/garanties/retractation/"}],"order":149,"subcategory":"","homeRank":0,"tagSlugs":["achats","recours"]}','{"kind":"guides","slug":"achat-retractation","title":"Achat en ligne : se rétracter sans rater les étapes","themeId":"achats","categoryId":"argent-consommation","description":"Vérifier le droit applicable, notifier sa décision et prouver le retour.","intro":"La règle d’or : annoncez explicitement votre rétractation ; renvoyer simplement le colis ne suffit pas.","sections":[{"title":"Vérifier que le droit existe","paragraphs":["Pour un achat de bien à distance auprès d’un professionnel européen, le délai est en principe de quatorze jours à compter du lendemain de la réception. Des exceptions concernent notamment les produits personnalisés ou périssables. Un achat en magasin n’ouvre pas systématiquement ce droit."]},{"title":"Notifier puis retourner","paragraphs":["Utilisez le formulaire proposé ou un écrit clair et conservez une preuve d’envoi. Renvoyez ensuite le bien dans les quatorze jours suivant la notification, à l’adresse indiquée. Vérifiez les frais de retour annoncés avant l’achat."]},{"title":"Suivre le remboursement","paragraphs":["Gardez la preuve d’expédition et photographiez le contenu. Le vendeur peut, sous conditions, différer le remboursement jusqu’au retour du bien ou à la preuve d’envoi. Si le produit est défectueux, distinguez cette démarche d’une demande au titre de la garantie."]}],"checklist":["Exceptions vérifiées.","Décision notifiée.","Retour traçable conservé."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Centre Européen des Consommateurs — Rétractation","url":"https://www.europe-consommateurs.eu/thematiques/garanties/retractation/"}],"order":149,"subcategory":"","homeRank":0,"tagSlugs":["achats","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
