INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/arrhes-ou-acompte','{"kind":"guides","slug":"arrhes-ou-acompte","title":"Arrhes ou acompte : savoir à quoi le versement engage","themeId":"achats","categoryId":"argent-consommation","description":"Lire la qualification du paiement avant de réserver ou commander.","intro":"La règle d’or : faites écrire la nature du versement et les conditions d’annulation avant de payer.","sections":[{"title":"Lire les mots du contrat","paragraphs":["Un acompte engage en principe fermement les deux parties. Les arrhes permettent généralement au consommateur de se désister en perdant la somme versée. Dans les contrats de consommation concernés, une avance non qualifiée est en principe considérée comme des arrhes."]},{"title":"Ne pas confondre les mécanismes","paragraphs":["Ces règles ne suppriment pas un droit légal de rétractation lorsqu’il s’applique. Une annulation, une inexécution du professionnel et un changement d’avis ne se traitent pas de la même façon. Vérifiez les règles propres au contrat."]},{"title":"Garder une preuve précise","paragraphs":["Demandez un reçu mentionnant le professionnel, le montant, la commande et la qualification du paiement. Avant d’accepter un avoir, vérifiez si vous pouvez demander un remboursement : un crédit à dépenser chez le vendeur n’est pas de l’argent restitué."]}],"checklist":["Nature du versement écrite.","Annulation comprise.","Reçu et contrat conservés."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"DGCCRF — Acompte, arrhes, avoir","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/acompte-arrhes-avoir"}],"order":150,"subcategory":"","homeRank":0,"tagSlugs":["achats"]}','{"kind":"guides","slug":"arrhes-ou-acompte","title":"Arrhes ou acompte : savoir à quoi le versement engage","themeId":"achats","categoryId":"argent-consommation","description":"Lire la qualification du paiement avant de réserver ou commander.","intro":"La règle d’or : faites écrire la nature du versement et les conditions d’annulation avant de payer.","sections":[{"title":"Lire les mots du contrat","paragraphs":["Un acompte engage en principe fermement les deux parties. Les arrhes permettent généralement au consommateur de se désister en perdant la somme versée. Dans les contrats de consommation concernés, une avance non qualifiée est en principe considérée comme des arrhes."]},{"title":"Ne pas confondre les mécanismes","paragraphs":["Ces règles ne suppriment pas un droit légal de rétractation lorsqu’il s’applique. Une annulation, une inexécution du professionnel et un changement d’avis ne se traitent pas de la même façon. Vérifiez les règles propres au contrat."]},{"title":"Garder une preuve précise","paragraphs":["Demandez un reçu mentionnant le professionnel, le montant, la commande et la qualification du paiement. Avant d’accepter un avoir, vérifiez si vous pouvez demander un remboursement : un crédit à dépenser chez le vendeur n’est pas de l’argent restitué."]}],"checklist":["Nature du versement écrite.","Annulation comprise.","Reçu et contrat conservés."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"DGCCRF — Acompte, arrhes, avoir","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/acompte-arrhes-avoir"}],"order":150,"subcategory":"","homeRank":0,"tagSlugs":["achats"]}',1,'2026-10-01T06:41:56.605Z','migration');
