INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/mediation-consommation','{"kind":"guides","slug":"mediation-consommation","title":"Litige commercial : préparer une médiation utile","themeId":"achats","categoryId":"argent-consommation","description":"Constituer un dossier clair après une réclamation restée sans solution.","intro":"La règle d’or : commencez par une réclamation écrite au professionnel et gardez sa trace.","sections":[{"title":"Formuler une demande concrète","paragraphs":["Rappelez la commande, les dates, le problème et la solution souhaitée. Joignez les pièces utiles, sans noyer votre interlocuteur sous des échanges sans rapport. Conservez la réponse ou la preuve de votre démarche."]},{"title":"Choisir le médiateur compétent","paragraphs":["Consultez les coordonnées indiquées par le professionnel et les conditions du dispositif. En principe, la saisine doit intervenir dans l’année suivant la réclamation écrite. Un litige déjà examiné ou en cours devant un autre médiateur ou un tribunal ne suit pas cette voie."]},{"title":"Comprendre le résultat attendu","paragraphs":["La médiation de la consommation est gratuite pour le consommateur, hors frais éventuels de ses propres conseils ou expertises. Le médiateur propose une solution amiable ; ce n’est pas un jugement. Certaines matières sont exclues : vérifiez la recevabilité avant l’envoi."]}],"checklist":["Réclamation préalable jointe.","Médiateur et délai vérifiés.","Solution demandée précisée."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Service Public Entreprendre — Médiation des litiges de consommation","url":"https://entreprendre.service-public.gouv.fr/vosdroits/F33338"},{"kind":"reference","label":"Ministère de l’Économie — Droits du consommateur en médiation","url":"https://www.economie.gouv.fr/mediation-conso/vous-etes-un-consommateur/vos-droits"}],"order":151,"subcategory":"","homeRank":0,"tagSlugs":["achats","recours"]}','{"kind":"guides","slug":"mediation-consommation","title":"Litige commercial : préparer une médiation utile","themeId":"achats","categoryId":"argent-consommation","description":"Constituer un dossier clair après une réclamation restée sans solution.","intro":"La règle d’or : commencez par une réclamation écrite au professionnel et gardez sa trace.","sections":[{"title":"Formuler une demande concrète","paragraphs":["Rappelez la commande, les dates, le problème et la solution souhaitée. Joignez les pièces utiles, sans noyer votre interlocuteur sous des échanges sans rapport. Conservez la réponse ou la preuve de votre démarche."]},{"title":"Choisir le médiateur compétent","paragraphs":["Consultez les coordonnées indiquées par le professionnel et les conditions du dispositif. En principe, la saisine doit intervenir dans l’année suivant la réclamation écrite. Un litige déjà examiné ou en cours devant un autre médiateur ou un tribunal ne suit pas cette voie."]},{"title":"Comprendre le résultat attendu","paragraphs":["La médiation de la consommation est gratuite pour le consommateur, hors frais éventuels de ses propres conseils ou expertises. Le médiateur propose une solution amiable ; ce n’est pas un jugement. Certaines matières sont exclues : vérifiez la recevabilité avant l’envoi."]}],"checklist":["Réclamation préalable jointe.","Médiateur et délai vérifiés.","Solution demandée précisée."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Service Public Entreprendre — Médiation des litiges de consommation","url":"https://entreprendre.service-public.gouv.fr/vosdroits/F33338"},{"kind":"reference","label":"Ministère de l’Économie — Droits du consommateur en médiation","url":"https://www.economie.gouv.fr/mediation-conso/vous-etes-un-consommateur/vos-droits"}],"order":151,"subcategory":"","homeRank":0,"tagSlugs":["achats","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
