INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/etat-lieux-entree','{"kind":"guides","slug":"etat-lieux-entree","title":"État des lieux : décrire maintenant pour éviter le litige","themeId":"logement","categoryId":"argent-consommation","description":"Observer chaque pièce et conserver un document réellement précis.","intro":"La règle d’or : décrivez les défauts dans l’état des lieux, plutôt que compter sur une promesse orale.","sections":[{"title":"Prendre le temps de constater","paragraphs":["Pour un bail d’habitation principale, faites le tour du logement avec le bailleur ou son représentant, dans de bonnes conditions d’éclairage. Notez l’état des équipements, les traces, les clés et les relevés utiles. Des photos peuvent compléter une description précise."]},{"title":"Relire avant de signer","paragraphs":["Demandez la correction des formulations qui ne correspondent pas à vos constatations. Conservez votre exemplaire dès la signature, y compris lorsque le document est électronique. Les deux états des lieux doivent permettre une comparaison lors du départ."]},{"title":"Signaler un oubli rapidement","paragraphs":["Le locataire peut demander un complément dans les dix jours calendaires suivant l’état des lieux ; pour le chauffage, durant le premier mois de chauffe. Adressez une demande traçable. En cas de refus, la commission départementale de conciliation peut être saisie."]}],"checklist":["Défauts décrits pièce par pièce.","Exemplaire signé reçu.","Oublis signalés à temps."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Service Public — État des lieux d’entrée","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31270"}],"order":152,"subcategory":"","homeRank":0,"tagSlugs":["logement"]}','{"kind":"guides","slug":"etat-lieux-entree","title":"État des lieux : décrire maintenant pour éviter le litige","themeId":"logement","categoryId":"argent-consommation","description":"Observer chaque pièce et conserver un document réellement précis.","intro":"La règle d’or : décrivez les défauts dans l’état des lieux, plutôt que compter sur une promesse orale.","sections":[{"title":"Prendre le temps de constater","paragraphs":["Pour un bail d’habitation principale, faites le tour du logement avec le bailleur ou son représentant, dans de bonnes conditions d’éclairage. Notez l’état des équipements, les traces, les clés et les relevés utiles. Des photos peuvent compléter une description précise."]},{"title":"Relire avant de signer","paragraphs":["Demandez la correction des formulations qui ne correspondent pas à vos constatations. Conservez votre exemplaire dès la signature, y compris lorsque le document est électronique. Les deux états des lieux doivent permettre une comparaison lors du départ."]},{"title":"Signaler un oubli rapidement","paragraphs":["Le locataire peut demander un complément dans les dix jours calendaires suivant l’état des lieux ; pour le chauffage, durant le premier mois de chauffe. Adressez une demande traçable. En cas de refus, la commission départementale de conciliation peut être saisie."]}],"checklist":["Défauts décrits pièce par pièce.","Exemplaire signé reçu.","Oublis signalés à temps."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Service Public — État des lieux d’entrée","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31270"}],"order":152,"subcategory":"","homeRank":0,"tagSlugs":["logement"]}',1,'2026-10-01T06:41:56.605Z','migration');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/guides/etat-lieux-entree','guides/etat-lieux-entree',1,'{"kind":"guides","slug":"etat-lieux-entree","title":"État des lieux : décrire maintenant pour éviter le litige","themeId":"logement","categoryId":"argent-consommation","description":"Observer chaque pièce et conserver un document réellement précis.","intro":"La règle d’or : décrivez les défauts dans l’état des lieux, plutôt que compter sur une promesse orale.","sections":[{"title":"Prendre le temps de constater","paragraphs":["Pour un bail d’habitation principale, faites le tour du logement avec le bailleur ou son représentant, dans de bonnes conditions d’éclairage. Notez l’état des équipements, les traces, les clés et les relevés utiles. Des photos peuvent compléter une description précise."]},{"title":"Relire avant de signer","paragraphs":["Demandez la correction des formulations qui ne correspondent pas à vos constatations. Conservez votre exemplaire dès la signature, y compris lorsque le document est électronique. Les deux états des lieux doivent permettre une comparaison lors du départ."]},{"title":"Signaler un oubli rapidement","paragraphs":["Le locataire peut demander un complément dans les dix jours calendaires suivant l’état des lieux ; pour le chauffage, durant le premier mois de chauffe. Adressez une demande traçable. En cas de refus, la commission départementale de conciliation peut être saisie."]}],"checklist":["Défauts décrits pièce par pièce.","Exemplaire signé reçu.","Oublis signalés à temps."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Service Public — État des lieux d’entrée","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31270"}],"order":152,"subcategory":"","homeRank":0,"tagSlugs":["logement"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/depot-garantie-restitution','{"kind":"guides","slug":"depot-garantie-restitution","title":"Dépôt de garantie : vérifier le délai et les retenues","themeId":"logement","categoryId":"argent-consommation","description":"Préparer la restitution et demander les justificatifs des sommes déduites.","intro":"La règle d’or : gardez la preuve de remise des clés et transmettez votre nouvelle adresse.","sections":[{"title":"Repérer le délai applicable","paragraphs":["Pour une location principale vide ou meublée soumise aux règles correspondantes, la restitution intervient en principe sous un mois si les états des lieux concordent, deux mois sinon. Le point de départ est la remise des clés, pas simplement le déménagement."]},{"title":"Examiner les retenues","paragraphs":["Comparez les états des lieux et demandez les justificatifs : devis, factures ou impayés documentés. Une provision particulière peut subsister pour les charges de copropriété. Une somme retenue n’est pas justifiée par sa seule présence sur un décompte."]},{"title":"Réclamer sans confondre loyer et dépôt","paragraphs":["Ne déduisez pas le dépôt du dernier loyer. Si la restitution tarde, adressez une mise en demeure ; une majoration peut être due sous conditions. En cas de désaccord persistant, vérifiez la démarche amiable préalable adaptée au montant du litige."]}],"checklist":["Remise des clés prouvée.","Nouvelle adresse transmise.","Retenues et délai examinés."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Service Public — Dépôt de garantie","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31269"}],"order":153,"subcategory":"","homeRank":0,"tagSlugs":["logement","recours"]}','{"kind":"guides","slug":"depot-garantie-restitution","title":"Dépôt de garantie : vérifier le délai et les retenues","themeId":"logement","categoryId":"argent-consommation","description":"Préparer la restitution et demander les justificatifs des sommes déduites.","intro":"La règle d’or : gardez la preuve de remise des clés et transmettez votre nouvelle adresse.","sections":[{"title":"Repérer le délai applicable","paragraphs":["Pour une location principale vide ou meublée soumise aux règles correspondantes, la restitution intervient en principe sous un mois si les états des lieux concordent, deux mois sinon. Le point de départ est la remise des clés, pas simplement le déménagement."]},{"title":"Examiner les retenues","paragraphs":["Comparez les états des lieux et demandez les justificatifs : devis, factures ou impayés documentés. Une provision particulière peut subsister pour les charges de copropriété. Une somme retenue n’est pas justifiée par sa seule présence sur un décompte."]},{"title":"Réclamer sans confondre loyer et dépôt","paragraphs":["Ne déduisez pas le dépôt du dernier loyer. Si la restitution tarde, adressez une mise en demeure ; une majoration peut être due sous conditions. En cas de désaccord persistant, vérifiez la démarche amiable préalable adaptée au montant du litige."]}],"checklist":["Remise des clés prouvée.","Nouvelle adresse transmise.","Retenues et délai examinés."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Service Public — Dépôt de garantie","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31269"}],"order":153,"subcategory":"","homeRank":0,"tagSlugs":["logement","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
