INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/facture-energie-contester','{"kind":"guides","slug":"facture-energie-contester","title":"Facture d’énergie contestée : construire une réclamation","themeId":"logement","categoryId":"argent-consommation","description":"Identifier le problème et garder une trace avant la médiation.","intro":"La règle d’or : transformez votre contestation en une demande écrite, datée et accompagnée de pièces.","sections":[{"title":"Identifier ce qui pose problème","paragraphs":["Rassemblez contrat, facture et éléments de consommation. Décrivez l’anomalie : prix appliqué, estimation, période ou prestation. Pour une facture ou un contrat de fourniture, contactez le fournisseur ; pour un problème de réseau, l’interlocuteur peut être différent."]},{"title":"Écrire au service concerné","paragraphs":["Exposez les faits, les références client et la correction attendue. Utilisez un courrier, un courriel ou le formulaire de votre espace client. Gardez une copie de l’envoi et des réponses. Une succession d’appels seuls rend le dossier difficile à reconstituer."]},{"title":"Passer à la médiation si nécessaire","paragraphs":["Après deux mois sans solution satisfaisante à votre réclamation écrite, vérifiez les conditions de saisine du médiateur national de l’énergie. La réclamation préalable est indispensable. La fiche officielle détaille les interlocuteurs selon le type de contrat et de difficulté."]}],"checklist":["Anomalie décrite.","Pièces regroupées.","Date de réclamation conservée."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Énergie-Info — Réclamation sur un contrat ou une facture","url":"https://www.energie-info.fr/fiche_pratique/jai-une-reclamation-concernant-mon-fournisseur-ou-le-gestionnaire-de-reseau/"}],"order":154,"subcategory":"","homeRank":0,"tagSlugs":["logement"]}','{"kind":"guides","slug":"facture-energie-contester","title":"Facture d’énergie contestée : construire une réclamation","themeId":"logement","categoryId":"argent-consommation","description":"Identifier le problème et garder une trace avant la médiation.","intro":"La règle d’or : transformez votre contestation en une demande écrite, datée et accompagnée de pièces.","sections":[{"title":"Identifier ce qui pose problème","paragraphs":["Rassemblez contrat, facture et éléments de consommation. Décrivez l’anomalie : prix appliqué, estimation, période ou prestation. Pour une facture ou un contrat de fourniture, contactez le fournisseur ; pour un problème de réseau, l’interlocuteur peut être différent."]},{"title":"Écrire au service concerné","paragraphs":["Exposez les faits, les références client et la correction attendue. Utilisez un courrier, un courriel ou le formulaire de votre espace client. Gardez une copie de l’envoi et des réponses. Une succession d’appels seuls rend le dossier difficile à reconstituer."]},{"title":"Passer à la médiation si nécessaire","paragraphs":["Après deux mois sans solution satisfaisante à votre réclamation écrite, vérifiez les conditions de saisine du médiateur national de l’énergie. La réclamation préalable est indispensable. La fiche officielle détaille les interlocuteurs selon le type de contrat et de difficulté."]}],"checklist":["Anomalie décrite.","Pièces regroupées.","Date de réclamation conservée."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Énergie-Info — Réclamation sur un contrat ou une facture","url":"https://www.energie-info.fr/fiche_pratique/jai-une-reclamation-concernant-mon-fournisseur-ou-le-gestionnaire-de-reseau/"}],"order":154,"subcategory":"","homeRank":0,"tagSlugs":["logement"]}',1,'2026-10-01T06:41:56.605Z','migration');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/guides/facture-energie-contester','guides/facture-energie-contester',1,'{"kind":"guides","slug":"facture-energie-contester","title":"Facture d’énergie contestée : construire une réclamation","themeId":"logement","categoryId":"argent-consommation","description":"Identifier le problème et garder une trace avant la médiation.","intro":"La règle d’or : transformez votre contestation en une demande écrite, datée et accompagnée de pièces.","sections":[{"title":"Identifier ce qui pose problème","paragraphs":["Rassemblez contrat, facture et éléments de consommation. Décrivez l’anomalie : prix appliqué, estimation, période ou prestation. Pour une facture ou un contrat de fourniture, contactez le fournisseur ; pour un problème de réseau, l’interlocuteur peut être différent."]},{"title":"Écrire au service concerné","paragraphs":["Exposez les faits, les références client et la correction attendue. Utilisez un courrier, un courriel ou le formulaire de votre espace client. Gardez une copie de l’envoi et des réponses. Une succession d’appels seuls rend le dossier difficile à reconstituer."]},{"title":"Passer à la médiation si nécessaire","paragraphs":["Après deux mois sans solution satisfaisante à votre réclamation écrite, vérifiez les conditions de saisine du médiateur national de l’énergie. La réclamation préalable est indispensable. La fiche officielle détaille les interlocuteurs selon le type de contrat et de difficulté."]}],"checklist":["Anomalie décrite.","Pièces regroupées.","Date de réclamation conservée."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Énergie-Info — Réclamation sur un contrat ou une facture","url":"https://www.energie-info.fr/fiche_pratique/jai-une-reclamation-concernant-mon-fournisseur-ou-le-gestionnaire-de-reseau/"}],"order":154,"subcategory":"","homeRank":0,"tagSlugs":["logement"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/depannage-domicile-urgence','{"kind":"guides","slug":"depannage-domicile-urgence","title":"Dépannage à domicile : garder la main malgré l’urgence","themeId":"travaux","categoryId":"argent-consommation","description":"Faire préciser le prix et limiter l’intervention au besoin réel.","intro":"La règle d’or : l’urgence ne dispense pas de comprendre et d’accepter par écrit l’intervention.","sections":[{"title":"Avant le déplacement","paragraphs":["Demandez les frais de déplacement, les tarifs horaires ou forfaitaires, les majorations et le coût éventuel du devis. Si la situation le permet, comparez plusieurs professionnels. Ne choisissez pas uniquement sur une publicité qui imite un document officiel."]},{"title":"Avant le premier geste","paragraphs":["Pour les prestations de dépannage concernées, un contrat écrit est requis dès le premier euro. Faites préciser les pièces, la main-d’œuvre et le total. Distinguez la réparation indispensable des travaux supplémentaires qui peuvent attendre une comparaison."]},{"title":"Si le prix ou la prestation change","paragraphs":["Demandez une explication et un document correspondant avant d’accepter. Conservez contrat et facture. N’imaginez pas qu’un délai de rétractation annule automatiquement une réparation urgente : des exceptions existent. Signalez les pratiques douteuses via SignalConso."]}],"checklist":["Tarifs annoncés.","Intervention écrite comprise.","Travaux supplémentaires examinés séparément."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"DGCCRF — Choisir un professionnel pour un dépannage","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/plomberie-serrurerie-chauffage-choisir-le-bon-professionnel-pour-un-depannage-domicile"}],"order":155,"subcategory":"","homeRank":0,"tagSlugs":["travaux"]}','{"kind":"guides","slug":"depannage-domicile-urgence","title":"Dépannage à domicile : garder la main malgré l’urgence","themeId":"travaux","categoryId":"argent-consommation","description":"Faire préciser le prix et limiter l’intervention au besoin réel.","intro":"La règle d’or : l’urgence ne dispense pas de comprendre et d’accepter par écrit l’intervention.","sections":[{"title":"Avant le déplacement","paragraphs":["Demandez les frais de déplacement, les tarifs horaires ou forfaitaires, les majorations et le coût éventuel du devis. Si la situation le permet, comparez plusieurs professionnels. Ne choisissez pas uniquement sur une publicité qui imite un document officiel."]},{"title":"Avant le premier geste","paragraphs":["Pour les prestations de dépannage concernées, un contrat écrit est requis dès le premier euro. Faites préciser les pièces, la main-d’œuvre et le total. Distinguez la réparation indispensable des travaux supplémentaires qui peuvent attendre une comparaison."]},{"title":"Si le prix ou la prestation change","paragraphs":["Demandez une explication et un document correspondant avant d’accepter. Conservez contrat et facture. N’imaginez pas qu’un délai de rétractation annule automatiquement une réparation urgente : des exceptions existent. Signalez les pratiques douteuses via SignalConso."]}],"checklist":["Tarifs annoncés.","Intervention écrite comprise.","Travaux supplémentaires examinés séparément."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"DGCCRF — Choisir un professionnel pour un dépannage","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/plomberie-serrurerie-chauffage-choisir-le-bon-professionnel-pour-un-depannage-domicile"}],"order":155,"subcategory":"","homeRank":0,"tagSlugs":["travaux"]}',1,'2026-10-01T06:41:56.605Z','migration');
