INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/location-voiture-etat','{"kind":"guides","slug":"location-voiture-etat","title":"Voiture de location : documenter le départ et le retour","themeId":"tourisme","categoryId":"argent-consommation","description":"Comparer les conditions et faire noter les dommages existants.","intro":"La règle d’or : faites constater l’état du véhicule avec le loueur avant de partir et lors du retour.","sections":[{"title":"Lire le coût complet","paragraphs":["Comparez kilométrage, carburant, dépôt de garantie, moyens de paiement acceptés et conditions de restitution. Vérifiez les assurances, exclusions et franchises : une option ne couvre pas nécessairement tous les dommages."]},{"title":"Inspecter avant de rouler","paragraphs":["Faites inscrire les rayures, chocs et autres défauts sur la fiche, sur tous les exemplaires. Relisez le document avant signature et conservez-le. Des photographies complètent utilement ce constat, sans remplacer un état contradictoire."]},{"title":"Organiser la restitution","paragraphs":["Prévoyez les horaires permettant un contrôle commun. Faites préciser les modalités si le retour se fait hors ouverture. Gardez les documents de retour et les justificatifs de carburant. En cas de facturation contestée, rapprochez les défauts invoqués de l’état signé au départ."]}],"checklist":["Franchise et exclusions lues.","Défauts inscrits au départ.","Restitution documentée."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"DGCCRF — Location de véhicule","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/location-de-vehicule-la-reglementation-applicable"}],"order":156,"subcategory":"","homeRank":0,"tagSlugs":["tourisme"]}','{"kind":"guides","slug":"location-voiture-etat","title":"Voiture de location : documenter le départ et le retour","themeId":"tourisme","categoryId":"argent-consommation","description":"Comparer les conditions et faire noter les dommages existants.","intro":"La règle d’or : faites constater l’état du véhicule avec le loueur avant de partir et lors du retour.","sections":[{"title":"Lire le coût complet","paragraphs":["Comparez kilométrage, carburant, dépôt de garantie, moyens de paiement acceptés et conditions de restitution. Vérifiez les assurances, exclusions et franchises : une option ne couvre pas nécessairement tous les dommages."]},{"title":"Inspecter avant de rouler","paragraphs":["Faites inscrire les rayures, chocs et autres défauts sur la fiche, sur tous les exemplaires. Relisez le document avant signature et conservez-le. Des photographies complètent utilement ce constat, sans remplacer un état contradictoire."]},{"title":"Organiser la restitution","paragraphs":["Prévoyez les horaires permettant un contrôle commun. Faites préciser les modalités si le retour se fait hors ouverture. Gardez les documents de retour et les justificatifs de carburant. En cas de facturation contestée, rapprochez les défauts invoqués de l’état signé au départ."]}],"checklist":["Franchise et exclusions lues.","Défauts inscrits au départ.","Restitution documentée."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"DGCCRF — Location de véhicule","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/location-de-vehicule-la-reglementation-applicable"}],"order":156,"subcategory":"","homeRank":0,"tagSlugs":["tourisme"]}',1,'2026-10-01T06:41:56.605Z','migration');
