INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/message-suspect-hameconnage','{"kind":"guides","slug":"message-suspect-hameconnage","title":"SMS ou courriel suspect : vérifier sans suivre le lien","themeId":"numerique","categoryId":"cybersecurite","description":"Reconnaître une demande douteuse et réagir après une divulgation.","intro":"La règle d’or : ouvrez vous-même le service officiel pour vérifier le message reçu.","sections":[{"title":"Sortir du parcours imposé","paragraphs":["Un remboursement, un colis ou une menace de fermeture peut servir de prétexte. N’envoyez pas de données sensibles et n’ouvrez pas une pièce jointe inattendue. Contactez l’organisme par une adresse connue, indépendante du message."]},{"title":"Si vous avez transmis un secret","paragraphs":["Changez immédiatement le mot de passe sur le vrai service, puis sur les autres comptes où il était réutilisé. Si des informations de paiement ont été communiquées ou des débits frauduleux constatés, faites opposition auprès de votre banque."]},{"title":"Garder les preuves","paragraphs":["Conservez le message, l’adresse du site et les informations sur ce que vous avez saisi. En cas d’usurpation ou d’opérations frauduleuses, déposez plainte. Un message bien rédigé peut être frauduleux : l’absence de fautes ne suffit pas à lui faire confiance."]}],"checklist":["Service ouvert indépendamment.","Accès compromis sécurisés.","Message conservé pour le signalement."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Hameçonnage","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/hameconnage-phishing/2e844784-f440-418c-8d8e-ed5556bb2376"}],"order":157,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","arnaques"]}','{"kind":"guides","slug":"message-suspect-hameconnage","title":"SMS ou courriel suspect : vérifier sans suivre le lien","themeId":"numerique","categoryId":"cybersecurite","description":"Reconnaître une demande douteuse et réagir après une divulgation.","intro":"La règle d’or : ouvrez vous-même le service officiel pour vérifier le message reçu.","sections":[{"title":"Sortir du parcours imposé","paragraphs":["Un remboursement, un colis ou une menace de fermeture peut servir de prétexte. N’envoyez pas de données sensibles et n’ouvrez pas une pièce jointe inattendue. Contactez l’organisme par une adresse connue, indépendante du message."]},{"title":"Si vous avez transmis un secret","paragraphs":["Changez immédiatement le mot de passe sur le vrai service, puis sur les autres comptes où il était réutilisé. Si des informations de paiement ont été communiquées ou des débits frauduleux constatés, faites opposition auprès de votre banque."]},{"title":"Garder les preuves","paragraphs":["Conservez le message, l’adresse du site et les informations sur ce que vous avez saisi. En cas d’usurpation ou d’opérations frauduleuses, déposez plainte. Un message bien rédigé peut être frauduleux : l’absence de fautes ne suffit pas à lui faire confiance."]}],"checklist":["Service ouvert indépendamment.","Accès compromis sécurisés.","Message conservé pour le signalement."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Hameçonnage","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/hameconnage-phishing/2e844784-f440-418c-8d8e-ed5556bb2376"}],"order":157,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","arnaques"]}',1,'2026-10-01T06:41:56.605Z','migration');
