INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/mots-passe-proteger-comptes','{"kind":"guides","slug":"mots-passe-proteger-comptes","title":"Mots de passe : éviter qu’un compte compromis entraîne les autres","themeId":"numerique","categoryId":"cybersecurite","description":"Organiser des accès distincts et renforcer leur protection.","intro":"La règle d’or : utilisez un mot de passe différent pour chaque service.","sections":[{"title":"Rompre les habitudes de réutilisation","paragraphs":["Commencez par les comptes importants, notamment la messagerie. Choisissez des secrets longs et difficiles à deviner, sans informations personnelles évidentes. Un même mot de passe légèrement modifié reste une mauvaise habitude."]},{"title":"S’aider d’un gestionnaire","paragraphs":["Un gestionnaire permet de conserver des mots de passe distincts dans un coffre chiffré. Protégez soigneusement son accès principal. Ne saisissez pas vos véritables mots de passe dans un outil inconnu censé tester leur solidité."]},{"title":"Ajouter une seconde protection","paragraphs":["Activez la double authentification lorsque le service la propose. Examinez les alertes de connexion inhabituelle. Si un secret a été divulgué, remplacez-le sur tous les services concernés ; changer seulement le compte où le problème a été remarqué laisse les autres exposés."]}],"checklist":["Secrets distincts.","Coffre protégé.","Double authentification activée."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"CNIL — Conseils pour les mots de passe","url":"https://www.cnil.fr/fr/les-conseils-de-la-cnil-pour-un-bon-mot-de-passe"}],"order":158,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite"]}','{"kind":"guides","slug":"mots-passe-proteger-comptes","title":"Mots de passe : éviter qu’un compte compromis entraîne les autres","themeId":"numerique","categoryId":"cybersecurite","description":"Organiser des accès distincts et renforcer leur protection.","intro":"La règle d’or : utilisez un mot de passe différent pour chaque service.","sections":[{"title":"Rompre les habitudes de réutilisation","paragraphs":["Commencez par les comptes importants, notamment la messagerie. Choisissez des secrets longs et difficiles à deviner, sans informations personnelles évidentes. Un même mot de passe légèrement modifié reste une mauvaise habitude."]},{"title":"S’aider d’un gestionnaire","paragraphs":["Un gestionnaire permet de conserver des mots de passe distincts dans un coffre chiffré. Protégez soigneusement son accès principal. Ne saisissez pas vos véritables mots de passe dans un outil inconnu censé tester leur solidité."]},{"title":"Ajouter une seconde protection","paragraphs":["Activez la double authentification lorsque le service la propose. Examinez les alertes de connexion inhabituelle. Si un secret a été divulgué, remplacez-le sur tous les services concernés ; changer seulement le compte où le problème a été remarqué laisse les autres exposés."]}],"checklist":["Secrets distincts.","Coffre protégé.","Double authentification activée."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"CNIL — Conseils pour les mots de passe","url":"https://www.cnil.fr/fr/les-conseils-de-la-cnil-pour-un-bon-mot-de-passe"}],"order":158,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite"]}',1,'2026-10-01T06:41:56.605Z','migration');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/guides/mots-passe-proteger-comptes','guides/mots-passe-proteger-comptes',1,'{"kind":"guides","slug":"mots-passe-proteger-comptes","title":"Mots de passe : éviter qu’un compte compromis entraîne les autres","themeId":"numerique","categoryId":"cybersecurite","description":"Organiser des accès distincts et renforcer leur protection.","intro":"La règle d’or : utilisez un mot de passe différent pour chaque service.","sections":[{"title":"Rompre les habitudes de réutilisation","paragraphs":["Commencez par les comptes importants, notamment la messagerie. Choisissez des secrets longs et difficiles à deviner, sans informations personnelles évidentes. Un même mot de passe légèrement modifié reste une mauvaise habitude."]},{"title":"S’aider d’un gestionnaire","paragraphs":["Un gestionnaire permet de conserver des mots de passe distincts dans un coffre chiffré. Protégez soigneusement son accès principal. Ne saisissez pas vos véritables mots de passe dans un outil inconnu censé tester leur solidité."]},{"title":"Ajouter une seconde protection","paragraphs":["Activez la double authentification lorsque le service la propose. Examinez les alertes de connexion inhabituelle. Si un secret a été divulgué, remplacez-le sur tous les services concernés ; changer seulement le compte où le problème a été remarqué laisse les autres exposés."]}],"checklist":["Secrets distincts.","Coffre protégé.","Double authentification activée."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"CNIL — Conseils pour les mots de passe","url":"https://www.cnil.fr/fr/les-conseils-de-la-cnil-pour-un-bon-mot-de-passe"}],"order":158,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/boite-mail-piratee','{"kind":"guides","slug":"boite-mail-piratee","title":"Boîte mail piratée : reprendre le contrôle durablement","themeId":"numerique","categoryId":"cybersecurite","description":"Sécuriser les accès et vérifier ce que l’intrus a modifié.","intro":"La règle d’or : changer le mot de passe ne suffit pas toujours ; vérifiez aussi les sessions et les redirections.","sections":[{"title":"Récupérer l’accès officiel","paragraphs":["Utilisez la procédure du fournisseur de messagerie si vous ne pouvez plus vous connecter. Remplacez le mot de passe par un secret unique et activez la double authentification. Changez aussi les mots de passe réutilisés ailleurs."]},{"title":"Vérifier les réglages","paragraphs":["Examinez les connexions actives et les règles de transfert ou de filtrage. Conservez les preuves d’activité inconnue avant de déconnecter les sessions suspectes. Une redirection malveillante peut continuer à transmettre vos messages après le changement de mot de passe."]},{"title":"Limiter les conséquences","paragraphs":["Prévenez vos contacts si des messages frauduleux ont été envoyés. Alertez votre banque en cas de risque financier et surveillez vos comptes. Conservez les éléments nécessaires à une plainte. Ne payez pas un inconnu qui promet de récupérer votre messagerie."]}],"checklist":["Mot de passe unique.","Sessions et transferts contrôlés.","Contacts concernés avertis."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Piratage d’une boîte mail","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/actualites/que-faire-en-cas-de-piratage-de-boite-mail"}],"order":159,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles"]}','{"kind":"guides","slug":"boite-mail-piratee","title":"Boîte mail piratée : reprendre le contrôle durablement","themeId":"numerique","categoryId":"cybersecurite","description":"Sécuriser les accès et vérifier ce que l’intrus a modifié.","intro":"La règle d’or : changer le mot de passe ne suffit pas toujours ; vérifiez aussi les sessions et les redirections.","sections":[{"title":"Récupérer l’accès officiel","paragraphs":["Utilisez la procédure du fournisseur de messagerie si vous ne pouvez plus vous connecter. Remplacez le mot de passe par un secret unique et activez la double authentification. Changez aussi les mots de passe réutilisés ailleurs."]},{"title":"Vérifier les réglages","paragraphs":["Examinez les connexions actives et les règles de transfert ou de filtrage. Conservez les preuves d’activité inconnue avant de déconnecter les sessions suspectes. Une redirection malveillante peut continuer à transmettre vos messages après le changement de mot de passe."]},{"title":"Limiter les conséquences","paragraphs":["Prévenez vos contacts si des messages frauduleux ont été envoyés. Alertez votre banque en cas de risque financier et surveillez vos comptes. Conservez les éléments nécessaires à une plainte. Ne payez pas un inconnu qui promet de récupérer votre messagerie."]}],"checklist":["Mot de passe unique.","Sessions et transferts contrôlés.","Contacts concernés avertis."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Piratage d’une boîte mail","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/actualites/que-faire-en-cas-de-piratage-de-boite-mail"}],"order":159,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles"]}',1,'2026-10-01T06:41:56.605Z','migration');
