INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/sauvegarder-documents','{"kind":"guides","slug":"sauvegarder-documents","title":"Sauvegardes : vérifier que vos documents sont récupérables","themeId":"numerique","categoryId":"cybersecurite","description":"Préparer une copie utile avant une panne, une perte ou une attaque.","intro":"La règle d’or : une sauvegarde doit pouvoir être restaurée, pas seulement sembler terminée.","sections":[{"title":"Choisir ce qui compte","paragraphs":["Listez les appareils et les documents irremplaçables : photos, dossiers, justificatifs ou travaux. Choisissez une solution adaptée au volume et à la sensibilité des données. Vérifiez que les fichiers importants sont réellement inclus."]},{"title":"Prévoir une copie régulière","paragraphs":["Planifiez les sauvegardes et contrôlez leur exécution. Déconnectez un support externe après utilisation et protégez-le contre le vol, la perte et les dégradations. Une copie exposée au même incident que l’original ne suffit pas."]},{"title":"Tester avant d’en avoir besoin","paragraphs":["Restaurez quelques fichiers dans un emplacement distinct et ouvrez-les. Vérifiez le support et les logiciels nécessaires à leur lecture. Notez les étapes de récupération : le jour d’une panne n’est pas le meilleur moment pour découvrir comment fonctionne votre dispositif."]}],"checklist":["Documents prioritaires inclus.","Copie protégée.","Restauration réellement testée."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Mémo sur les sauvegardes","url":"https://www.cybermalveillance.gouv.fr/medias/2020/03/memo-sauvegardes.pdf"}],"order":160,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite"]}','{"kind":"guides","slug":"sauvegarder-documents","title":"Sauvegardes : vérifier que vos documents sont récupérables","themeId":"numerique","categoryId":"cybersecurite","description":"Préparer une copie utile avant une panne, une perte ou une attaque.","intro":"La règle d’or : une sauvegarde doit pouvoir être restaurée, pas seulement sembler terminée.","sections":[{"title":"Choisir ce qui compte","paragraphs":["Listez les appareils et les documents irremplaçables : photos, dossiers, justificatifs ou travaux. Choisissez une solution adaptée au volume et à la sensibilité des données. Vérifiez que les fichiers importants sont réellement inclus."]},{"title":"Prévoir une copie régulière","paragraphs":["Planifiez les sauvegardes et contrôlez leur exécution. Déconnectez un support externe après utilisation et protégez-le contre le vol, la perte et les dégradations. Une copie exposée au même incident que l’original ne suffit pas."]},{"title":"Tester avant d’en avoir besoin","paragraphs":["Restaurez quelques fichiers dans un emplacement distinct et ouvrez-les. Vérifiez le support et les logiciels nécessaires à leur lecture. Notez les étapes de récupération : le jour d’une panne n’est pas le meilleur moment pour découvrir comment fonctionne votre dispositif."]}],"checklist":["Documents prioritaires inclus.","Copie protégée.","Restauration réellement testée."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Mémo sur les sauvegardes","url":"https://www.cybermalveillance.gouv.fr/medias/2020/03/memo-sauvegardes.pdf"}],"order":160,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite"]}',1,'2026-10-01T06:41:56.605Z','migration');
