INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/usurpation-identite-reagir','{"kind":"guides","slug":"usurpation-identite-reagir","title":"Usurpation d’identité : documenter et alerter","themeId":"numerique","categoryId":"cybersecurite","description":"Réagir à des démarches faites en votre nom et protéger vos justificatifs.","intro":"La règle d’or : conservez les preuves et contactez directement chaque organisme concerné.","sections":[{"title":"Identifier les faits","paragraphs":["Archivez les courriers, contrats inconnus, adresses de profils et captures d’écran. Distinguez une simple exposition de données d’un usage frauduleux constaté. Établissez une chronologie des démarches dont vous n’êtes pas l’auteur."]},{"title":"Signaler et déposer plainte","paragraphs":["Avertissez les services concernés ainsi que vos établissements financiers. Déposez plainte pour les faits d’usurpation et gardez les copies utiles à vos contestations. Si des documents d’identité ont été utilisés, renseignez-vous sur leur annulation et leur renouvellement."]},{"title":"Limiter les réutilisations","paragraphs":["Avant de transmettre un justificatif, vérifiez le destinataire et ne fournissez que le nécessaire. Marquez les copies avec le destinataire, la date et le motif. Le filigrane réduit le risque de détournement, sans rendre une transmission à un inconnu sûre."]}],"checklist":["Faits et preuves classés.","Organismes prévenus.","Copies de justificatifs contextualisées."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Usurpation d’identité","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/usurpation-identite-que-faire"}],"order":161,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles","recours"]}','{"kind":"guides","slug":"usurpation-identite-reagir","title":"Usurpation d’identité : documenter et alerter","themeId":"numerique","categoryId":"cybersecurite","description":"Réagir à des démarches faites en votre nom et protéger vos justificatifs.","intro":"La règle d’or : conservez les preuves et contactez directement chaque organisme concerné.","sections":[{"title":"Identifier les faits","paragraphs":["Archivez les courriers, contrats inconnus, adresses de profils et captures d’écran. Distinguez une simple exposition de données d’un usage frauduleux constaté. Établissez une chronologie des démarches dont vous n’êtes pas l’auteur."]},{"title":"Signaler et déposer plainte","paragraphs":["Avertissez les services concernés ainsi que vos établissements financiers. Déposez plainte pour les faits d’usurpation et gardez les copies utiles à vos contestations. Si des documents d’identité ont été utilisés, renseignez-vous sur leur annulation et leur renouvellement."]},{"title":"Limiter les réutilisations","paragraphs":["Avant de transmettre un justificatif, vérifiez le destinataire et ne fournissez que le nécessaire. Marquez les copies avec le destinataire, la date et le motif. Le filigrane réduit le risque de détournement, sans rendre une transmission à un inconnu sûre."]}],"checklist":["Faits et preuves classés.","Organismes prévenus.","Copies de justificatifs contextualisées."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Cybermalveillance.gouv.fr — Usurpation d’identité","url":"https://www.cybermalveillance.gouv.fr/tous-nos-contenus/fiches-reflexes/usurpation-identite-que-faire"}],"order":161,"subcategory":"","homeRank":0,"tagSlugs":["cybersecurite","donnees-personnelles","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
