INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/ia-verifier-proteger','{"kind":"guides","slug":"ia-verifier-proteger","title":"IA générative : vérifier la réponse et protéger ses données","themeId":"ia","categoryId":"ia-numerique","description":"Utiliser une aide à la rédaction sans lui déléguer son jugement.","intro":"La règle d’or : une réponse convaincante doit encore être vérifiée avant d’être utilisée.","sections":[{"title":"Donner un objectif clair","paragraphs":["Précisez le public, le résultat attendu et les contraintes utiles. Demandez une reformulation si la réponse est vague. Retirez du contexte les informations personnelles ou confidentielles qui ne sont pas nécessaires."]},{"title":"Contrôler les points décisifs","paragraphs":["Vérifiez les dates, chiffres, citations et références dans les documents d’origine. Un lien ou un ton assuré ne prouve pas l’exactitude du contenu. Pour une décision importante, faites examiner les éléments par une personne compétente."]},{"title":"Garder la responsabilité du résultat","paragraphs":["Relisez avant d’envoyer ou de publier. Ne copiez pas un dossier client, médical ou interne dans un service sans avoir vérifié son autorisation et ses conditions de traitement. Utilisez un exemple fictif lorsque les détails réels n’apportent rien."]}],"checklist":["Objectif formulé.","Données inutiles retirées.","Affirmations vérifiées avant usage."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Info.gouv.fr — Bien utiliser les IA génératives","url":"https://www.info.gouv.fr/actualite/ia-generatives-comment-bien-les-utiliser"}],"order":162,"subcategory":"","homeRank":0,"tagSlugs":["donnees-personnelles","ia"]}','{"kind":"guides","slug":"ia-verifier-proteger","title":"IA générative : vérifier la réponse et protéger ses données","themeId":"ia","categoryId":"ia-numerique","description":"Utiliser une aide à la rédaction sans lui déléguer son jugement.","intro":"La règle d’or : une réponse convaincante doit encore être vérifiée avant d’être utilisée.","sections":[{"title":"Donner un objectif clair","paragraphs":["Précisez le public, le résultat attendu et les contraintes utiles. Demandez une reformulation si la réponse est vague. Retirez du contexte les informations personnelles ou confidentielles qui ne sont pas nécessaires."]},{"title":"Contrôler les points décisifs","paragraphs":["Vérifiez les dates, chiffres, citations et références dans les documents d’origine. Un lien ou un ton assuré ne prouve pas l’exactitude du contenu. Pour une décision importante, faites examiner les éléments par une personne compétente."]},{"title":"Garder la responsabilité du résultat","paragraphs":["Relisez avant d’envoyer ou de publier. Ne copiez pas un dossier client, médical ou interne dans un service sans avoir vérifié son autorisation et ses conditions de traitement. Utilisez un exemple fictif lorsque les détails réels n’apportent rien."]}],"checklist":["Objectif formulé.","Données inutiles retirées.","Affirmations vérifiées avant usage."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Info.gouv.fr — Bien utiliser les IA génératives","url":"https://www.info.gouv.fr/actualite/ia-generatives-comment-bien-les-utiliser"}],"order":162,"subcategory":"","homeRank":0,"tagSlugs":["donnees-personnelles","ia"]}',1,'2026-10-01T06:41:56.605Z','migration');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/guides/ia-verifier-proteger','guides/ia-verifier-proteger',1,'{"kind":"guides","slug":"ia-verifier-proteger","title":"IA générative : vérifier la réponse et protéger ses données","themeId":"ia","categoryId":"ia-numerique","description":"Utiliser une aide à la rédaction sans lui déléguer son jugement.","intro":"La règle d’or : une réponse convaincante doit encore être vérifiée avant d’être utilisée.","sections":[{"title":"Donner un objectif clair","paragraphs":["Précisez le public, le résultat attendu et les contraintes utiles. Demandez une reformulation si la réponse est vague. Retirez du contexte les informations personnelles ou confidentielles qui ne sont pas nécessaires."]},{"title":"Contrôler les points décisifs","paragraphs":["Vérifiez les dates, chiffres, citations et références dans les documents d’origine. Un lien ou un ton assuré ne prouve pas l’exactitude du contenu. Pour une décision importante, faites examiner les éléments par une personne compétente."]},{"title":"Garder la responsabilité du résultat","paragraphs":["Relisez avant d’envoyer ou de publier. Ne copiez pas un dossier client, médical ou interne dans un service sans avoir vérifié son autorisation et ses conditions de traitement. Utilisez un exemple fictif lorsque les détails réels n’apportent rien."]}],"checklist":["Objectif formulé.","Données inutiles retirées.","Affirmations vérifiées avant usage."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Info.gouv.fr — Bien utiliser les IA génératives","url":"https://www.info.gouv.fr/actualite/ia-generatives-comment-bien-les-utiliser"}],"order":162,"subcategory":"","homeRank":0,"tagSlugs":["donnees-personnelles","ia"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/teletravail-bons-reperes','{"kind":"guides","slug":"teletravail-bons-reperes","title":"Télétravail : organiser sa journée et son poste","themeId":"travail","categoryId":"management-travail","description":"Réduire l’inconfort et préserver les échanges avec l’équipe.","intro":"La règle d’or : préparez autant l’organisation du travail que l’installation de l’ordinateur.","sections":[{"title":"Aménager avec les moyens disponibles","paragraphs":["Choisissez un espace adapté et limitez les reflets sur l’écran. Pour un usage prolongé du portable, un écran ou support associé à un clavier et une souris séparés aide à mieux installer le poste. Recherchez un appui confortable des pieds et du dos."]},{"title":"Clarifier le fonctionnement collectif","paragraphs":["Convenez des priorités, des échanges et des moyens d’obtenir de l’aide. Signalez les difficultés d’accès aux outils et les charges mal réparties. La disponibilité permanente ne remplace pas une organisation explicite."]},{"title":"Prévoir des changements de posture","paragraphs":["Intégrez des moments permettant de quitter l’écran et de bouger. Maintenez les contacts avec l’équipe et des limites de disponibilité. Si l’installation ou l’organisation crée des difficultés persistantes, échangez avec l’employeur et les interlocuteurs de prévention."]}],"checklist":["Poste ajusté.","Priorités et échanges clarifiés.","Pauses et déconnexion prévues."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"INRS — Prévenir les risques du télétravail","url":"https://www.inrs.fr/risques/teletravail/prevenir-les-risques"}],"order":163,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}','{"kind":"guides","slug":"teletravail-bons-reperes","title":"Télétravail : organiser sa journée et son poste","themeId":"travail","categoryId":"management-travail","description":"Réduire l’inconfort et préserver les échanges avec l’équipe.","intro":"La règle d’or : préparez autant l’organisation du travail que l’installation de l’ordinateur.","sections":[{"title":"Aménager avec les moyens disponibles","paragraphs":["Choisissez un espace adapté et limitez les reflets sur l’écran. Pour un usage prolongé du portable, un écran ou support associé à un clavier et une souris séparés aide à mieux installer le poste. Recherchez un appui confortable des pieds et du dos."]},{"title":"Clarifier le fonctionnement collectif","paragraphs":["Convenez des priorités, des échanges et des moyens d’obtenir de l’aide. Signalez les difficultés d’accès aux outils et les charges mal réparties. La disponibilité permanente ne remplace pas une organisation explicite."]},{"title":"Prévoir des changements de posture","paragraphs":["Intégrez des moments permettant de quitter l’écran et de bouger. Maintenez les contacts avec l’équipe et des limites de disponibilité. Si l’installation ou l’organisation crée des difficultés persistantes, échangez avec l’employeur et les interlocuteurs de prévention."]}],"checklist":["Poste ajusté.","Priorités et échanges clarifiés.","Pauses et déconnexion prévues."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"INRS — Prévenir les risques du télétravail","url":"https://www.inrs.fr/risques/teletravail/prevenir-les-risques"}],"order":163,"subcategory":"","homeRank":0,"tagSlugs":["travail","decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
