INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/tresorerie-anticiper','{"kind":"guides","slug":"tresorerie-anticiper","title":"Trésorerie : regarder quand l’argent entre et sort","themeId":"projets","categoryId":"entrepreneuriat","description":"Repérer les mois difficiles avant de prendre de nouveaux engagements.","intro":"La règle d’or : une vente prévue n’est pas encore de l’argent disponible.","sections":[{"title":"Placer les flux au bon mois","paragraphs":["Construisez un tableau des encaissements et décaissements attendus. Affectez chaque somme au mois de son paiement effectif prévu, pas seulement à la date de facture. Incluez les charges, taxes, investissements et remboursements concernés."]},{"title":"Suivre le solde cumulé","paragraphs":["Partez de la trésorerie initiale et reportez le solde de chaque mois au suivant. Un résultat annuel favorable peut masquer un manque temporaire. Distinguez les recettes confirmées des hypothèses et examinez les conséquences d’un paiement client retardé."]},{"title":"Agir avant le manque","paragraphs":["Actualisez le tableau avec les montants réels. Si un déficit apparaît, réexaminez le calendrier des dépenses et les ressources disponibles avec votre accompagnateur ou votre comptable. N’engagez pas une dépense sur la seule promesse d’une entrée future."]}],"checklist":["Dates de paiement utilisées.","Solde cumulé suivi.","Hypothèses actualisées."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Bpifrance Création — Plan de trésorerie","url":"https://bpifrance-creation.fr/encyclopedie/previsions-financieres-business-plan/previsions-financieres/plan-tresorerie-projet"}],"order":164,"subcategory":"","homeRank":0,"tagSlugs":["budget","entreprendre"]}','{"kind":"guides","slug":"tresorerie-anticiper","title":"Trésorerie : regarder quand l’argent entre et sort","themeId":"projets","categoryId":"entrepreneuriat","description":"Repérer les mois difficiles avant de prendre de nouveaux engagements.","intro":"La règle d’or : une vente prévue n’est pas encore de l’argent disponible.","sections":[{"title":"Placer les flux au bon mois","paragraphs":["Construisez un tableau des encaissements et décaissements attendus. Affectez chaque somme au mois de son paiement effectif prévu, pas seulement à la date de facture. Incluez les charges, taxes, investissements et remboursements concernés."]},{"title":"Suivre le solde cumulé","paragraphs":["Partez de la trésorerie initiale et reportez le solde de chaque mois au suivant. Un résultat annuel favorable peut masquer un manque temporaire. Distinguez les recettes confirmées des hypothèses et examinez les conséquences d’un paiement client retardé."]},{"title":"Agir avant le manque","paragraphs":["Actualisez le tableau avec les montants réels. Si un déficit apparaît, réexaminez le calendrier des dépenses et les ressources disponibles avec votre accompagnateur ou votre comptable. N’engagez pas une dépense sur la seule promesse d’une entrée future."]}],"checklist":["Dates de paiement utilisées.","Solde cumulé suivi.","Hypothèses actualisées."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"Bpifrance Création — Plan de trésorerie","url":"https://bpifrance-creation.fr/encyclopedie/previsions-financieres-business-plan/previsions-financieres/plan-tresorerie-projet"}],"order":164,"subcategory":"","homeRank":0,"tagSlugs":["budget","entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
