INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/promotions-comparer-prix','{"kind":"guides","slug":"promotions-comparer-prix","title":"Promotions : regarder le prix avant le pourcentage","themeId":"achats","categoryId":"argent-consommation","description":"Distinguer une réduction annoncée d’une comparaison commerciale.","intro":"La règle d’or : comparez ce que vous paierez réellement, pas seulement la taille du rabais.","sections":[{"title":"Comprendre le prix de référence","paragraphs":["Pour les annonces de réduction de prix concernées, le professionnel doit prendre comme référence son prix le plus bas des trente jours précédents. Un pourcentage élevé ne permet donc pas, seul, d’évaluer l’intérêt de l’offre."]},{"title":"Lire la nature de la comparaison","paragraphs":["Un prix conseillé par le fabricant ou pratiqué ailleurs n’est pas la même chose qu’un ancien prix du vendeur. La présentation doit permettre de distinguer comparaison et réduction. Regardez les mentions qui accompagnent le prix barré."]},{"title":"Décider sur le coût utile","paragraphs":["Comparez le même produit, ses caractéristiques et le total à payer. Gardez une capture de l’offre si elle paraît trompeuse. Ne transformez pas une réduction en besoin : un article inutile reste une dépense, même avec une remise affichée."]}],"checklist":["Référence du rabais comprise.","Produit comparable identifié.","Coût final examiné."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"DGCCRF — Règles contre les faux rabais","url":"https://www.economie.gouv.fr/dgccrf/actualites-dgccrf/des-regles-plus-claires-contre-les-faux-rabais"}],"order":165,"subcategory":"","homeRank":0,"tagSlugs":["budget","promotions","achats"]}','{"kind":"guides","slug":"promotions-comparer-prix","title":"Promotions : regarder le prix avant le pourcentage","themeId":"achats","categoryId":"argent-consommation","description":"Distinguer une réduction annoncée d’une comparaison commerciale.","intro":"La règle d’or : comparez ce que vous paierez réellement, pas seulement la taille du rabais.","sections":[{"title":"Comprendre le prix de référence","paragraphs":["Pour les annonces de réduction de prix concernées, le professionnel doit prendre comme référence son prix le plus bas des trente jours précédents. Un pourcentage élevé ne permet donc pas, seul, d’évaluer l’intérêt de l’offre."]},{"title":"Lire la nature de la comparaison","paragraphs":["Un prix conseillé par le fabricant ou pratiqué ailleurs n’est pas la même chose qu’un ancien prix du vendeur. La présentation doit permettre de distinguer comparaison et réduction. Regardez les mentions qui accompagnent le prix barré."]},{"title":"Décider sur le coût utile","paragraphs":["Comparez le même produit, ses caractéristiques et le total à payer. Gardez une capture de l’offre si elle paraît trompeuse. Ne transformez pas une réduction en besoin : un article inutile reste une dépense, même avec une remise affichée."]}],"checklist":["Référence du rabais comprise.","Produit comparable identifié.","Coût final examiné."],"reviewedAt":"2026-09-28","sources":[{"kind":"reference","label":"DGCCRF — Règles contre les faux rabais","url":"https://www.economie.gouv.fr/dgccrf/actualites-dgccrf/des-regles-plus-claires-contre-les-faux-rabais"}],"order":165,"subcategory":"","homeRank":0,"tagSlugs":["budget","promotions","achats"]}',1,'2026-10-01T06:41:56.605Z','migration');
