INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/proprietaire-refuse-travaux','{"kind":"guides","slug":"proprietaire-refuse-travaux","title":"Location : que faire si le propriétaire ne réalise pas les travaux ?","description":"Identifier les réparations dues, formaliser sa demande et choisir le bon recours sans suspendre soi-même le loyer.","categoryId":"argent-consommation","reviewedAt":"2026-09-28","intro":"Un équipement défectueux et une envie de rafraîchir la décoration ne posent pas la même question. Avant de réclamer des travaux, identifiez le problème, sa cause et la personne qui doit intervenir. Ce guide concerne les baux d’habitation en France.","sections":[{"title":"Distinguer entretien, vétusté et défaut du logement","paragraphs":["L’entretien courant et les petites réparations relèvent généralement du locataire. Mais une réparation rendue nécessaire par la vétusté peut incomber au propriétaire, même si elle figure habituellement parmi les réparations locatives. La nature de la panne et son origine comptent donc autant que le nom de l’équipement.","Un simple souhait de décoration ne suffit pas à rendre des travaux obligatoires. En revanche, le bailleur doit respecter ses obligations de réparation et de décence. Comparez votre situation avec les fiches officielles ci-dessous avant d’affirmer qui doit payer."]},{"title":"Décrire le problème et conserver les preuves","paragraphs":["Rassemblez le bail, l’état des lieux, des photos datées et les échanges déjà intervenus. Si un professionnel a constaté une panne, conservez son diagnostic. Présentez une chronologie courte : apparition du problème, signalements et réponses reçues.","Exemple fictif : le chauffage reste défaillant malgré un entretien réalisé. Décrivez les pièces concernées et les interventions effectuées, plutôt que d’envoyer seulement « il faut tout refaire ». Une demande précise aide à identifier les travaux attendus."]},{"title":"Formaliser la demande par une mise en demeure","paragraphs":["Si les démarches amiables n’aboutissent pas et que les travaux incombent au bailleur, adressez une mise en demeure par lettre recommandée avec accusé de réception. Décrivez les désordres, demandez leur traitement et joignez les pièces utiles. Gardez une copie du courrier et la preuve de réception.","Proposez un délai adapté à la situation pour obtenir une réponse et un calendrier. Ce délai demandé ne remplace pas les délais des procédures légales. En cas de danger immédiat, recherchez une aide urgente adaptée sans attendre l’issue des courriers."]},{"title":"Choisir une démarche adaptée au litige","paragraphs":["La fiche Service-Public sur les travaux du bailleur indique qu’après deux mois sans accord ou sans réponse à la mise en demeure, le locataire peut recourir à la commission départementale de conciliation ou à un conciliateur de justice avant de saisir le juge.","La commission intervient gratuitement ; pour un litige sur les réparations, sa saisine est facultative. Une tentative amiable peut néanmoins être exigée avant certaines actions judiciaires. La procédure dépend notamment de la demande et d’un éventuel défaut de décence : faites préciser votre parcours avant de saisir le tribunal. Le juge des contentieux de la protection peut imposer des travaux si les conditions sont réunies."]},{"title":"Ne pas suspendre soi-même le loyer","paragraphs":["Le refus de travaux n’autorise pas, à lui seul, à arrêter les paiements ou à déduire une facture du loyer. Continuez à respecter vos obligations pendant les démarches. Une réduction, une suspension ou une consignation doit reposer sur le cadre légal applicable, notamment une décision du juge ; ne la décidez pas unilatéralement.","Conservez aussi la preuve des conséquences concrètes du problème : pièce inutilisable, dépenses justifiées ou durée des désordres. Une éventuelle indemnisation doit être examinée au regard des faits ; elle n’est pas acquise par la seule annonce d’une demande de dommages-intérêts."]}],"checklist":["J’ai distingué l’entretien courant de la vétusté et des travaux du bailleur.","Mon dossier décrit des faits et contient des justificatifs.","Ma demande écrite précise les travaux attendus.","J’ai conservé le courrier et sa preuve de réception.","Je vérifie le recours approprié et continue à régler le loyer dû."],"sources":[{"kind":"inspiration","label":"Ça peut vous arriver — transcription fournie par le lecteur : travaux du bailleur (0:38–2:51). Épisode précis non identifié ; lien vers l’émission.","url":"https://www.rtl.fr/programmes/ca-peut-vous-arriver"},{"kind":"reference","label":"Service-Public — Travaux à la charge du propriétaire","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31699"},{"kind":"reference","label":"Service-Public — Réparations locatives","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31697"},{"kind":"reference","label":"Service-Public — Dégradations et vétusté","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F21105"},{"kind":"reference","label":"Service-Public — Commission départementale de conciliation","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F1216"},{"kind":"reference","label":"Service-Public — Litiges liés à la location","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31301"}],"order":167,"subcategory":"","homeRank":3,"themeId":"logement","tagSlugs":["logement","travaux","recours"]}','{"kind":"guides","slug":"proprietaire-refuse-travaux","title":"Location : que faire si le propriétaire ne réalise pas les travaux ?","description":"Identifier les réparations dues, formaliser sa demande et choisir le bon recours sans suspendre soi-même le loyer.","categoryId":"argent-consommation","reviewedAt":"2026-09-28","intro":"Un équipement défectueux et une envie de rafraîchir la décoration ne posent pas la même question. Avant de réclamer des travaux, identifiez le problème, sa cause et la personne qui doit intervenir. Ce guide concerne les baux d’habitation en France.","sections":[{"title":"Distinguer entretien, vétusté et défaut du logement","paragraphs":["L’entretien courant et les petites réparations relèvent généralement du locataire. Mais une réparation rendue nécessaire par la vétusté peut incomber au propriétaire, même si elle figure habituellement parmi les réparations locatives. La nature de la panne et son origine comptent donc autant que le nom de l’équipement.","Un simple souhait de décoration ne suffit pas à rendre des travaux obligatoires. En revanche, le bailleur doit respecter ses obligations de réparation et de décence. Comparez votre situation avec les fiches officielles ci-dessous avant d’affirmer qui doit payer."]},{"title":"Décrire le problème et conserver les preuves","paragraphs":["Rassemblez le bail, l’état des lieux, des photos datées et les échanges déjà intervenus. Si un professionnel a constaté une panne, conservez son diagnostic. Présentez une chronologie courte : apparition du problème, signalements et réponses reçues.","Exemple fictif : le chauffage reste défaillant malgré un entretien réalisé. Décrivez les pièces concernées et les interventions effectuées, plutôt que d’envoyer seulement « il faut tout refaire ». Une demande précise aide à identifier les travaux attendus."]},{"title":"Formaliser la demande par une mise en demeure","paragraphs":["Si les démarches amiables n’aboutissent pas et que les travaux incombent au bailleur, adressez une mise en demeure par lettre recommandée avec accusé de réception. Décrivez les désordres, demandez leur traitement et joignez les pièces utiles. Gardez une copie du courrier et la preuve de réception.","Proposez un délai adapté à la situation pour obtenir une réponse et un calendrier. Ce délai demandé ne remplace pas les délais des procédures légales. En cas de danger immédiat, recherchez une aide urgente adaptée sans attendre l’issue des courriers."]},{"title":"Choisir une démarche adaptée au litige","paragraphs":["La fiche Service-Public sur les travaux du bailleur indique qu’après deux mois sans accord ou sans réponse à la mise en demeure, le locataire peut recourir à la commission départementale de conciliation ou à un conciliateur de justice avant de saisir le juge.","La commission intervient gratuitement ; pour un litige sur les réparations, sa saisine est facultative. Une tentative amiable peut néanmoins être exigée avant certaines actions judiciaires. La procédure dépend notamment de la demande et d’un éventuel défaut de décence : faites préciser votre parcours avant de saisir le tribunal. Le juge des contentieux de la protection peut imposer des travaux si les conditions sont réunies."]},{"title":"Ne pas suspendre soi-même le loyer","paragraphs":["Le refus de travaux n’autorise pas, à lui seul, à arrêter les paiements ou à déduire une facture du loyer. Continuez à respecter vos obligations pendant les démarches. Une réduction, une suspension ou une consignation doit reposer sur le cadre légal applicable, notamment une décision du juge ; ne la décidez pas unilatéralement.","Conservez aussi la preuve des conséquences concrètes du problème : pièce inutilisable, dépenses justifiées ou durée des désordres. Une éventuelle indemnisation doit être examinée au regard des faits ; elle n’est pas acquise par la seule annonce d’une demande de dommages-intérêts."]}],"checklist":["J’ai distingué l’entretien courant de la vétusté et des travaux du bailleur.","Mon dossier décrit des faits et contient des justificatifs.","Ma demande écrite précise les travaux attendus.","J’ai conservé le courrier et sa preuve de réception.","Je vérifie le recours approprié et continue à régler le loyer dû."],"sources":[{"kind":"inspiration","label":"Ça peut vous arriver — transcription fournie par le lecteur : travaux du bailleur (0:38–2:51). Épisode précis non identifié ; lien vers l’émission.","url":"https://www.rtl.fr/programmes/ca-peut-vous-arriver"},{"kind":"reference","label":"Service-Public — Travaux à la charge du propriétaire","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31699"},{"kind":"reference","label":"Service-Public — Réparations locatives","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31697"},{"kind":"reference","label":"Service-Public — Dégradations et vétusté","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F21105"},{"kind":"reference","label":"Service-Public — Commission départementale de conciliation","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F1216"},{"kind":"reference","label":"Service-Public — Litiges liés à la location","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31301"}],"order":167,"subcategory":"","homeRank":3,"themeId":"logement","tagSlugs":["logement","travaux","recours"]}',1,'2026-10-01T06:41:56.605Z','migration');
INSERT OR IGNORE INTO revisions(id,content_id,version,snapshot_json,action,actor,created_at) VALUES('initial/guides/proprietaire-refuse-travaux','guides/proprietaire-refuse-travaux',1,'{"kind":"guides","slug":"proprietaire-refuse-travaux","title":"Location : que faire si le propriétaire ne réalise pas les travaux ?","description":"Identifier les réparations dues, formaliser sa demande et choisir le bon recours sans suspendre soi-même le loyer.","categoryId":"argent-consommation","reviewedAt":"2026-09-28","intro":"Un équipement défectueux et une envie de rafraîchir la décoration ne posent pas la même question. Avant de réclamer des travaux, identifiez le problème, sa cause et la personne qui doit intervenir. Ce guide concerne les baux d’habitation en France.","sections":[{"title":"Distinguer entretien, vétusté et défaut du logement","paragraphs":["L’entretien courant et les petites réparations relèvent généralement du locataire. Mais une réparation rendue nécessaire par la vétusté peut incomber au propriétaire, même si elle figure habituellement parmi les réparations locatives. La nature de la panne et son origine comptent donc autant que le nom de l’équipement.","Un simple souhait de décoration ne suffit pas à rendre des travaux obligatoires. En revanche, le bailleur doit respecter ses obligations de réparation et de décence. Comparez votre situation avec les fiches officielles ci-dessous avant d’affirmer qui doit payer."]},{"title":"Décrire le problème et conserver les preuves","paragraphs":["Rassemblez le bail, l’état des lieux, des photos datées et les échanges déjà intervenus. Si un professionnel a constaté une panne, conservez son diagnostic. Présentez une chronologie courte : apparition du problème, signalements et réponses reçues.","Exemple fictif : le chauffage reste défaillant malgré un entretien réalisé. Décrivez les pièces concernées et les interventions effectuées, plutôt que d’envoyer seulement « il faut tout refaire ». Une demande précise aide à identifier les travaux attendus."]},{"title":"Formaliser la demande par une mise en demeure","paragraphs":["Si les démarches amiables n’aboutissent pas et que les travaux incombent au bailleur, adressez une mise en demeure par lettre recommandée avec accusé de réception. Décrivez les désordres, demandez leur traitement et joignez les pièces utiles. Gardez une copie du courrier et la preuve de réception.","Proposez un délai adapté à la situation pour obtenir une réponse et un calendrier. Ce délai demandé ne remplace pas les délais des procédures légales. En cas de danger immédiat, recherchez une aide urgente adaptée sans attendre l’issue des courriers."]},{"title":"Choisir une démarche adaptée au litige","paragraphs":["La fiche Service-Public sur les travaux du bailleur indique qu’après deux mois sans accord ou sans réponse à la mise en demeure, le locataire peut recourir à la commission départementale de conciliation ou à un conciliateur de justice avant de saisir le juge.","La commission intervient gratuitement ; pour un litige sur les réparations, sa saisine est facultative. Une tentative amiable peut néanmoins être exigée avant certaines actions judiciaires. La procédure dépend notamment de la demande et d’un éventuel défaut de décence : faites préciser votre parcours avant de saisir le tribunal. Le juge des contentieux de la protection peut imposer des travaux si les conditions sont réunies."]},{"title":"Ne pas suspendre soi-même le loyer","paragraphs":["Le refus de travaux n’autorise pas, à lui seul, à arrêter les paiements ou à déduire une facture du loyer. Continuez à respecter vos obligations pendant les démarches. Une réduction, une suspension ou une consignation doit reposer sur le cadre légal applicable, notamment une décision du juge ; ne la décidez pas unilatéralement.","Conservez aussi la preuve des conséquences concrètes du problème : pièce inutilisable, dépenses justifiées ou durée des désordres. Une éventuelle indemnisation doit être examinée au regard des faits ; elle n’est pas acquise par la seule annonce d’une demande de dommages-intérêts."]}],"checklist":["J’ai distingué l’entretien courant de la vétusté et des travaux du bailleur.","Mon dossier décrit des faits et contient des justificatifs.","Ma demande écrite précise les travaux attendus.","J’ai conservé le courrier et sa preuve de réception.","Je vérifie le recours approprié et continue à régler le loyer dû."],"sources":[{"kind":"inspiration","label":"Ça peut vous arriver — transcription fournie par le lecteur : travaux du bailleur (0:38–2:51). Épisode précis non identifié ; lien vers l’émission.","url":"https://www.rtl.fr/programmes/ca-peut-vous-arriver"},{"kind":"reference","label":"Service-Public — Travaux à la charge du propriétaire","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31699"},{"kind":"reference","label":"Service-Public — Réparations locatives","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31697"},{"kind":"reference","label":"Service-Public — Dégradations et vétusté","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F21105"},{"kind":"reference","label":"Service-Public — Commission départementale de conciliation","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F1216"},{"kind":"reference","label":"Service-Public — Litiges liés à la location","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F31301"}],"order":167,"subcategory":"","homeRank":3,"themeId":"logement","tagSlugs":["logement","travaux","recours"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/degat-des-eaux-bons-reflexes','{"kind":"guides","slug":"degat-des-eaux-bons-reflexes","title":"Dégât des eaux : agir vite et garder les preuves","description":"Limiter les dommages, prévenir son assurance et préparer un dossier clair sans effacer les preuves.","categoryId":"argent-consommation","reviewedAt":"2026-09-28","intro":"Une fuite demande deux réflexes complémentaires : empêcher les dégâts de s’aggraver et documenter ce qui s’est passé. Ce guide distingue les mesures urgentes de la remise en état, pour agir dans le bon ordre.","sections":[{"title":"Limiter les dégâts sans se mettre en danger","paragraphs":["Si vous pouvez le faire sans risque, fermez l’arrivée d’eau concernée. Si la fuite vient d’ailleurs, prévenez le voisin ou le syndic. Faites réparer la fuite rapidement ; ne manipulez pas d’installation électrique mouillée et sollicitez une intervention adaptée en cas de danger.","La réparation urgente de la fuite est différente de la réfection des peintures ou des sols. Pour cette remise en état, obtenez d’abord l’accord de votre assureur. Gardez les justificatifs des interventions urgentes."]},{"title":"Déclarer rapidement et décrire les faits","paragraphs":["Prévenez votre assureur dès la découverte. Le délai prévu au contrat ne peut en principe être inférieur à cinq jours ouvrés. Vérifiez ses modalités de déclaration. Un constat amiable peut faciliter le dossier, mais il n’est pas obligatoire.","Notez la date, les pièces touchées, les dommages visibles et les démarches entreprises. Distinguez les faits observés de vos suppositions : « de l’eau apparaît au plafond » ne permet pas encore d’affirmer quelle installation fuit. Conservez la confirmation de votre déclaration."]},{"title":"Photographier et conserver les éléments utiles","paragraphs":["Prenez des vues d’ensemble et des détails des dommages, sans vous exposer. Faites une liste des biens touchés et rassemblez les factures disponibles. Avant de jeter un objet endommagé, demandez les consignes de l’assureur ; la conservation des preuves ne doit pas créer de danger.","Exemple fictif : une fuite a détrempé un meuble. Photographiez son emplacement, les zones abîmées et son identification, puis ajoutez sa facture si vous l’avez. Un dossier organisé sera plus facile à examiner qu’une série de photos sans contexte."]},{"title":"Préparer l’expertise sans la présumer obligatoire","paragraphs":["L’expertise n’est pas systématique. Lorsqu’un expert intervient, il examine notamment les causes et les dommages. Préparez vos documents et signalez les éléments qui pourraient être oubliés. Le montant de 1 600 euros évoqué dans la transcription ne doit pas être présenté comme une obligation légale universelle d’expertise.","Si vous contestez ses conclusions, demandez des explications et renseignez-vous sur la contre-expertise. Vérifiez auparavant la prise en charge de ses frais dans votre contrat. Ne confondez pas le coût estimé des réparations et l’indemnité finalement proposée."]},{"title":"Vérifier la garantie mobilisée","paragraphs":["L’origine de l’eau, les exclusions et les franchises comptent : toute entrée d’eau ne garantit pas une indemnisation. Demandez à l’assureur quelle garantie il examine et quels documents il attend.","Une inondation relevant du régime des catastrophes naturelles obéit à des conditions spécifiques, notamment un arrêté de reconnaissance et une assurance ouvrant droit à cette garantie. Pour ce régime, la déclaration doit être faite au plus tard trente jours après la publication de l’arrêté. Une forte pluie ne suffit donc pas, à elle seule, à garantir la prise en charge."]}],"checklist":["La fuite et les dangers immédiats sont pris en charge.","La déclaration est transmise et sa confirmation conservée.","Les dommages sont photographiés et les justificatifs rassemblés.","La remise en état attend les consignes de l’assureur.","La garantie et les conditions de prise en charge sont vérifiées."],"sources":[{"kind":"inspiration","label":"La règle d’or — Dégât des eaux (transcription fournie par le lecteur ; repères 1:21, 2:19 et 2:27)","url":"https://www.youtube.com/watch?v=NcnPI8KRmyE"},{"kind":"reference","label":"Service-Public — Assurance dégâts des eaux","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F1352"},{"kind":"reference","label":"Service-Public — Expertise en assurance habitation","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F3075"},{"kind":"reference","label":"Service-Public — Indemnisation des catastrophes naturelles","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F3076"}],"order":168,"subcategory":"","homeRank":0,"themeId":"logement","tagSlugs":["logement"]}','{"kind":"guides","slug":"degat-des-eaux-bons-reflexes","title":"Dégât des eaux : agir vite et garder les preuves","description":"Limiter les dommages, prévenir son assurance et préparer un dossier clair sans effacer les preuves.","categoryId":"argent-consommation","reviewedAt":"2026-09-28","intro":"Une fuite demande deux réflexes complémentaires : empêcher les dégâts de s’aggraver et documenter ce qui s’est passé. Ce guide distingue les mesures urgentes de la remise en état, pour agir dans le bon ordre.","sections":[{"title":"Limiter les dégâts sans se mettre en danger","paragraphs":["Si vous pouvez le faire sans risque, fermez l’arrivée d’eau concernée. Si la fuite vient d’ailleurs, prévenez le voisin ou le syndic. Faites réparer la fuite rapidement ; ne manipulez pas d’installation électrique mouillée et sollicitez une intervention adaptée en cas de danger.","La réparation urgente de la fuite est différente de la réfection des peintures ou des sols. Pour cette remise en état, obtenez d’abord l’accord de votre assureur. Gardez les justificatifs des interventions urgentes."]},{"title":"Déclarer rapidement et décrire les faits","paragraphs":["Prévenez votre assureur dès la découverte. Le délai prévu au contrat ne peut en principe être inférieur à cinq jours ouvrés. Vérifiez ses modalités de déclaration. Un constat amiable peut faciliter le dossier, mais il n’est pas obligatoire.","Notez la date, les pièces touchées, les dommages visibles et les démarches entreprises. Distinguez les faits observés de vos suppositions : « de l’eau apparaît au plafond » ne permet pas encore d’affirmer quelle installation fuit. Conservez la confirmation de votre déclaration."]},{"title":"Photographier et conserver les éléments utiles","paragraphs":["Prenez des vues d’ensemble et des détails des dommages, sans vous exposer. Faites une liste des biens touchés et rassemblez les factures disponibles. Avant de jeter un objet endommagé, demandez les consignes de l’assureur ; la conservation des preuves ne doit pas créer de danger.","Exemple fictif : une fuite a détrempé un meuble. Photographiez son emplacement, les zones abîmées et son identification, puis ajoutez sa facture si vous l’avez. Un dossier organisé sera plus facile à examiner qu’une série de photos sans contexte."]},{"title":"Préparer l’expertise sans la présumer obligatoire","paragraphs":["L’expertise n’est pas systématique. Lorsqu’un expert intervient, il examine notamment les causes et les dommages. Préparez vos documents et signalez les éléments qui pourraient être oubliés. Le montant de 1 600 euros évoqué dans la transcription ne doit pas être présenté comme une obligation légale universelle d’expertise.","Si vous contestez ses conclusions, demandez des explications et renseignez-vous sur la contre-expertise. Vérifiez auparavant la prise en charge de ses frais dans votre contrat. Ne confondez pas le coût estimé des réparations et l’indemnité finalement proposée."]},{"title":"Vérifier la garantie mobilisée","paragraphs":["L’origine de l’eau, les exclusions et les franchises comptent : toute entrée d’eau ne garantit pas une indemnisation. Demandez à l’assureur quelle garantie il examine et quels documents il attend.","Une inondation relevant du régime des catastrophes naturelles obéit à des conditions spécifiques, notamment un arrêté de reconnaissance et une assurance ouvrant droit à cette garantie. Pour ce régime, la déclaration doit être faite au plus tard trente jours après la publication de l’arrêté. Une forte pluie ne suffit donc pas, à elle seule, à garantir la prise en charge."]}],"checklist":["La fuite et les dangers immédiats sont pris en charge.","La déclaration est transmise et sa confirmation conservée.","Les dommages sont photographiés et les justificatifs rassemblés.","La remise en état attend les consignes de l’assureur.","La garantie et les conditions de prise en charge sont vérifiées."],"sources":[{"kind":"inspiration","label":"La règle d’or — Dégât des eaux (transcription fournie par le lecteur ; repères 1:21, 2:19 et 2:27)","url":"https://www.youtube.com/watch?v=NcnPI8KRmyE"},{"kind":"reference","label":"Service-Public — Assurance dégâts des eaux","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F1352"},{"kind":"reference","label":"Service-Public — Expertise en assurance habitation","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F3075"},{"kind":"reference","label":"Service-Public — Indemnisation des catastrophes naturelles","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F3076"}],"order":168,"subcategory":"","homeRank":0,"themeId":"logement","tagSlugs":["logement"]}',1,'2026-10-01T06:41:56.605Z','migration');
