,"Les incertitudes importantes sont résolues avant l’engagement."],"sources":[{"label":"RTL — Voiture d’occasion : les conseils pour éviter les arnaques (2022)","url":"https://www.rtl.fr/actu/economie-consommation/voiture-d-occasion-carte-grise-controle-technique-les-conseils-pour-eviter-les-arnaques-7900165845","kind":"inspiration"},{"label":"Service-Public — HistoVec","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/R68264","kind":"reference"},{"label":"Service-Public — Vente et contrôle technique","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F16540","kind":"reference"}],"kind":"guides","categoryId":"argent-consommation","reviewedAt":"2026-09-27","order":170,"subcategory":"Acheter","homeRank":0,"themeId":"automobile","tagSlugs":["automobile"]}','migration','migration','2026-10-01T06:41:56.605Z');
INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/acheter-en-ligne-avec-methode','{"slug":"acheter-en-ligne-avec-methode","title":"Achat en ligne : vérifier avant de payer","description":"Identifier le vendeur, lire les conditions et conserver les preuves pour éviter un achat mal préparé.","intro":"Un site soigné, une promotion et des commentaires enthousiastes ne suffisent pas pour décider. Avant de payer, vérifiez à qui vous achetez, ce qui est vendu et comment la commande doit se dérouler.","sections":[{"title":"Identifier le vendeur réel","paragraphs":["Cherchez son identité et ses coordonnées. Sur une place de marché, distinguez la plateforme du vendeur de l’article. Consultez les conditions de vente, le pays d’établissement et les modalités de contact. Si ces éléments sont absents ou incohérents, interrompez votre achat pour vérifier."]},{"title":"Relire le panier sans se presser","paragraphs":["Contrôlez les caractéristiques, le montant final, la livraison et les frais de retour annoncés. Repérez les options ajoutées ou un éventuel abonnement. Le cadenas HTTPS protège la connexion, mais ne prouve pas à lui seul le sérieux du vendeur.","Exemple fictif : un produit paraît moins cher, mais le panier ajoute une livraison coûteuse et une option récurrente. Comparez le total réellement demandé avec votre besoin, plutôt que la réduction mise en avant."]},{"title":"Comprendre la possibilité de retour","paragraphs":["Pour un bien acheté à distance auprès d’un professionnel, le consommateur dispose en général de quatorze jours à compter de sa réception pour notifier sa rétractation. Il existe des exceptions, notamment pour certains biens personnalisés ou périssables. Ce droit ne s’applique pas de la même façon à une vente entre particuliers. Vérifiez les conditions applicables avant de commander."]},{"title":"Conserver les preuves et réagir par écrit","paragraphs":["Gardez la confirmation de commande, la description de l’offre et les justificatifs de paiement. Si la livraison ou le produit pose problème, rassemblez les faits et adressez une demande précise au vendeur. La fiche officielle sur les litiges en ligne indique les démarches possibles selon le problème.","Évitez de multiplier des messages dispersés : une chronologie avec les dates, les références et la réponse attendue permet de présenter clairement votre dossier. Ne transmettez pas vos codes bancaires à une personne qui prétend régler le litige."]}],"checklist":["Je sais qui est le vendeur.","J’ai vérifié le montant final et les options.","Les conditions de livraison et de retour sont lisibles.","Je connais les exceptions éventuelles à la rétractation.","Les preuves de commande et de paiement sont conservées."],"sources":[{"label":"RTL — Acheter sur Internet, La règle d’or (2022)","url":"https://www.rtl.fr/actu/economie-consommation/vente-en-ligne-que-faut-il-savoir-avant-d-acheter-sur-internet-7900141653","kind":"inspiration"},{"label":"DGCCRF — Acheter sur Internet de façon sécurisée","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/comment-realiser-des-achats-sur-internet-de-facon-securisee","kind":"reference"},{"label":"Ministère de l’Économie — Droit de rétractation","url":"https://www.economie.gouv.fr/particuliers/mes-droits-conso/bien-consommer/vente-distance-tout-savoir-sur-votre-droit-de-retractation","kind":"reference"},{"label":"Ministère de l’Économie — Litiges en ligne","url":"https://www.economie.gouv.fr/particuliers/mes-droits-conso/gerer-un-litige/achats-et-services-en-ligne-6-conseils-en-cas-de-litige","kind":"reference"}],"kind":"guides","categoryId":"argent-consommation","reviewedAt":"2026-09-27","order":171,"subcategory":"","homeRank":0,"themeId":"achats","tagSlugs":["achats"]}','{"slug":"acheter-en-ligne-avec-methode","title":"Achat en ligne : vérifier avant de payer","description":"Identifier le vendeur, lire les conditions et conserver les preuves pour éviter un achat mal préparé.","intro":"Un site soigné, une promotion et des commentaires enthousiastes ne suffisent pas pour décider. Avant de payer, vérifiez à qui vous achetez, ce qui est vendu et comment la commande doit se dérouler.","sections":[{"title":"Identifier le vendeur réel","paragraphs":["Cherchez son identité et ses coordonnées. Sur une place de marché, distinguez la plateforme du vendeur de l’article. Consultez les conditions de vente, le pays d’établissement et les modalités de contact. Si ces éléments sont absents ou incohérents, interrompez votre achat pour vérifier."]},{"title":"Relire le panier sans se presser","paragraphs":["Contrôlez les caractéristiques, le montant final, la livraison et les frais de retour annoncés. Repérez les options ajoutées ou un éventuel abonnement. Le cadenas HTTPS protège la connexion, mais ne prouve pas à lui seul le sérieux du vendeur.","Exemple fictif : un produit paraît moins cher, mais le panier ajoute une livraison coûteuse et une option récurrente. Comparez le total réellement demandé avec votre besoin, plutôt que la réduction mise en avant."]},{"title":"Comprendre la possibilité de retour","paragraphs":["Pour un bien acheté à distance auprès d’un professionnel, le consommateur dispose en général de quatorze jours à compter de sa réception pour notifier sa rétractation. Il existe des exceptions, notamment pour certains biens personnalisés ou périssables. Ce droit ne s’applique pas de la même façon à une vente entre particuliers. Vérifiez les conditions applicables avant de commander."]},{"title":"Conserver les preuves et réagir par écrit","paragraphs":["Gardez la confirmation de commande, la description de l’offre et les justificatifs de paiement. Si la livraison ou le produit pose problème, rassemblez les faits et adressez une demande précise au vendeur. La fiche officielle sur les litiges en ligne indique les démarches possibles selon le problème.","Évitez de multiplier des messages dispersés : une chronologie avec les dates, les références et la réponse attendue permet de présenter clairement votre dossier. Ne transmettez pas vos codes bancaires à une personne qui prétend régler le litige."]}],"checklist":["Je sais qui est le vendeur.","J’ai vérifié le montant final et les options.","Les conditions de livraison et de retour sont lisibles.","Je connais les exceptions éventuelles à la rétractation.","Les preuves de commande et de paiement sont conservées."],"sources":[{"label":"RTL — Acheter sur Internet, La règle d’or (2022)","url":"https://www.rtl.fr/actu/economie-consommation/vente-en-ligne-que-faut-il-savoir-avant-d-acheter-sur-internet-7900141653","kind":"inspiration"},{"label":"DGCCRF — Acheter sur Internet de façon sécurisée","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/comment-realiser-des-achats-sur-internet-de-facon-securisee","kind":"reference"},{"label":"Ministère de l’Économie — Droit de rétractation","url":"https://www.economie.gouv.fr/particuliers/mes-droits-conso/bien-consommer/vente-distance-tout-savoir-sur-votre-droit-de-retractation","kind":"reference"},{"label":"Ministère de l’Économie — Litiges en ligne","url":"https://www.economie.gouv.fr/particuliers/mes-droits-conso/gerer-un-litige/achats-et-services-en-ligne-6-conseils-en-cas-de-litige","kind":"reference"}],"kind":"guides","categoryId":"argent-consommation","reviewedAt":"2026-09-27","order":171,"subcategory":"","homeRank":0,"themeId":"achats","tagSlugs":["achats"]}',1,'2026-10-01T06:41:56.605Z','migration');
