INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/preparer-une-decision-importante','{"kind":"guides","slug":"preparer-une-decision-importante","title":"Préparer une décision importante","description":"Clarifier ses critères, comparer les options et savoir quand décider sans attendre une certitude parfaite.","categoryId":"argent-consommation","intro":"Vous hésitez entre deux offres, un changement de projet ou un achat qui vous engage. Le but de cette méthode est de rendre votre choix explicable : comprendre ce que vous cherchez, ce que vous acceptez et ce qui pourrait vous faire changer d’avis.","sections":[{"title":"Formuler le vrai besoin","paragraphs":["Écrivez la décision en une phrase, avec une échéance réelle. « Choisir un ordinateur pour mon travail avant la fin du mois » est plus utile que « trouver le meilleur ordinateur ». La première formulation donne un usage et une limite ; la seconde invite à comparer sans fin.","Distinguez ensuite ce qui est indispensable de ce qui est simplement agréable. Gardez trois critères essentiels, formulés de manière observable. Par exemple : faire fonctionner les logiciels utilisés, pouvoir transporter l’appareil et respecter une enveloppe définie à l’avance."]},{"title":"Comparer sur la même base","paragraphs":["Pour chaque option, reprenez les mêmes critères. Ajoutez le coût dans la durée, le temps de prise en main, les contraintes et la possibilité de revenir sur le choix. Notez aussi ce que vous ne savez pas encore : une case vide n’est pas une mauvaise note, c’est une question à poser.","Incluez une option souvent oubliée : conserver la situation actuelle. Elle peut avoir un coût ou des inconvénients, mais elle permet de vérifier si le changement répond à un besoin ou seulement à une envie du moment."]},{"title":"Chercher ce qui pourrait invalider votre préférence","paragraphs":["Une fois votre favori identifié, cherchez volontairement son principal défaut. Quelle contrainte rendrait ce choix inadapté ? Quelle information vous manque pour le savoir ? Contactez la personne qui peut répondre, plutôt que de continuer à accumuler des comparatifs généraux.","Exemple : un outil semble idéal, mais l’export des données est incertain. Tester cet export sur quelques fichiers apporte une information plus décisive qu’une nouvelle présentation commerciale."]},{"title":"Décider et garder une trace","paragraphs":["Résumez votre choix, les raisons et les limites acceptées. Si la décision est réversible, prévoyez une période d’essai avec un critère concret de réussite. Si elle vous engage longtemps, prenez le temps de vérifier les conditions et de solliciter un avis adapté à l’enjeu.","Une décision peut être raisonnable sans garantir un résultat parfait. Lors du bilan, comparez ce que vous pouviez savoir au moment du choix et ce que vous avez appris ensuite. Cela vous aidera davantage que de juger uniquement le résultat."]}],"checklist":["Mon besoin tient en une phrase.","Mes critères essentiels sont explicites.","J’ai comparé les coûts et contraintes sur la même durée.","J’ai vérifié le principal point d’incertitude.","Je sais quand et comment réévaluer mon choix."],"order":172,"subcategory":"","homeRank":0,"themeId":"travail","tagSlugs":["decisions"]}','{"kind":"guides","slug":"preparer-une-decision-importante","title":"Préparer une décision importante","description":"Clarifier ses critères, comparer les options et savoir quand décider sans attendre une certitude parfaite.","categoryId":"argent-consommation","intro":"Vous hésitez entre deux offres, un changement de projet ou un achat qui vous engage. Le but de cette méthode est de rendre votre choix explicable : comprendre ce que vous cherchez, ce que vous acceptez et ce qui pourrait vous faire changer d’avis.","sections":[{"title":"Formuler le vrai besoin","paragraphs":["Écrivez la décision en une phrase, avec une échéance réelle. « Choisir un ordinateur pour mon travail avant la fin du mois » est plus utile que « trouver le meilleur ordinateur ». La première formulation donne un usage et une limite ; la seconde invite à comparer sans fin.","Distinguez ensuite ce qui est indispensable de ce qui est simplement agréable. Gardez trois critères essentiels, formulés de manière observable. Par exemple : faire fonctionner les logiciels utilisés, pouvoir transporter l’appareil et respecter une enveloppe définie à l’avance."]},{"title":"Comparer sur la même base","paragraphs":["Pour chaque option, reprenez les mêmes critères. Ajoutez le coût dans la durée, le temps de prise en main, les contraintes et la possibilité de revenir sur le choix. Notez aussi ce que vous ne savez pas encore : une case vide n’est pas une mauvaise note, c’est une question à poser.","Incluez une option souvent oubliée : conserver la situation actuelle. Elle peut avoir un coût ou des inconvénients, mais elle permet de vérifier si le changement répond à un besoin ou seulement à une envie du moment."]},{"title":"Chercher ce qui pourrait invalider votre préférence","paragraphs":["Une fois votre favori identifié, cherchez volontairement son principal défaut. Quelle contrainte rendrait ce choix inadapté ? Quelle information vous manque pour le savoir ? Contactez la personne qui peut répondre, plutôt que de continuer à accumuler des comparatifs généraux.","Exemple : un outil semble idéal, mais l’export des données est incertain. Tester cet export sur quelques fichiers apporte une information plus décisive qu’une nouvelle présentation commerciale."]},{"title":"Décider et garder une trace","paragraphs":["Résumez votre choix, les raisons et les limites acceptées. Si la décision est réversible, prévoyez une période d’essai avec un critère concret de réussite. Si elle vous engage longtemps, prenez le temps de vérifier les conditions et de solliciter un avis adapté à l’enjeu.","Une décision peut être raisonnable sans garantir un résultat parfait. Lors du bilan, comparez ce que vous pouviez savoir au moment du choix et ce que vous avez appris ensuite. Cela vous aidera davantage que de juger uniquement le résultat."]}],"checklist":["Mon besoin tient en une phrase.","Mes critères essentiels sont explicites.","J’ai comparé les coûts et contraintes sur la même durée.","J’ai vérifié le principal point d’incertitude.","Je sais quand et comment réévaluer mon choix."],"order":172,"subcategory":"","homeRank":0,"themeId":"travail","tagSlugs":["decisions"]}',1,'2026-10-01T06:41:56.605Z','migration');
