INSERT OR IGNORE INTO content(id,draft_json,published_json,version,updated_at,updated_by) VALUES('guides/tester-une-idee-avant-de-la-developper','{"kind":"guides","slug":"tester-une-idee-avant-de-la-developper","title":"Tester une idée avant de la développer","description":"Transformer une intuition en une petite expérience, avec une question précise et un bilan honnête.","categoryId":"entrepreneuriat","intro":"Une idée peut paraître évidente à celui qui la porte et rester floue pour ceux à qui elle s’adresse. Avant de construire une solution complète, cherchez une façon simple d’observer le problème et de tester votre proposition.","sections":[{"title":"Décrire une situation, pas un public abstrait","paragraphs":["« Les petites entreprises » est un ensemble trop large pour commencer. Décrivez plutôt une personne dans une situation concrète : un indépendant qui perd du temps à retrouver les documents d’un projet, par exemple. Demandez comment il s’y prend aujourd’hui, ce qui bloque et quelles conséquences cela a.","Évitez de présenter immédiatement votre solution. Une conversation sur les habitudes réelles vous apprend autre chose qu’une réponse polie à la question « trouvez-vous mon idée intéressante ? ». Notez les exemples précis et les mots employés."]},{"title":"Choisir une seule hypothèse","paragraphs":["Écrivez ce qui doit être vrai pour que votre projet soit utile. Par exemple : les personnes concernées rencontrent ce problème chaque semaine et acceptent d’essayer une nouvelle façon de travailler. Vous pourrez tester d’autres points ensuite ; les mélanger rend le résultat difficile à interpréter.","Définissez avant l’essai ce que vous observerez. Un rendez-vous accepté, un document réellement confié ou l’utilisation répétée d’une maquette sont des comportements. Un compliment est encourageant, mais ne prouve pas qu’une solution sera utilisée."]},{"title":"Faire le plus petit essai honnête","paragraphs":["Une démonstration, un prototype papier ou un service réalisé manuellement peuvent suffire. Dites clairement ce qui fonctionne, ce qui est simulé et ce qui n’existe pas encore. Ne promettez pas une disponibilité ou une automatisation que vous ne pouvez pas assurer.","Fixez une durée et une limite de moyens. Pour un essai de classement de documents, vous pourriez travailler sur un petit jeu de données fictives avec quelques personnes volontaires. L’objectif est d’apprendre sur l’usage, pas de donner l’apparence d’un produit terminé."]},{"title":"Décider de la suite à partir des observations","paragraphs":["Séparez ce que vous avez observé de votre interprétation. « Deux personnes ont essayé une fois » ne signifie pas « le besoin est validé ». Demandez ce qui a empêché de recommencer et comparez ces réponses à votre hypothèse initiale.","Votre bilan peut conduire à poursuivre, modifier le public visé, simplifier la proposition ou arrêter. Gardez une courte trace du test et de ses limites. Une expérience modeste n’établit pas la taille d’un marché ; elle permet de choisir une prochaine étape plus informée."]}],"checklist":["Le problème correspond à une situation réelle.","Une seule hypothèse guide mon essai.","Le comportement attendu est défini à l’avance.","Les participants savent ce qui est expérimental.","Une date de bilan et une limite de moyens sont fixées."],"order":174,"subcategory":"","homeRank":0,"themeId":"projets","tagSlugs":["entreprendre"]}','{"kind":"guides","slug":"tester-une-idee-avant-de-la-developper","title":"Tester une idée avant de la développer","description":"Transformer une intuition en une petite expérience, avec une question précise et un bilan honnête.","categoryId":"entrepreneuriat","intro":"Une idée peut paraître évidente à celui qui la porte et rester floue pour ceux à qui elle s’adresse. Avant de construire une solution complète, cherchez une façon simple d’observer le problème et de tester votre proposition.","sections":[{"title":"Décrire une situation, pas un public abstrait","paragraphs":["« Les petites entreprises » est un ensemble trop large pour commencer. Décrivez plutôt une personne dans une situation concrète : un indépendant qui perd du temps à retrouver les documents d’un projet, par exemple. Demandez comment il s’y prend aujourd’hui, ce qui bloque et quelles conséquences cela a.","Évitez de présenter immédiatement votre solution. Une conversation sur les habitudes réelles vous apprend autre chose qu’une réponse polie à la question « trouvez-vous mon idée intéressante ? ». Notez les exemples précis et les mots employés."]},{"title":"Choisir une seule hypothèse","paragraphs":["Écrivez ce qui doit être vrai pour que votre projet soit utile. Par exemple : les personnes concernées rencontrent ce problème chaque semaine et acceptent d’essayer une nouvelle façon de travailler. Vous pourrez tester d’autres points ensuite ; les mélanger rend le résultat difficile à interpréter.","Définissez avant l’essai ce que vous observerez. Un rendez-vous accepté, un document réellement confié ou l’utilisation répétée d’une maquette sont des comportements. Un compliment est encourageant, mais ne prouve pas qu’une solution sera utilisée."]},{"title":"Faire le plus petit essai honnête","paragraphs":["Une démonstration, un prototype papier ou un service réalisé manuellement peuvent suffire. Dites clairement ce qui fonctionne, ce qui est simulé et ce qui n’existe pas encore. Ne promettez pas une disponibilité ou une automatisation que vous ne pouvez pas assurer.","Fixez une durée et une limite de moyens. Pour un essai de classement de documents, vous pourriez travailler sur un petit jeu de données fictives avec quelques personnes volontaires. L’objectif est d’apprendre sur l’usage, pas de donner l’apparence d’un produit terminé."]},{"title":"Décider de la suite à partir des observations","paragraphs":["Séparez ce que vous avez observé de votre interprétation. « Deux personnes ont essayé une fois » ne signifie pas « le besoin est validé ». Demandez ce qui a empêché de recommencer et comparez ces réponses à votre hypothèse initiale.","Votre bilan peut conduire à poursuivre, modifier le public visé, simplifier la proposition ou arrêter. Gardez une courte trace du test et de ses limites. Une expérience modeste n’établit pas la taille d’un marché ; elle permet de choisir une prochaine étape plus informée."]}],"checklist":["Le problème correspond à une situation réelle.","Une seule hypothèse guide mon essai.","Le comportement attendu est défini à l’avance.","Les participants savent ce qui est expérimental.","Une date de bilan et une limite de moyens sont fixées."],"order":174,"subcategory":"","homeRank":0,"themeId":"projets","tagSlugs":["entreprendre"]}',1,'2026-10-01T06:41:56.605Z','migration');
